window.__ARXIV_DATA__ = {"papers":[{"id":"2611.05377v1","title":"DreamX: Video Diffusion Model is a Universal Latent Action Learner","abstract":"Learning a universal action representation from video requires modeling dynamics that are consistent across different executions of the same action yet invariant to changes in embodiment and appearance. Existing latent action models infer actions from visual transitions, but their representations often entangle the underlying action with irrelevant visual variations, limiting transfer across embodiments. We introduce DreamX, which repurposes a pretrained video diffusion model as a universal latent action learner. Our approach extracts compact latent actions from the video model's rich spatiotemporal features, compressing each latent video frame by $\\boldsymbol{300\\times}$ ($\\boldsymbol{1{,}200 \\rightarrow 4}$ tokens). In addition, by leveraging the video model's generative prior, these latent actions capture action-relevant dynamics disentangled from visual appearance. The resulting latent space serves as a shared action interface across embodiments (human and robot), environments, and action parameterizations. On LARY-Bench, DreamX achieves state-of-the-art performance among latent action models. Moreover, actions encoded in one setting remain effective in another: the latent space supports any-to-any video transfer and zero-shot action transfer across diverse embodiments and environments. Furthermore, this shared interface also enables policy learning in a compact latent action space, reducing the computational cost of video-diffusion-based policies.","authors":["Jisoo Kim","Chaehyun Kim","Junsu Kim","Jiho Park","Seongchan Kim","Eunbeen Hong","Soowon Son","Fu-En Yang","Seungryong Kim"],"published":"2026-11-03T18:59:56Z","updated":"2026-11-03T18:59:56Z","abstract_url":"https://arxiv.org/abs/2611.05377v1","html_url":"https://arxiv.org/html/2611.05377v1","pdf_url":"https://arxiv.org/pdf/2611.05377v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"html","source_text_chars":66352,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, diffusion 相关；摘要显示其主要贡献为：Learning a universal action representation from video requires modeling dynamics that are consistent across different executions of the same action yet invariant to changes in embodiment and appearance. Existing latent action models infer actions from visual...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05361v1","title":"Visibility-Aware Reference Generation for Benchmarking Visual 3D Reconstruction in Vegetation-Rich Environments","abstract":"Reliable evaluation of visual 3D reconstruction and depth estimation in vegetation-rich outdoor environments is limited by the scarcity of geometric ground-truth data and the cost of complete scanner surveys. We present a LiDARbased reference-generation pipeline for evaluating the zero-shot performance of feed-forward visual-geometry models alongside conventional structure-from-motion (SfM) methods. The pipeline reuses camera images, LiDAR scans, and reference poses from existing multi-sensor localization datasets to generate per-view depth maps and visible reference point clouds. To address visibility errors in accumulated LiDAR scans, we introduce the LargeDepth-Gap Visibility Score (LDGVS) for point-wise visibility filtering and automatic scale selection in Hidden Point Removal(HPR). Experiments on TartanAirV2 and TartanGround show that, compared with Poisson surface reconstruction, which is an approach suited to completed scan surveys, the combined HPR and LDGVS filtering retains approximately three times the point density at comparable absolute relative error. We also apply the pipeline to the BotanicGarden dataset to systematically compare depth estimation and 3D reconstruction methods. Feedforward methods produce dense depth predictions efficiently, but their 3D reconstructions can contain duplicated structures. Conventional SfM generally produces more coherent geometry, but its reconstructions remain sparse and more prone to failure in challenging vegetated scenes. The benchmark toolkit and datasets will be released.","authors":["Zhipeng Zhong","Matthew Coombes","Cunjia Liu"],"published":"2026-11-03T18:54:52Z","updated":"2026-11-03T18:54:52Z","abstract_url":"https://arxiv.org/abs/2611.05361v1","html_url":"https://arxiv.org/html/2611.05361v1","pdf_url":"https://arxiv.org/pdf/2611.05361v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":100152,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Reliable evaluation of visual 3D reconstruction and depth estimation in vegetation-rich outdoor environments is limited by the scarcity of geometric ground-truth data and the cost of complete scanner surveys. We present a LiDARbased reference-generation pipel...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05359v1","title":"GSCV++: Lightweight 3D Gaussian Splatting Sequence Compression via Standard Video Codecs","abstract":"This paper presents GSCV++, a lightweight pipeline for 3D {G}aussian {S}platting (GS) sequences {C}ompression with standard {V}ideo codecs. To meet the requirements of low-complexity and hardware compatibility from the industry, GSCV++ jointly improves preprocessing, 3D-to-2D mapping, and practical video compression configuration of GS compression. First, for preprocessing, energy-adaptive inter-frame spherical harmonic (SH) alternative current (AC) dimensionality reduction (EA-SHDR) is proposed to produces a compact and stable temporal SH AC feature space. It can reduce the data volume of following mapping and practical compression, as well as less complexity while eliminating redundant information. Second, for 3D-to-2D mapping, prior-based Inter-MiniPLAS (P-MiniPLAS) is designed to generate smooth 2D feature maps through prior-based weighting factor inference and small scale remapping. Compared with vanilla Parallel Linear Assignment Sorting (PLAS) and Morton scan, P-MiniPLAS ensures the generated 2D maps are more suitable for the video codec while maintaining a low level of computational complexity. Third, for practical compression, content-aware generalized compression (CA-GC) is developed to use a non-uniform bit-depth split for coordinate map generation, and a coding unit size selection is introduced for efficient compression complexity control, which fully exploits the performance of video codecs without involving normative changes. Experiments demonstrate that GSCV++ reports over 20\\% in intra- and 60\\% in inter-prediction rate-distortion gains compared with state-of-the-art (SOTA) methods. GSCV++ also achieves faster 2D map generation, encoding, and decoding than other SOTA methods using the same type of video codecs. Ablation studies verify the effectiveness and robustness of the proposed modules and provide insights for subsequent research.","authors":["Qi Yang","Yingzhan Xu","Kai Zhang","Li Zhang"],"published":"2026-11-03T18:54:29Z","updated":"2026-11-03T18:54:29Z","abstract_url":"https://arxiv.org/abs/2611.05359v1","html_url":"https://arxiv.org/html/2611.05359v1","pdf_url":"https://arxiv.org/pdf/2611.05359v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":1973,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：This paper presents GSCV++, a lightweight pipeline for 3D {G}aussian {S}platting (GS) sequences {C}ompression with standard {V}ideo codecs. To meet the requirements of low-complexity and hardware compatibility from the industry, GSCV++ jointly improves prepro...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05291v1","title":"Low-Density 3D Point Cloud Classification","abstract":"3D point cloud classification, a task in computer vision, has recently gained substantial interest due to its extensive applications across various domains such as augmented and virtual reality, robotics, and autonomous driving. However, classifying 3D point clouds becomes challenging in real-world scenarios where the density levels vary. These variations are due to limitations inherent to current sensing technologies and variable environmental conditions, which often prevent the capture of detailed and comprehensive geometric representations. Existing classification methods, which have demonstrated impressive results on dense point clouds, may be affected and could experience reduced performance when dealing with low-density point clouds. Addressing this challenge, this paper introduces LD-PointNet++, an architecture optimized for the classification of low-density point clouds. To pave the way for LD-PointNet++, we conduct the first benchmarking study that systematically evaluates state-of-the-art point cloud classification methods across varying densities, revealing significant performance declines in low-density environments. Experimental results on the ModelNet benchmark dataset demonstrate that LD-PointNet++ not only outperforms these methods in low-density scenarios but also demonstrates consistent accuracy above 90% across different density levels.","authors":["Ahmed Baha Ben Jmaa","Faten Chaieb"],"published":"2026-11-03T18:07:11Z","updated":"2026-11-03T18:07:11Z","abstract_url":"https://arxiv.org/abs/2611.05291v1","html_url":"https://arxiv.org/html/2611.05291v1","pdf_url":"https://arxiv.org/pdf/2611.05291v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":39741,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：3D point cloud classification, a task in computer vision, has recently gained substantial interest due to its extensive applications across various domains such as augmented and virtual reality, robotics, and autonomous driving. However, classifying 3D point...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05280v1","title":"YANAMI: A Large-Scale Multimodal Dataset and Benchmark for Multiturn Stateful Interaction","abstract":"Unified Multimodal Models (UMMs) integrate visual understanding, generation, and editing within a single unified framework. However, existing unified multimodal datasets and benchmarks remain dominated by single-turn tasks. Even in recent multi-turn datasets, many turns can be solved independently without tracking information across turns. Consequently, they provide limited supervision and evaluation for multimodal stateful interaction, which requires models to understand, maintain, update, and faithfully realize evolving dialogue states across turns. To address this gap, we introduce YANAMI, the first large-scale multimodal dialogue dataset and benchmark for stateful interaction, comprising YANAMI-400K and YANAMI-Bench. YANAMI-400K contains 400K multi-turn multimodal dialogues, with more than 2M images and 2.6M dialogue turns. The dialogues span four representative scenarios: Multi-Image Fusion, Image Editing, World Modeling, and Visual Reasoning, and require models to continuously track, preserve, and revise evolving multimodal dialogue states across turns. YANAMI-Bench comprises 400 multi-turn dialogues for systematically evaluating multimodal stateful interaction. It jointly evaluates Dialogue State Understanding and Visual Realization, characterizing the gap between models' ability to understand evolving dialogue states and their ability to faithfully realize them in visual outputs. Experiments show that fine-tuning BAGEL on YANAMI-400K improves image editing, generation, and multimodal stateful interaction by 10.3%, 2.0%, and 13.23%, respectively, while preserving its general visual understanding capabilities. Evaluations on YANAMI-Bench further reveal that existing UMMs still struggle to maintain, update, and visually realize evolving multimodal dialogue states.","authors":["Shengyu Wang","Tengyue Nong","Junming Liu","Haosong Peng","Siyu Li","Ruiqi Lei","Fushuo Huo","Yuhao Pan","Yunfeng Fan","Ding Wang","Nan Cheng","Haozhao Wang","Wenchao Xu"],"published":"2026-11-03T17:59:36Z","updated":"2026-11-03T17:59:36Z","abstract_url":"https://arxiv.org/abs/2611.05280v1","html_url":"https://arxiv.org/html/2611.05280v1","pdf_url":"https://arxiv.org/pdf/2611.05280v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":108524,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Unified Multimodal Models (UMMs) integrate visual understanding, generation, and editing within a single unified framework. However, existing unified multimodal datasets and benchmarks remain dominated by single-turn tasks. Even in recent multi-turn datasets,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05279v1","title":"Möbius: A Unified Motion-Language Model Bridging Understanding and Generation","abstract":"We aim to build a truly unified motion model that can understand, generate, and edit human motion within a single framework. Existing motion UMMs remain only partially unified: motion understanding is handled by a language model, while generation is often delegated to a separate diffusion module operating over learned motion latents. We introduce Möbius, which brings the entire diffusion process into the same multimodal representation space used for motion understanding. Clean motion, noisy motion, and text jointly participate in shared attention, while role-specific parameters process understanding and generation streams. Importantly, Möbius operates directly on continuous frame-level raw motion, requiring neither discrete tokenization nor a pretrained motion VAE. This simple formulation naturally supports motion captioning, text-to-motion generation, temporal completion, and instruction-guided editing within a single model. On HumanML3D, Möbius achieves state-of-the-art performance among unified motion models. Scaling to 1.7B parameters and 1,700 hours of motion data further demonstrates that our framework is both effective and scalable.","authors":["Jiazhi Shu","Chengfeng Zhao","Jinyi Wang","Yubo Zhao","Zhiyang Dou","Ronghui Li","Yu Lu","Xinwei Jiang","Zijiao Zeng","Yuan Liu"],"published":"2026-11-03T17:59:16Z","updated":"2026-11-03T17:59:16Z","abstract_url":"https://arxiv.org/abs/2611.05279v1","html_url":"https://arxiv.org/html/2611.05279v1","pdf_url":"https://arxiv.org/pdf/2611.05279v1.pdf","matched_keywords":["3d","representation","multimodal","diffusion"],"source_used":"html","source_text_chars":69653,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal, diffusion 相关；摘要显示其主要贡献为：We aim to build a truly unified motion model that can understand, generate, and edit human motion within a single framework. Existing motion UMMs remain only partially unified: motion understanding is handled by a language model, while generation is often del...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05275v1","title":"Route Anything: A Study of Model and Policy Routing for General-Purpose AI Systems","abstract":"Artificial general intelligence (AGI) requires a method that can understand, generate, reason, and act across diverse domains and modalities. Rather than relying on a single model to master every capability, a promising path toward AGI now is to orchestrate a heterogeneous ecosystem of specialized models, tools, and policies (candidates) into a unified AI system. At the heart of this vision lies a fundamental question: how can an AI system dynamically select and coordinate the most capable candidate for each task while balancing performance and computational cost? In this work, we present Route Anything, a unified framework for studying model and policy routing across general-purpose AI systems. We develop a unified theoretical foundation that characterizes optimal routing under quality--cost trade-offs and establishes how the information available to a router determines its attainable performance. To systematically investigate routing across diverse capabilities, we first construct an omni-modal trajectory matrix spanning 25 benchmarks across language understanding, image, video, and speech generation, coding and workplace agents, and robotic manipulation, comprising 374,401 scored runs from 452 candidate configurations. Building on this framework, we train and test different routers to investigate the potential of omni-modal model routing, the capabilities of learned routers, and the conditions under which routing improves efficiency. Our results reveal substantial opportunities for capability orchestration: per-input oracle routing outperforms the best fixed candidate by 5.4 points, and learned routers outperform it by 0.3 points across 16 benchmarks, by 2.1 points on video generation, and by 1.1 points on robot manipulation while using 24% less policy time. More importantly, routing raises efficiency by 8.82x on average compared with the reference model.","authors":["Pengfei Zhou","Yixing Ma","Hexin Wang","Weidong Tang","Zhenglin Wan","Wangbo Zhao","Yang You"],"published":"2026-11-03T17:56:42Z","updated":"2026-11-03T17:56:42Z","abstract_url":"https://arxiv.org/abs/2611.05275v1","html_url":"https://arxiv.org/html/2611.05275v1","pdf_url":"https://arxiv.org/pdf/2611.05275v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":133164,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：Artificial general intelligence (AGI) requires a method that can understand, generate, reason, and act across diverse domains and modalities. Rather than relying on a single model to master every capability, a promising path toward AGI now is to orchestrate a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05231v1","title":"Diagnosis by Composition: Detecting and Localizing Unseen Diseases by Composing Learned Radiological Findings","abstract":"Deep models for radiological diagnosis are typically trained to predict disease labels directly from images, which limits them to diseases seen during training and makes their decisions hard to interpret in radiologists' terms. Radiology, however, proceeds from visual findings to disease through published guidelines that make this decision rule explicit, interpretable, and reproducible. We introduce diagnosis by composition (DbC), a representation learning framework that encodes this findings-first logic. DbC learns a vocabulary of radiological findings by aligning image features with the text embeddings of the findings, each finding represented as a dense map over the scan. A disease is defined by a set of required findings derived from its guidelines, and its diagnosis map is a fixed, parameter-free composition of the corresponding finding maps. Because the finding-to-disease mapping is derived from guidelines rather than learned, DbC is interpretable and auditable by design, can extend to new diseases by specifying their findings without retraining, and can diagnose unseen diseases by composing their findings. On multi-phase liver CT, DbC detects and localizes unseen diseases, rare diseases from a different institution, and an external cohort significantly better than all comparators, including models that align images with disease names. DbC also improves detection and localization in the fully supervised setting and remains superior across training-set sizes. Although demonstrated on liver CT, DbC applies wherever radiological guidelines define diseases through findings.","authors":["Kaihua Hou","Wei Liu","Yi Huang","Hao Zhang","Haibo Jin","Yifei Sun","Yuan gao","Zuoou Li","Ling Zhang","Ahmed Alaa","Geoffrey H. Tison","Xu Han","Ke Yan"],"published":"2026-11-03T17:14:51Z","updated":"2026-11-03T17:14:51Z","abstract_url":"https://arxiv.org/abs/2611.05231v1","html_url":"https://arxiv.org/html/2611.05231v1","pdf_url":"https://arxiv.org/pdf/2611.05231v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":99002,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Deep models for radiological diagnosis are typically trained to predict disease labels directly from images, which limits them to diseases seen during training and makes their decisions hard to interpret in radiologists' terms. Radiology, however, proceeds fr...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05206v1","title":"Diffusion Plug-in Priors for Self-Supervised Ultrasound Video Restoration","abstract":"\\textit{Objective:} Ultrasound videos are limited by hardware-constrained spatial resolution and signal-dependent speckle, while paired low- and high-resolution acquisitions for supervised restoration are rarely available. We aim to jointly super-resolve and despeckle ultrasound videos without paired training data or network retraining. \\textit{Methods:} We propose UltraDiff, which uses a frozen pre-trained diffusion model (DM) as a plug-in prior and restores each frame by optimizing the latent seed of the DM sampler under a range-constrained maximum a posteriori formulation. We derive a speckle-aware data-fidelity term from a Rayleigh scale-family model and characterize its relative-residual and variance-adaptive weighting properties. We further introduce a stabilized fidelity that is bounded below and strictly convex in log intensity for positive observations in its unclamped form. A total-variation regularizer complements the DM prior, and a temporal seed update warm-starts each frame from the optimized seed of its predecessor. \\textit{Results:} On EchoNet-LVH videos with simulated speckle and additive noise, UltraDiff with a natural-image prior improves PSNR by 1.24\\,dB over the strongest baseline, and ultrasound-related priors improve it further. On real clinical echocardiography videos, UltraDiff reduces the mean absolute error of zero-shot ejection fraction (EF) prediction from 7.31 to 6.37 EF points relative to DUP, the strongest baseline. \\textit{Conclusion:} Combining a speckle-aware fidelity with frozen diffusion priors enables ground-truth-free ultrasound video restoration that benefits downstream measurement. \\textit{Significance:} UltraDiff needs neither paired data nor retraining and is not tied to a specific diffusion checkpoint. Code associated with this work will be made publicly available upon acceptance.","authors":["Chu Chen","Mingduo He","Yining Li","Yinhao Wu","Wei Tang","Yiwen Luo","Yixuan Chen","Graham Treece","Pasquale Cascarano","Kangning Cui"],"published":"2026-11-03T16:55:01Z","updated":"2026-11-03T16:55:01Z","abstract_url":"https://arxiv.org/abs/2611.05206v1","html_url":"https://arxiv.org/html/2611.05206v1","pdf_url":"https://arxiv.org/pdf/2611.05206v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":54147,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：\\textit{Objective:} Ultrasound videos are limited by hardware-constrained spatial resolution and signal-dependent speckle, while paired low- and high-resolution acquisitions for supervised restoration are rarely available. We aim to jointly super-resolve and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05197v1","title":"Robust Reconstruction of Power Lines from Incomplete Mobile and Aerial LiDAR Data","abstract":"Accurate vegetation-encroachment assessment and risk mitigation require electric utilities to accurately locate and characterize distribution-network assets, including poles and power lines, and distinguish among medium-voltage, low-voltage, neutral, and telecommunication lines. Mobile and aerial Light Detection and Ranging (LiDAR) point clouds provide detailed 3D representations of these assets and their surroundings. However, power-line detection and reconstruction remain challenging because conductor returns are often sparse, incomplete, noisy, or occluded by vegetation. These challenges are especially significant in distribution networks, where lower pole heights and complex line configurations place conductors close to trees. In addition, mobile and aerial LiDAR datasets differ substantially in point density, viewing geometry, spatial coverage, and occlusion patterns. We propose a robust and automated reconstruction method combining scaled density-based clustering, robust polynomial fitting, and iterative fragment merging to recover individual conductors under severe data incompleteness and occlusion. Following semantic classification, the same reconstruction pipeline processes both mobile and aerial LiDAR data without modality-specific code or parameter tuning. The method is evaluated through degradation experiments, benchmarking, parameter sensitivity analysis, and large-scale validation. On the aerial dataset, it achieves 96.87% precision, 96.66% recall, a 96.76% F$_1$-score, and a geometric RMSE of 0.127 m. On the mobile dataset, where conductor-level reference annotations were unavailable, it achieves a point-to-model RMSE of 0.045 m and a reconstruction coverage of 95.27%. Source code, documentation, and evaluation data are publicly available at https://github.com/varen-project.","authors":["Mohamed Gaha","Damos Ayobo Abongo","Philippe Massicotte","Eya Ben Kacem","Wael Jaafar","Rami Langar","Christian Buteau"],"published":"2026-11-03T16:48:56Z","updated":"2026-11-03T16:48:56Z","abstract_url":"https://arxiv.org/abs/2611.05197v1","html_url":"https://arxiv.org/html/2611.05197v1","pdf_url":"https://arxiv.org/pdf/2611.05197v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":79858,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Accurate vegetation-encroachment assessment and risk mitigation require electric utilities to accurately locate and characterize distribution-network assets, including poles and power lines, and distinguish among medium-voltage, low-voltage, neutral, and tele...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05193v1","title":"Factorized MLLM Embeddings for Composed Image Retrieval","abstract":"Composed Image Retrieval (CIR) aims to retrieve a target image given a reference image and a modification text. Although recent approaches leveraging Multimodal Large Language Models (MLLMs) have shown significant progress, we argue that the MLLM's compositional understanding remains underutilized. This stems from directly mapping composed queries into a retrieval embedding via contrastive supervision alone, without explicitly resolving the intended visual modifications. In this work, we introduce Factorized MLLM Embeddings (FactEmbed), which decouples compositional query comprehension from building discriminative embeddings. Rather than directly projecting the composed query into a single embedding without internal reasoning, FactEmbed employs a set of factorized latents that simulate the intended visual modifications via an intermediate target imagination objective. This process encourages the latents to ground into target semantics before forming discriminative representations for retrieval. Subsequently, to propagate these factorized representations throughout the model for retrieval, we optimize a factor-level contrastive loss while distilling the decomposed representations into a deeper attention layer of the MLLM. Finally, for efficient inference, we retain the [EOS] token to establish a global-level embedding on top of these factorized latents, while we exploit the mean-pooled factorized latents to rerank a short candidate list at negligible cost, as both are produced by the same forward pass. Extensive evaluations demonstrate that FactEmbed outperforms prior works across CIR benchmarks.","authors":["WonJun Moon","Seongchan Kim","Dahun Kim","Seungryong Kim"],"published":"2026-11-03T16:46:45Z","updated":"2026-11-03T16:46:45Z","abstract_url":"https://arxiv.org/abs/2611.05193v1","html_url":"https://arxiv.org/html/2611.05193v1","pdf_url":"https://arxiv.org/pdf/2611.05193v1.pdf","matched_keywords":["retrieval","representation","multimodal"],"source_used":"html","source_text_chars":90388,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, representation, multimodal 相关；摘要显示其主要贡献为：Composed Image Retrieval (CIR) aims to retrieve a target image given a reference image and a modification text. Although recent approaches leveraging Multimodal Large Language Models (MLLMs) have shown significant progress, we argue that the MLLM's compositio...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05192v1","title":"From Natural Images to Medical Scans: Transferability of Diffusion Models for Medical Image Generation","abstract":"Transfer learning from natural images is standard in supervised and increasingly adopted in self-supervised medical image analysis, but its role in generative modelling, and in particular diffusion denoisers, remains underexplored. Medical diffusion models typically train the denoiser from scratch, with no systematic evaluation of natural-image transfer. We analyse this across latent and pixel paradigms, model sizes (131M-952M) and two radiology datasets (RadImageNet, BraTS), and ask which aspects of transfer support generation. We find that: i) Natural-image initialisation consistently improves generation, by 21-34% relative gFID in pixel space against 14% in latent space, where the tokeniser supplies much of the prior. gFID gains mirror downstream pathology classification and radiomic-feature FD, both proxies for clinical fidelity. ii) Benefits reflect spatial structure, not semantics: semantic probing does not predict generation quality, whereas a spatial-structure metric adapted to internal denoiser representations tracks gFID at $|r|=0.85$, positioning spatial organisation as a channel through which pretraining manifests. iii) Mixed-domain denoiser training shows that natural and medical images share similar layer-wise representations up to the late blocks, and mixing natural images into medical training improves fidelity. iv) Transfer benefit is tied to natural image initialisation, outperforming in-domain medical pretraining and several reinitialisation schemes. Overall, natural image denoisers transfer positively to medical ones in our setup. Code is available at https://github.com/CAIROLab-Bern/rad-dit","authors":["Efthymios Georgiou","Ioannis Kakogeorgiou","Sarah Brüningk"],"published":"2026-11-03T16:46:15Z","updated":"2026-11-03T16:46:15Z","abstract_url":"https://arxiv.org/abs/2611.05192v1","html_url":"https://arxiv.org/html/2611.05192v1","pdf_url":"https://arxiv.org/pdf/2611.05192v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":74742,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Transfer learning from natural images is standard in supervised and increasingly adopted in self-supervised medical image analysis, but its role in generative modelling, and in particular diffusion denoisers, remains underexplored. Medical diffusion models ty...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05181v1","title":"What Does the Model See? Representation Validity in Multimodal LLM-Based Video Analysis","abstract":"Multimodal large language models (MLLMs) allow social scientists to analyze video at scale, but researchers must decide which parts of a video to provide as input. We use the term representation validity to examine how text, audio, video, and combined inputs affect measurement and subsequent analysis. We compare input representations across six open-weight MLLMs and three human-annotated video datasets. No representation consistently performs best. On seven news-related constructs, native-video performance varies little across models (macro-F1 = .70-.77), while extracted-text performance ranges from .52 to .80. Three models perform better with text and three with video. Combining inputs rarely improves performance. Higher classification accuracy also does not reliably produce estimates closer to those based on human codes. The highest-F1 representation best reproduces human-coded regression coefficients in 17 of 42 comparisons. Even when each model uses its highest-F1 deployable representation, 45% of sample-prevalence estimates differ from the human-coded benchmark by more than ten percentage points. Input representation therefore requires validation for both the construct being measured and the quantity estimated from the resulting labels.","authors":["Christian Pipal","Eva-Maria Vogel","Morgan Wack"],"published":"2026-11-03T16:42:49Z","updated":"2026-11-03T16:42:49Z","abstract_url":"https://arxiv.org/abs/2611.05181v1","html_url":"https://arxiv.org/html/2611.05181v1","pdf_url":"https://arxiv.org/pdf/2611.05181v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"html","source_text_chars":119026,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) allow social scientists to analyze video at scale, but researchers must decide which parts of a video to provide as input. We use the term representation validity to examine how text, audio, video, and combined inputs...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05158v1","title":"Perturb, Repair, Verify: Self-Play Vision-Language Verifiers for Compositional Understanding","abstract":"Vision-language verifiers judge whether an image faithfully matches a textual description, yet existing training pipelines typically rely on static supervision from stronger external judges or curated hard-negative data. Such supervision requires external generation or annotation, is teacher-bounded, and is difficult to adapt as model failures evolve. We introduce PROVE (Perturb-and-Repair Optimization for Vision-Language Evaluation), a self-play framework that trains verifiers through a closed perturb-verify-repair-verify loop. Starting from a known-correct image-caption pair, a Mutator introduces a typed perturbation over objects, attributes, counts, or relations. The verifier then judges the perturbed caption and provides textual feedback, which a Repairer uses to recover a faithful caption for re-verification. These two verification rounds produce structured rewards for informative mismatches and visually grounded repairs. Since perturbation, verification, and repair are role-conditioned behaviors of the same evolving multimodal backbone, updating the shared parameters also improves the verifier itself. Experiments show that PROVE improves fine-grained compositional verification across model scales and families and strengthens visual-detail robustness on the reference backbone, with limited, benchmark-dependent changes on broader multimodal tasks.","authors":["Zijun Huang","Yingjun Du","Cees G. M. Snoek"],"published":"2026-11-03T16:31:34Z","updated":"2026-11-03T16:31:34Z","abstract_url":"https://arxiv.org/abs/2611.05158v1","html_url":"https://arxiv.org/html/2611.05158v1","pdf_url":"https://arxiv.org/pdf/2611.05158v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":101923,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Vision-language verifiers judge whether an image faithfully matches a textual description, yet existing training pipelines typically rely on static supervision from stronger external judges or curated hard-negative data. Such supervision requires external gen...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05131v1","title":"High-fidelity training-free photovoltaic module mapping from multi-view UAV imagery","abstract":"High-fidelity photovoltaic (PV) module mapping requires complete instance recovery and accurate delineation. Vision foundation models offer zero-shot segmentation, but converting incomplete and inconsistent predictions across views into a complete, geometrically accurate map of individual modules remains challenging. We propose the Multi-View PV Module Mapper (MV-PVMapper), a training-free framework coupling vision foundation models with unmanned aerial vehicle (UAV) photogrammetry. First, Segment Anything Model 3 (SAM 3) generates candidates from original images using text prompts. Their contours are then transferred into object space through per-module slope correction to limit distortion from surface-model noise, and verified against representative module dimensions to guide cross-view instance selection. Finally, accepted instances return to all covering images as box prompts for SAM~3, supplementing text prompts with spatial cues for iterative segmentation, verification and fusion. On five-direction surveys of three operational rooftop PV plants at approximately 1 cm nadir ground sampling distance, two feedback iterations recover 7,710 of 7,711 reference modules with no false positives at an intersection-over-union (IoU) matching threshold of 0.5. Macro-averaged area precision and recall reach 99.00 % and 98.52 %, respectively. Averaged across sites, the aggregated Jaccard index reaches 97.55 %, compared with 60.73 % and 41.24 % for orthomosaic segmentation and multi-view pixel-voting baselines, respectively; average precision at the stricter IoU threshold of 0.95 reaches 95.67 %. Ablation studies show that module-size constraints are critical for instance separation, while slope correction and feedback to all covering views improve boundary accuracy. These results are achieved without task-specific image annotation or segmentation-model weight updates.","authors":["WenHao Duana","Qi Chena","Penglei Zhang","Ruizhe Deng","Zhiling Guo","Haoran Zhang","Yuntian Chen"],"published":"2026-11-03T16:14:16Z","updated":"2026-11-03T16:14:16Z","abstract_url":"https://arxiv.org/abs/2611.05131v1","html_url":"https://arxiv.org/html/2611.05131v1","pdf_url":"https://arxiv.org/pdf/2611.05131v1.pdf","matched_keywords":["instance"],"source_used":"html","source_text_chars":71633,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 instance 相关；摘要显示其主要贡献为：High-fidelity photovoltaic (PV) module mapping requires complete instance recovery and accurate delineation. Vision foundation models offer zero-shot segmentation, but converting incomplete and inconsistent predictions across views into a complete, geometrica...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05106v1","title":"Label-Preserving Fourier Domain Adaptation with Generative-AI and Real Style Donors for 3D Mitral Valve Segmentation","abstract":"Accurate segmentation of the mitral valve from three-dimensional transesophageal echocardiography (3D TEE) is severely restricted by the scarcity of publicly available expert- annotated volumetric datasets. To address this critical limitation, we investigated Fourier Domain Adaptation (FDA), utilizing general-purpose generative-AI images (from platforms like Chat- GPT, Google Gemini, and Microsoft MAI) as annotation-free style donors for 3D mitral valve segmentation. We employed a DeepMitral residual U-Net model on the public MVSeg2023 dataset, comparing six conditions over three runs: real-only training, traditional augmentation, FDA with each generative source, and a non-AI FDA control using real-image style donors, plus an optimization-matched real-only control and a \\b{eta} sensitivity analysis. Case-level paired testing showed that FDA with these generative sources led to significant reductions in boundary- and surface-related errors across all three donor conditions relative to the primary real-only baseline. However, the impact on the core segmentation metric, Generalized Dice Score (GDS), proved generator-dependent. ChatGPT-FDA showed a significant GDS advantage over the optimization-matched control but not over the primary baseline, and Gemini-FDA showed no significant GDS difference. Notably, only MAI-FDA provided a statistically robust and significant increase in GDS compared to the primary baseline. The \\b{eta} sensitivity was not robust across training runs. These findings confirm that FDA remains an important augmentation mechanism. While generative-AI images offer a practical means of acquiring style diversity without new annotations, the non-AI control performed comparably to ChatGPT-FDA, so we do not conclude that this approach is superior to training with real-image donors.","authors":["Javeria Javed","Ahmed Salim","Muhammad Mahboob Ur Rahman"],"published":"2026-11-03T16:01:44Z","updated":"2026-11-03T16:01:44Z","abstract_url":"https://arxiv.org/abs/2611.05106v1","html_url":"https://arxiv.org/html/2611.05106v1","pdf_url":"https://arxiv.org/pdf/2611.05106v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":46266,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Accurate segmentation of the mitral valve from three-dimensional transesophageal echocardiography (3D TEE) is severely restricted by the scarcity of publicly available expert- annotated volumetric datasets. To address this critical limitation, we investigated...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05102v1","title":"Characterizing the vertical continuity of fuel strata based on TLS point clouds Gaussian decomposition and overlap metrics","abstract":"Vertical forest structure influences fire behavior by regulating understory-to-canopy fuel connectivity, yet operational fuel-type models represent this complexity through discrete classes that only indirectly capture vertical continuity. High-density point clouds offer an opportunity to characterize vertical fuel connectivity in a more explicit and continuous manner, but specific methodological approaches are still required. We applied Gaussian decomposition to vertical height profiles derived from terrestrial laser scanning (TLS) point clouds across 25 permanent forest plots to characterize geometric vertical fuel continuity. A multiscale analysis spanning from the plot scale to ~0.5 $m^2$ units was used to evaluate geometric, probabilistic, and overlap metrics for characterizing fuel strata. The method reproduced the vertical transition between shrub and tree strata, with median Pearson correlations ranging from 0.83 to 0.96 across analysis levels. Probability density overlap metrics and separability indicators, such as the Jeffries-Matusita distance, provided complementary descriptors of vertical continuity. Intermediate spatial scales (3-6 m cells) provided a useful compromise between spatial detail and the consistent representation of shrub-canopy interaction patterns. Finer scales increased variability due to point density reduction and profile irregularity, and low mean squared error values were found insufficient as sole performance indicators. Gaussian decomposition applied to TLS point clouds enables explicit quantification of vertical fuel continuity, a limitation of current discrete classification systems. Continuous vertical connectivity metrics derived from this approach offer a pathway for improving ladder fuel characterization and strengthening decision-making support in wildfire risk assessment.","authors":["Jesús Torralba","Luis Á. Ruiz","Pablo Crespo-Peremarch","Marina Simó-Martí","Juan Pedro Carbonell-Rivera"],"published":"2026-11-03T15:56:46Z","updated":"2026-11-03T15:56:46Z","abstract_url":"https://arxiv.org/abs/2611.05102v1","html_url":"https://arxiv.org/html/2611.05102v1","pdf_url":"https://arxiv.org/pdf/2611.05102v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":1968,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Vertical forest structure influences fire behavior by regulating understory-to-canopy fuel connectivity, yet operational fuel-type models represent this complexity through discrete classes that only indirectly capture vertical continuity. High-density point c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05083v1","title":"Manifold Embedding of Deep Image Features for Image Matching via Neural Adjoint Maps","abstract":"Estimating semantic correspondences between different object instances of similar categories in real-world images is a fundamental challenge in computer vision. While the recent progress in foundation models has significantly advanced solutions for such difficult image correspondence problems, respective methods are often insufficiently regularised. For example, common nearest-neighbour matching with foundation model features often results in noisy correspondences, which is particularly prominent when solving for dense correspondences. In this work, we tackle image matching via functional maps, which have been popularised for 3D shape matching due to their powerful spectral formalism utilising an efficient low-dimensional linear representation. However, functional maps require that domains (in our cases the rectangular image grids) are equipped with an informative and non-trivial geometry. To define a meaningful manifold structure for images, we use Galerkin's method from finite elements to derive a discrete Laplace-Beltrami operator (LBO) based on a manifold embedding of deep image features. Further, we leverage a neural adjoint map that allows to represent non-linear mappings. We demonstrate that our method sets the new state of the art among zero-shot image correspondence methods on multiple dense correspondence benchmarks of real-world images. Our code is publicly available: https://github.com/NafieAmrani/NAMI","authors":["Nafie El Amrani","Moritz Heep","Florian Bernard"],"published":"2026-11-03T15:42:20Z","updated":"2026-11-03T15:42:20Z","abstract_url":"https://arxiv.org/abs/2611.05083v1","html_url":"https://arxiv.org/html/2611.05083v1","pdf_url":"https://arxiv.org/pdf/2611.05083v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"html","source_text_chars":110150,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, instance 相关；摘要显示其主要贡献为：Estimating semantic correspondences between different object instances of similar categories in real-world images is a fundamental challenge in computer vision. While the recent progress in foundation models has significantly advanced solutions for such diffi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05072v1","title":"Trajectory Evaluation via Rollout-Free World Model for End-to-end Autonomous Driving","abstract":"Although existing candidate trajectory evaluators have substantially improved end-to-end planning accuracy, their underlying mechanism remains suboptimal. Model-based evaluators typically make scoring future-aware by explicitly predicting candidate-conditioned future states over the planning horizon, which we term rollout. However, rollout incurs high inference cost and accumulates prediction errors. We argue that planning does not require reconstructing a full future scene for each candidate, but only future-relevant information for reliable comparison. We therefore propose RFWorld, a Rollout-Free World model for end-to-end trajectory evaluation. RFWorld constructs a shared scene memory and shapes it into a future-readable representation via lightweight training-time temporal readout with semantic supervision, keeping training overhead low. At inference time, candidate trajectories directly query the shared memory via sparse spatial readout for scoring, reducing computation by roughly the planning horizon times the number of candidate trajectories, while avoiding recursive rollout errors. Experiments on NAVSIM and Bench2Drive show that RFWorld learns a more planning-aligned world representation and achieves state-of-the-art performance.","authors":["Junzhe Wang","Jinqing Zhang","Qingjie Liu"],"published":"2026-11-03T15:36:04Z","updated":"2026-11-03T15:36:04Z","abstract_url":"https://arxiv.org/abs/2611.05072v1","html_url":"https://arxiv.org/html/2611.05072v1","pdf_url":"https://arxiv.org/pdf/2611.05072v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":58700,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Although existing candidate trajectory evaluators have substantially improved end-to-end planning accuracy, their underlying mechanism remains suboptimal. Model-based evaluators typically make scoring future-aware by explicitly predicting candidate-conditione...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:15+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05066v1","title":"VIGOR: Visual Gain Ordering for Hallucination Mitigation in Multimodal Discrete Diffusion Language Models","abstract":"Multimodal discrete diffusion language models (dLLMs) generate responses through iterative mask prediction and offer a promising alternative to autoregressive large vision-language models. However, they still suffer from hallucination, producing outputs that are plausible under language priors but insufficiently grounded in the image. We argue that hallucination in multimodal dLLMs is not only a token prediction problem, but also a premature commitment problem: during iterative denoising, some masked positions are unmasked too early because their confidence is driven more by language priors than by visual evidence, and these early commitments can bias later generation. To address this issue, we propose Visual Gain Ordering (VIGOR), a training-free and plug-and-play inference strategy that reorders masked positions according to counterfactual visual evidence. At each denoising step, VIGOR compares the confidence of each candidate token under the original image-conditioned pass and an additional visual-ablation pass, and prioritizes positions whose predictions are more strongly supported by the image. Experiments on LLaDA-V and Lumina-DiMOO show that VIGOR consistently reduces hallucination and improves multimodal reasoning performance across benchmarks. Code is available at https://github.com/THU-BPM/Vigor.","authors":["Junzhe Chen","Tian Qin","Eugenie Shi","Tianshu Zhang","Qiang Ju","Lijie Wen"],"published":"2026-11-03T15:28:11Z","updated":"2026-11-03T15:28:11Z","abstract_url":"https://arxiv.org/abs/2611.05066v1","html_url":"https://arxiv.org/html/2611.05066v1","pdf_url":"https://arxiv.org/pdf/2611.05066v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"html","source_text_chars":76734,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal, diffusion 相关；摘要显示其主要贡献为：Multimodal discrete diffusion language models (dLLMs) generate responses through iterative mask prediction and offer a promising alternative to autoregressive large vision-language models. However, they still suffer from hallucination, producing outputs that...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:15+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05062v1","title":"FloMo: 3D Scene Flow as a World Action Model Intermediate for Learning from Human Video","abstract":"Pretrained video generation models distill internet-scale motion priors into robot policies, but full video is a redundant signal for action prediction. We argue that dense 3D motion is the medium through which video pretraining best transfers to robot actions, and that predicting motion rather than video affords better sample-efficiency for action prediction. FloMo is a 5B video-generation model fine-tuned to predict 3D scene-flow and action tokens. Rendering scene flow as RGB and encoding it into the same latent space as video enables a pretrained video generation backbone to efficiently adapt to predict 3D scene flow. Co-trained on action-free human video and action-labeled robot teleoperation data, our model benefits from human-video pretraining and generalizes to unseen objects, motion primitives, and tasks. Replacing motion prediction with a video prediction objective degrades out-of-distribution generalization, while adding a video prediction target alongside motion lowers policy success rather than improving it. When motion, video, and action are predicted jointly, action tokens attend far more to motion than to video, suggesting that predicting video wastes model capacity. Together, these results indicate that motion effectively mediates the transfer from video pretraining to action. More information can be found at flomo-wam.github.io.","authors":["Jeremy Collins","Namra Patel","Ayush Agarwal","Shitij Govil","Animesh Garg"],"published":"2026-11-03T15:25:35Z","updated":"2026-11-03T15:25:35Z","abstract_url":"https://arxiv.org/abs/2611.05062v1","html_url":"https://arxiv.org/html/2611.05062v1","pdf_url":"https://arxiv.org/pdf/2611.05062v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05058v1","title":"Do Agentic Policies Need to Look at Every Step? Geometric Abstraction for Reasoning and Action","abstract":"Recent multimodal language models can reason directly about robot scenes, but it is unclear whether they need to repeatedly reinterpret raw visual observations at every step of an interaction. We propose shifting routine spatial reasoning from images to text and symbols through a 3D geometric abstraction that is refreshed locally from observations and read directly by the language models. Specifically, our interface represents scene geometry via typed, evidence-aware symbolic references to object parts, grounds them from calibrated RGB-D, and returns compact textual checkpoints with metric residuals after each action. Symbolic task structure can thus be reused across decisions while metric values are rebound to the current scene, with direct visual reasoning invoked only on demand. Across offline policy synthesis and continuous online execution, reasoning over grounded text and symbols improves multi-step manipulation completion while substantially reducing repeated multimodal queries, positioning explicit geometric state as an effective substrate for agentic robot policies.","authors":["Yihang Liu","Yiming Chen","Mingzhe Zheng"],"published":"2026-11-03T15:22:46Z","updated":"2026-11-03T15:22:46Z","abstract_url":"https://arxiv.org/abs/2611.05058v1","html_url":"https://arxiv.org/html/2611.05058v1","pdf_url":"https://arxiv.org/pdf/2611.05058v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05049v1","title":"On the Learnability of Footwear Robustness: Footstep Recognition Under Unseen Conditions","abstract":"Footstep patterns, captured using pressure or force-sensitive walkways during natural walking, offer a convenient and passive approach to biometric recognition. However, footwear variability poses a major challenge to practical deployment, as it impacts both the foot-sensor interface and the user's underlying gait mechanics. This study considers the particularly difficult scenario where users enroll under one fixed footwear condition but must later be recognized in arbitrary, unseen footwear. Using the StepUP-P150 dataset, we show that footwear-induced shift, while substantial and heterogeneous across individuals, contains shared structure that can be learned from a training population and transferred, zero-shot, to previously unseen users and footwear styles. We do this using BiStepNet, a novel architecture that decomposes spatial and temporal identity cues into independently trainable streams and outperforms compact 3D spatiotemporal baselines for cross-footwear recognition. We demonstrate that cross-footwear recognition performance scales systematically with the volume and diversity of footwear representation in the training set, with gains transferring to footwear styles not directly observed during training. Moreover, we show that auxiliary gait datasets with only partial modality overlap (incorporated through the architecture's decomposed design) can be leveraged to further improve robustness to unseen footwear conditions.","authors":["Robyn Larracy","Erik Scheme"],"published":"2026-11-03T15:16:30Z","updated":"2026-11-03T15:16:30Z","abstract_url":"https://arxiv.org/abs/2611.05049v1","html_url":"https://arxiv.org/html/2611.05049v1","pdf_url":"https://arxiv.org/pdf/2611.05049v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04980v1","title":"ProAlign: Progressive Positional and Prototype-Guided Alignment for Aerial-Ground Person Re-Identification","abstract":"Aerial-Ground Person Re-Identification (AG-ReID) aims to match pedestrian images captured by unmanned aerial vehicles (UAVs) and ground-based surveillance cameras. The task remains highly challenging due to severe viewpoint discrepancies, frequent occlusions, and substantial domain gaps between aerial and ground imagery. Beyond these observable factors, existing methods often overlook two fundamental structural issues: cumulative positional drift during hierarchical feature extraction and semantic inconsistency across cross-view feature distributions. To address these challenges, we propose ProAlign, a Progressive Positional and Prototype-Guided Alignment Network for AG-ReID. ProAlign comprises two key components: a Layer-wise Progressive Positional Embedding (LPPE) module and a View-Aware Prototype Contrastive Learning (PCL) module. LPPE performs adaptive positional calibration throughout transformer layers by employing conditional positional encoding in shallow layers to mitigate local spatial distortions, while introducing learnable static positional embeddings in deeper layers to reinforce global semantic priors. Meanwhile, PCL maintains view-specific aerial and ground prototypes for each identity and enforces cross-view semantic consistency via a dual-prototype contrastive objective. Extensive experiments on CARGO and two real-world AG-ReID benchmarks demonstrate the effectiveness of ProAlign, achieving state-of-the-art overall retrieval performance on CARGO with improvements of 1.60% in Rank-1 accuracy and 5.01% in mAP over the strongest competing methods.","authors":["Qiao Li","Jing Chen","Cong Wu","Kun He","Ruiying Du","Lei Tan"],"published":"2026-11-03T14:33:13Z","updated":"2026-11-03T14:33:13Z","abstract_url":"https://arxiv.org/abs/2611.04980v1","html_url":"https://arxiv.org/html/2611.04980v1","pdf_url":"https://arxiv.org/pdf/2611.04980v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04960v1","title":"An Agentic Framework for Quality-Aware and Scenario-Adaptive Image Compression","abstract":"Despite decades of progress, image codecs remain difficult to adapt to diverse real-world compression scenarios for two main reasons. First, most image codecs are optimized for a specific objective and require substantial redevelopment when the compression goal changes. Second, they typically assume clean inputs, whereas sensor-captured images often contain degradations that alter rate-quality behavior. To address these challenges, we propose Practical Image Coding Agents (PICA), a multi-agent framework that adapts existing codecs to diverse user requirements and potentially degraded inputs. PICA consists of four collaborative agents: a Perception agent that interprets user intent and analyzes image content, an Improvement agent that jointly considers bitrate and reconstruction quality to guide pre-coding restoration, a Coding agent that refines quality-control settings from global to regional levels, and an After-coding improvement agent that addresses residual degradations and compression-induced artifacts through restoration guided solely by image quality. To enable codec-agnostic regional adaptation, we introduce Agentic ROI Coding (AROIC), which treats the codec as a black box and allows the agent to automatically schedule, execute, evaluate, and reflect ROI coding plans without architectural modifications or codec-specific retraining. We integrate these four agents with a Scenario-Guided Quality-Rate (SGQR) evaluation strategy to enable more effective scenario-adaptive compression across heterogeneous codecs. Comprehensive experiments on clean, noisy, and blurred images across standard, perceptual, and machine-vision compression scenarios demonstrate that PICA consistently enhances the compression performance of both the conventional H.266/VVC codec and the neural Cheng2020 codec, outperforming competing compression methods on the Kodak, CLIC2020, and HEVC datasets.","authors":["Zhenghao Chen","Lebin Zhou","Zicong Chen","Naifu Xue","Jiahao Li","Bin Li","Dong Xu","Yan Lu"],"published":"2026-11-03T14:19:39Z","updated":"2026-11-03T14:19:39Z","abstract_url":"https://arxiv.org/abs/2611.04960v1","html_url":"https://arxiv.org/html/2611.04960v1","pdf_url":"https://arxiv.org/pdf/2611.04960v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04950v1","title":"DPAGait: Dynamic Pose-Knowledge-Aware Network for Robust Gait Recognition in the Wild","abstract":"Gait biometrics aims at identity recognition by appearance or pose features captured during unconstrained human walking. Existing methods predominantly rely on binary silhouette images, inherently characterized by low information entropy, and fail to fully utilize the dynamic information in gait sequences, limiting their ability to handle cross-time variations effectively. Consequently, these methods encounter significant challenges in the wild. They are susceptible to variations in clothing, carried objects, and viewpoints, as well as dynamic environmental conditions, all of which lead to substantial degradation in recognition accuracy and robustness. To overcome these challenges, we propose a pose-knowledge-aware approach specifically designed for robust gait recognition in the wild. First, we propose a novel Dynamic Pose-Parsing enhanced Silhouette gait representation paradigm that substantially enhances the information entropy and effectively captures fine-grained behavioral cues by integrating pose-parsing cues with traditional silhouettes. Subsequently, we develop a dual-branch Dynamic Pose-Knowledge-Aware Gait network. The framework consists of two complementary branches: (1) a 2D dynamic pose-aware branch that extracts pose-enhanced features from our proposed DPPS representations, and (2) a 3D Skinned Multi-Person Linear branch that leverages the 3D SMPL model to capture rich and comprehensive 3D dynamic pose information. Finally, the features are integrated to facilitate accurate and robust gait recognition. Extensive experiments on four challenging in-the-wild gait datasets demonstrate the effectiveness and generalizability of the proposed DPPS representation. The complete framework is further evaluated on SUSTech1K, CCPG, and Gait3D, where SMPL information is available or can be consistently estimated, achieving competitive performance under diverse real-world conditions.","authors":["Zenan Lin","Junduan Huang","Kun Liu","M. Saad Shakeel","Wenxiong Kang"],"published":"2026-11-03T14:11:15Z","updated":"2026-11-03T14:11:15Z","abstract_url":"https://arxiv.org/abs/2611.04950v1","html_url":"https://arxiv.org/html/2611.04950v1","pdf_url":"https://arxiv.org/pdf/2611.04950v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04948v1","title":"PATTS: Parallel-Aware Test-Time Scaling for Thought-Image Generation in Multimodal Discrete Diffusion LLMs","abstract":"Test-time scaling (TTS) improves generative models by allocating additional inference-time computation to sampling, search, and verification. Existing image generation approaches, however, typically rank completed images or image-centric intermediate states. We study TTS for parallel multimodal discrete diffusion language models, in which reasoning tokens and image tokens are decoded jointly within a single generation trajectory. We first diagnose a limitation of conventional final-image selection: on GenEval, a CLIP-style image-prompt score is weakly aligned with within-prompt compositional correctness, leaving substantial headroom between verifier selection and oracle selection. We then propose PATTS, a novel parallel-aware TTS framework that searches over intermediate thought-image states using cross-modal verifier signals. PATTS uses a state-dependent reliability weight, derived from model-internal trajectory diagnostics, to modulate the influence of external semantic verification during generation. In the fixed N=32 evaluation on MMaDA-Parallel, the PATTS reaches a GenEval score of 0.844, compared with 0.628 without TTS, 0.787 for Best-of-N, and 0.810 for FKD. These results show that reliability-aware trajectory verification can improve test-time selection for parallel thought-image co-generation under the evaluated search budget. Our code release is at https://github.com/Ringo-Star/PATTS.git","authors":["Yasong Dai","Zeeshan Hayder","David Ahmedt-Aristizabal","Hongdong Li"],"published":"2026-11-03T14:10:56Z","updated":"2026-11-03T14:10:56Z","abstract_url":"https://arxiv.org/abs/2611.04948v1","html_url":"https://arxiv.org/html/2611.04948v1","pdf_url":"https://arxiv.org/pdf/2611.04948v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04932v1","title":"VISTA: Vision-Language Integrated Semantic Triage Architecture for Online Face Clustering in Long Videos","abstract":"Clustering faces by identity in long, continuous video streams is a challenging task that serves as a building block for human-centric video analysis. The majority of existing face clustering models are offline, i.e., they assume the entire data to be available altogether. In many practical scenarios, however, the entire data is either unavailable or poses computational challenges to be processed in its entirety. A handful of online methods that exist rely on geometric visual features and simple thresholding techniques, which fail when the faces exhibit significant appearance variations in long, unconstrained videos. To this end, we present VISTA, the first vision language framework for online face clustering in long videos. VISTA leverages semantic reasoning in a controlled, uncertainty aware fashion to maintain both high cluster purity and long range identity continuity. This makes it robust to the variations in illumination, pose, and costume changes that the faces and characters exhibit in long real world videos. Extensive experiments on the VPCD benchmark dataset (with 15 full episodes from The Big Bang Theory [2007-2019], Buffy the Vampire Slayer [1997-2003], and Sherlock [2010-2017]) demonstrate that VISTA achieves a robust precision and recall balance, consistently improving over the strongest matched online unsupervised baseline (COFC) under identical detector, embeddings, and evaluation protocol. Code and supplementary material: https://github.com/SkyJiashu/VISTA.","authors":["Jiashu Liao","Joanne Garde-Hansen","Sanjay Sharma","Tanaya Guha"],"published":"2026-11-03T14:02:57Z","updated":"2026-11-03T14:02:57Z","abstract_url":"https://arxiv.org/abs/2611.04932v1","html_url":"https://arxiv.org/html/2611.04932v1","pdf_url":"https://arxiv.org/pdf/2611.04932v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04916v1","title":"Behind Video Generation: Observations and Insights on Multimodal Understanding from Kling","abstract":"Video generation has progressed from isolated clips to coherent short-form audiovisual sequences, and the bottleneck is shifting from rendering to semantic control. This report summarizes the observations and insights on multimodal understanding gained from successive generations of Kling. We argue that generation quality is the projection of multimodal understanding through the entire data--conditioning--alignment--evaluation chain, and we examine this chain module by module. Kling-MLLM, a shared multimodal foundation model that unifies image, video, audio, synchronized audio--video, and interleaved inputs, is specialized for each downstream module. Because a DiT is trained on far fewer training samples than a language model, we treat captioning as a semantic contract that maximizes description density, and extend it to reference-grounded captioning that makes reference bindings explicit. Prompt enhancement translates user intent into this caption distribution: basic PE is derived from captions of compelling videos and refined with text-level and generator-in-the-loop reinforcement learning, while agentic PE refines the story and retrieves compelling examples. We show that a reliable text encoder comes from perceptual training rather than from stronger language ability, and that candidates can be screened from text alone before end-to-end training. Reward modeling pairs a general reward model for explainable, localized critiques with a decision reward model for fast multidimensional scoring, treating perceptual bandwidth as a first-class design parameter. Finally, we review task-specific automatic evaluation, focusing on protocols that expose scoring shortcuts and help trace failures to their upstream source. We hope these lessons offer practical guidance for building the understanding stack behind controllable video generation.","authors":["Kling Team","Dong Chen","Jialu Chen","Xinlong Chen","Yifan Dai","Haotian Dong","Binzong Geng","Yushuo Guan","Minghui Guo","Guanlin He","Guanxiao He","Jingyun Hua","Yanwei Huang","Yiyan Ji","Xueping Jia","Yizhuo Jia","Bozhou Li","Jiaze Li","Min Li","Shihao Li","Shujie Li","Shengyi Liao","Weihong Lin","Shiyuan Liu","Xinyu Liu","Siyang Mao","Xiaoru Qu","Dianmo Sheng","Yang Shi","Jiafu Tang","Longxiang Tang","Yuqi Tang","Chengzhuo Tong","Kuo Wang","Qixun Wang","Rui Wang","Tianduo Wang","Yuran Wang","Zekun Wang","Zihao Wang","Boyang Xia","Yifan Xu","Liu Yang","Zhenlong Yuan","Bohan Zeng","Mujin Zhang","Yuanxing Zhang","Zhicheng Zhang","Zhuoran Zhang","Yuanhong Zheng","Kun Gai","Chengru Song","Pengfei Wan"],"published":"2026-11-03T13:56:06Z","updated":"2026-11-03T13:56:06Z","abstract_url":"https://arxiv.org/abs/2611.04916v1","html_url":"https://arxiv.org/html/2611.04916v1","pdf_url":"https://arxiv.org/pdf/2611.04916v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04913v1","title":"EP-LVMQA: Evidence-Preserving Coarse-to-Fine Localization for Low-Quality Long Video Moment Question Answering","abstract":"Long instructional videos are increasingly used in medical education, industrial training, and procedural knowledge transfer, yet their evidence is often incomplete or unreliable: subtitles may be missing, ASR noisy, OCR sparse, and decisive actions briefly shown without narration. Existing VideoQA systems typically return labels or free-form text, making answer support difficult to inspect. We study Long Video Moment Question Answering (LVMQA), where a system returns timestamped answer-supporting evidence. We propose EP-LVMQA, an evidence-preserving coarse-to-fine framework comprising an Uncertainty-Aware Multimodal Evidence Timeline, a Coarse Evidence Planner, and an Evidence-Conditioned Fine Localizer. An evidence card transfers planner scores, matched cues, source-confidence proxies, modality-specific evidence, neighboring context, and a temporal prior between the latter two modules. On MedVidQA, EP-LVMQA achieves 26.1 R1@0.5 and 31.8 mIoU, improving the strongest non-ours results by 6.3 and 5.1 points. It raises Suff.@2 and Ver.@2 to 25.4 and 22.6, gains of 9.5 and 8.8 points. Under matched low-quality perturbations, average relative degradation is reduced from the strongest non-ours value of 14.6% to 11.1%. On Ego4D-NLQ and QVHighlights, EP-LVMQA remains broadly comparable to established task-specific localization methods.","authors":["Guoning Chen","Zhexun Hu","Yifan Wei","Yixuan Weng","Bin Li","Yufei Zhao"],"published":"2026-11-03T13:53:08Z","updated":"2026-11-03T13:53:08Z","abstract_url":"https://arxiv.org/abs/2611.04913v1","html_url":"https://arxiv.org/html/2611.04913v1","pdf_url":"https://arxiv.org/pdf/2611.04913v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04912v1","title":"MiCaDe: Online LiDAR-Camera Miscalibration Change Detection for Autonomous Driving","abstract":"Reliable multi-sensor perception in autonomous vehicles requires accurate calibration between cameras and LiDAR. However, calibration drift is often unavoidable in long-term deployments: vibrations, thermal effects, and minor mechanical shocks may alter the relative pose between sensors, leading to systematic errors in downstream fusion tasks. We propose MiCaDe (Miscalibration Change Detection), an online solution detecting when the extrinsic LiDAR-camera calibration parameters are no longer accurate by means of sequential change detection. MiCaDe requires no calibration targets, or modification of the perception stack, providing low false-alarm rates with negligible computational overhead. Our key insight is that 3D and 2D bounding boxes produced by standard object detectors should remain geometrically consistent under correct calibration. By matching cross-modal detections, we derive geometric consistency metrics that serve as sensitive indicators of extrinsic drift. These metrics are aggregated into fixed-size batches and scored against a reference distribution, producing a likelihood stream that is monitored by a Change Point Model (CPM). Crucially, the CPM accumulates statistical evidence over time, enabling detection of subtle drifts that would otherwise go unnoticed. Experiments on multiple long-sequence datasets and on a real-world dataset with physically induced miscalibration confirm reliable detection under diverse conditions. Code available at: https://github.com/CarloSgaravatti/MiCaDe.","authors":["Carlo Sgaravatti","Riccardo Pieroni","Matteo Corno","Sergio M. Savaresi","Luca Magri","Giacomo Boracchi"],"published":"2026-11-03T13:52:45Z","updated":"2026-11-03T13:52:45Z","abstract_url":"https://arxiv.org/abs/2611.04912v1","html_url":"https://arxiv.org/html/2611.04912v1","pdf_url":"https://arxiv.org/pdf/2611.04912v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04903v1","title":"Heads That Write, Not Just Point: Image Retrieval Heads in Vision-Language Models","abstract":"Large vision-language models (LVLMs) can process interleaved text and multiple images in a single context, but how they internally identify the image relevant to a question remains poorly understood. We study this grounding step as in-context image retrieval and introduce ICIR-MCQ, a controlled probe for head-level analysis of image retrieval. Using each head's attention mass over image-token spans, we first identify sparse pointer heads that reliably point to the target image. These heads transfer beyond the probe: a single pointer head is competitive with external vision-language retrievers on a naturalistic multi-image retrieval benchmark, showing that LVLMs contain a strong internal image retrieval signal. Attention alone, however, shows where a head reads from, not what its output passes on to later layers, so we introduce a complementary output-side analysis. For each head, we train a lightweight image retriever on its value-weighted output and use it to identify writer heads, whose outputs contain enough information to identify the target image. Surprisingly, the pointer and writer criteria select substantially different head sets, with only 35 to 47 heads overlapping among the top-100 heads under each criterion. Targeted set-partition ablations show that the heads most important for standard multi-image inference are concentrated in this pointer-writer intersection, while heads selected by only one criterion show less consistent separation from random-head controls. The most consistent causal effects arise from heads selected by both the attention-based pointer and output-side writer criteria. Code and data: https://github.com/parkquasar/Image-Retrieval-Heads.","authors":["Junsung Park","Sangwon Yu","Donghun Kang","Yeongtak Oh","Jaewon Jeong","Gyeongtae Yoo","Han Cheol Moon","Jungbeom Lee","Sungroh Yoon"],"published":"2026-11-03T13:48:28Z","updated":"2026-11-03T13:48:28Z","abstract_url":"https://arxiv.org/abs/2611.04903v1","html_url":"https://arxiv.org/html/2611.04903v1","pdf_url":"https://arxiv.org/pdf/2611.04903v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04894v1","title":"VisSearch-Bench: Evaluating Long Horizon Visual Search in Multimodal Agents","abstract":"Multimodal agents use web and image tools to answer questions beyond their internal knowledge. Some search tasks use images mainly to identify an initial entity, then rely on text retrieval. These tasks offer limited insight into how agents connect information across images, objects, and search steps. We therefore focus on visual context management. This involves organizing and using visual information and linking it to other findings during search. Visually intensive tasks require agents to combine object appearance, local details, or spatial relations with external information. We introduce VisSearch-Bench, with 204 human-written tasks across 7 main domains and 25 subdomains. It covers Set-wise Visual Search, Sequential Visual Search, Hybrid Wide-Deep Search, Competitive Visual Disambiguation, and Visual-Structure-Guided Search. Each task provides a reference answer, traceable evidence, and scoring rules. Accuracy measures complete task success, while Process Score measures the correctness and completeness of individual results and subquestion answers. Across 16 multimodal models, the best system fully solves only 26.47% of tasks, even with search tools. These results highlight the challenge of linking visual evidence with search results to produce complete answers.","authors":["ZhengXian Wu","Qianhao Nie","Zhuohong Chen","Junjie Gao","Yuyao Zhang","Yunyao Yu","Hangrui Xu","Cheng Cheng","Guiyu Ma","Jin Zhang","Xingzhong Xu","Kai Yang","Haoqian Wang"],"published":"2026-11-03T13:40:41Z","updated":"2026-11-03T13:40:41Z","abstract_url":"https://arxiv.org/abs/2611.04894v1","html_url":"https://arxiv.org/html/2611.04894v1","pdf_url":"https://arxiv.org/pdf/2611.04894v1.pdf","matched_keywords":["retrieval","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04873v1","title":"Trusting Imagined Futures: Auditing Imagined Rewards for VLA Post-Training","abstract":"Video world models enable candidate actions to be evaluated through imagined outcomes, but high predicted rewards can favor trajectories with poor execution quality. We introduce Trusting Imagined Futures (TIF), an offline supervision selection method for vision-language-action (VLA) post-training that audits predicted rewards using execution feedback. A multidimensional reward model predicts a utility score for candidate ranking and five dimensions of execution quality. An auditor uses reward predictions and uncertainty to identify overestimation patterns learned from paired imagined videos and real executions. TIF accepts the candidate with the highest predicted utility when its advantage over the existing trajectory exceeds a margin and its audit risk passes a threshold; otherwise, it retains the existing supervision. The retained real trajectories then supervise behavior cloning. Across four LIBERO suites and three training seeds, TIF achieves a mean success rate of 76.25%, improving over training on the existing trajectories by 3.00 percentage points with the same trajectory count and training budget. Adding audit gating yields 1.47 percentage points with the reward model and advantage margin held fixed. The gains persist against advantage ranking and logistic regression risk selection at matched replacement counts. On recorded videos from three real robot tasks, TIF increases clean completion among selected trajectories from 58.33% to 70.00% across 60 candidate pools.","authors":["Zicheng Kong","Zhenbo Xu","Haoyan Zhang","Jinghan Yang","Zhenzhen Li","Yiwei Ru","Liuyu Xiang","WanTing Xu","Min Ren","Zhaofeng He"],"published":"2026-11-03T13:26:53Z","updated":"2026-11-03T13:26:53Z","abstract_url":"https://arxiv.org/abs/2611.04873v1","html_url":"https://arxiv.org/html/2611.04873v1","pdf_url":"https://arxiv.org/pdf/2611.04873v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04811v1","title":"NightIQA: A Comprehensive Dataset and Benchmark for MLLM-Based Nighttime Image Quality Assessment","abstract":"Nighttime images are inherently susceptible to complex, compound degradations, making accurate quality assessment exceptionally challenging. Score-based IQA methods condense quality into a single number, lacking the multi-dimensional, language-grounded reasoning required for nighttime evaluation. Multimodal Large Language Models (MLLMs) offer a more comprehensive alternative, yet remain constrained by a critical data gap: existing real-world IQA datasets are overwhelmingly daytime-centric and often built from outdated captures, while synthetic alternatives lack nighttime-specific degradation modeling, yielding artifacts far removed from authentic nighttime conditions. To bridge this gap, we present NightIQA, a dataset and benchmark suite purpose-built for MLLM-based nighttime IQA. It comprises three core components: NightIQA-Real, a real-world dataset of 1,769 high-resolution images that we captured ourselves with modern equipment, encompassing six canonical distortion types and structured multi-dimensional annotations; NightIQA-Bench, a benchmark of 1,078 visually grounded multiple-choice questions tailored to MLLM-based nighttime IQA, organized around a four-level evaluation hierarchy spanning Perception, Technical Assessment, Localization, and Reasoning; and NightIQA-Syn, an inherently scalable, scene-aware synthesis pipeline that jointly models global-level and instance-level degradations, with an initial release of 80k high-fidelity images alongside the full generation code. Fine-tuned on NightIQA with Supervised Fine-Tuning (SFT) and Group Relative Policy Optimization (GRPO), Qwen3-VL-8B outperforms open-source IQA methods and achieves higher overall accuracy than leading closed-source models, highlighting the value of domain-specific data and structured supervision.","authors":["Yiding Tian","Jiaojiao Yi","Jiayuan Lu","Pufan Xu","Jinlin Wu","Changyuan Wen","Hongyuan Yu"],"published":"2026-11-03T12:42:30Z","updated":"2026-11-03T12:42:30Z","abstract_url":"https://arxiv.org/abs/2611.04811v1","html_url":"https://arxiv.org/html/2611.04811v1","pdf_url":"https://arxiv.org/pdf/2611.04811v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04764v1","title":"Pixel-space video generation with U-JiT","abstract":"Latent diffusion and flow matching models are ubiquitous in state-of-the-art generative video models. While highly effective, relying on pretrained autoencoders to compress the data into a lower-dimensional latent space also comes with drawbacks. First, training proceeds in two stages: autoencoder pretraining, with compression and reconstruction objectives, followed by latent generative model training, precluding fully end-to-end training. Second, autoencoders also lead to an inherent loss of signal, and the trade-off between reconstruction quality and generative performance in the latent space is still an active area of research. In this paper we explore the viability of generative video models directly in pixel space. We analyze recent approaches in pixel-space generative modeling of images that rely on basic transformer designs, and identify several shortcomings that limit their effectiveness for the high-dimensional pixel-space video generation. To overcome these limitations, we propose a UNet-like transformer architecture along with improvements to the training recipe and sampling strategy. We conduct controlled experiments, training latent and pixel-space models from scratch on Kinetics-600. For the standard frames-to-video task at 128 resolution, our U-JiT model improves generative FVD by 27% over prior state-of-the-art results, and by 14% against the JiT pixel-space baseline. Scaling to higher 256 resolution, we find the improvement over pixel-space and latent-based models grows as we increase the spatiotemporal compression rate up to $64 \\times 64 \\times 8$. Finally, we find that U-JiT improves per-frame FID by 27% over latent models and 61% over pixel-space models on class-to-video generation, with respectively 9% and 56% reduction in FVD.","authors":["Théophane Vallaeys","Jakob Verbeek","Matthieu Cord"],"published":"2026-11-03T12:11:03Z","updated":"2026-11-03T12:11:03Z","abstract_url":"https://arxiv.org/abs/2611.04764v1","html_url":"https://arxiv.org/html/2611.04764v1","pdf_url":"https://arxiv.org/pdf/2611.04764v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04759v1","title":"Beyond Local Refinement: Wide-Area Precise Cross-View Localization","abstract":"Fine-grained cross-view localization aims to precisely localize a ground camera against geo-referenced aerial imagery, but current methods typically assume a narrow geographic prior, substantially limiting their applicability when upstream localization remains coarse. To bridge this gap, we study this task over much larger aerial regions. However, this seemingly simple extension fundamentally changes the localization problem: the growing disparity in spatial extent between ground and aerial views makes reliable cross-view matching difficult to establish directly, while the increasing number of look-alike locations in larger regions introduces substantial visual ambiguity. To address these challenges, we propose RingMatch, a search-and-verification framework for wide-area cross-view localization. RingMatch first leverages predictive uncertainty to uncover plausible locations and progressively zooms into their surroundings to obtain increasingly fine-grained evidence, yielding a compact set of promising candidates. We then introduce the depth ring, a novel geometric representation that reveals subtle variations in the spatial layout around a location and serves as a view-shared spatial signature for an LVLM verifier to resolve residual ambiguity. To benchmark this setting, we construct VIGOR-Pro by composing VIGOR aerial tiles into contiguous regions with spatial extents of up to 400 m. Experiments show that RingMatch maintains strong localization performance as the aerial region expands, consistently outperforming representative end-to-end and retrieval-based methods.","authors":["Qingguo Hu","Xinyu Ma","Yujie Lin","Yaoxiang Wang","Qi Shi","Zonghao Guo","Chi Chen","Jinsong Su"],"published":"2026-11-03T12:08:24Z","updated":"2026-11-03T12:08:24Z","abstract_url":"https://arxiv.org/abs/2611.04759v1","html_url":"https://arxiv.org/html/2611.04759v1","pdf_url":"https://arxiv.org/pdf/2611.04759v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04755v1","title":"iMED: A Multi-Endoscope Dataset for Surgical 3D Perception","abstract":"We introduce iMED, the first synchronized multi-endoscope dataset for robot-assisted minimally invasive surgery (RAMIS), designed to address a fundamental limitation in surgical vision benchmarking: the absence of independent held-out viewpoints. Existing surgical datasets capture single-trajectory sequences from a single endoscope, making it impossible to distinguish geometric generalization from photometric interpolation along a narrow forward-facing path. iMED provides 340 sequences ~170K synchronized timepoints with 4 views per timepoint) recorded simultaneously from two independent stereo endoscopes across ex vivo, postmortem, and live surgical settings, spanning 14 specimens with diverse anatomical regions and motion regimes. The dataset includes calibrated camera intrinsics, ArUco-based frame-wise pose estimates with uncertainty quantification, instrument segmentation masks, and rich clinical metadata. Using a train-on-one-endoscope, test-on-another evaluation protocol, we benchmark 23 state-of-the-art methods across rigid and deformable novel view synthesis, pose estimation, feature matching, and monocular depth estimation. Our experiments show that methods relying primarily on photometric supervision degrade substantially under this held-out-endoscope setting, while methods with explicit geometric regularization are more robust across views in our benchmark. Notably, large-scale foundation models transfer surprisingly well to surgical imagery, often outperforming domain-specific models, suggesting pitfalls in current fine-tuning protocols. iMED establishes a new evaluation protocol for geometric generalization in surgical vision.","authors":["Sierra Bonilla","Fengyi Jiang","Chinedu Nwoye","Jingpei Lu","Kailey Reardon","Humphrey W. Chow","Francisco Vasconcelos","Sophia Bano","Adam Schmidt","Omid Mohareri"],"published":"2026-11-03T12:06:58Z","updated":"2026-11-03T12:06:58Z","abstract_url":"https://arxiv.org/abs/2611.04755v1","html_url":"https://arxiv.org/html/2611.04755v1","pdf_url":"https://arxiv.org/pdf/2611.04755v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04728v1","title":"SPOD: Recovering Suppressed Temporal Evidence in Video-LLMs via Single-Pass Orthogonal Decomposition","abstract":"Video Large Language Models (Video-LLMs) have achieved strong performance on many video understanding tasks, yet remain vulnerable to temporal hallucination in time-sensitive reasoning scenarios such as scene transition understanding and event ordering. Existing solutions either require costly retraining or introduce inefficient multi-pass inference and external supervision at test time. In this work, we show that temporal evidence is already encoded in Video-LLM hidden representations but is not fully exploited during standard inference. Motivated by this observation, we propose Single-Pass Orthogonal Decomposition (SPOD), a training-free framework that recovers suppressed temporal evidence through analytical hidden-state manipulation in a single forward pass. SPOD consists of two components: Frame Distinctiveness Analysis (FDA), which identifies salient frames from middle-layer hidden-state geometry, and Temporal Delta Subspace (TDS), which constructs orthogonal temporal and prior subspaces from weighted inter-frame hidden-state differences. By decomposing final hidden states into temporal, prior, and residual components and rescaling them independently, SPOD enhances dynamic information, suppresses static appearance bias, and preserves complementary information. Experiments on VidHalluc, EventHallusion, and VideoMMMU show that SPOD consistently outperforms strong inference-time baselines across temporal reasoning tasks and model architectures while retaining near-vanilla inference efficiency. These results suggest that improving temporal reasoning in Video-LLMs may depend not only on additional supervision, but also on recovering temporal evidence already present in their internal representations. Our code is available at https://github.com/VioAgnes/SPOD.","authors":["Yangguang Lin","Quan Fang","Xiaoyan Liu","Zefan Xu"],"published":"2026-11-03T11:46:39Z","updated":"2026-11-03T11:46:39Z","abstract_url":"https://arxiv.org/abs/2611.04728v1","html_url":"https://arxiv.org/html/2611.04728v1","pdf_url":"https://arxiv.org/pdf/2611.04728v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04712v1","title":"VISAGE: Vertex-based Intrinsic Surface Appearance GEneration via Dual-Stream Diffusion for Arbitrary 3D Heads","abstract":"Recovering identity-faithful, physically based surface appearance for 3D human heads from sparse images remains challenging. Existing methods often rely on UV-based pipelines, introducing seam artefacts, or operate in image space, limiting surface consistency. We present VISAGE, Vertex-based Intrinsic Surface Appearance GEneration, a surface-based conditional diffusion framework that synthesises per-vertex albedo and roughness directly on arbitrary mesh topologies, without requiring consistent UV parameterisation at training time. VISAGE combines global spectral processing with local geodesic K-Nearest-Neighbour refinement, enforcing structural coherence while restoring detail beyond the truncated spectral basis. Multi-view RGB images condition the network via visibility-aware cross-attention, enabling occlusion-robust synthesis across the full head surface. Region-specific modules specialise in semantically demanding and distinct areas (eyes, mouth, skin and hair), while a tangent-space output projection recovers fine iris detail. We further introduce a scalable procedural augmentation pipeline that enriches raw geometry scans with physically plausible albedo, roughness and normal maps for training. The predicted attributes render directly as a single RGBA vertex-colour channel. VISAGE reduces FID by 42.7% on NPHM and 22.5% and 4.4% on zero-shot FaceVerse and i3DMM, respectively, relative to the strongest baseline, with a 7.2M-parameter core network.","authors":["Jeremias Krauß","Pragati Jaiswal","René Schuster","Didier Stricker"],"published":"2026-11-03T11:35:05Z","updated":"2026-11-03T11:35:05Z","abstract_url":"https://arxiv.org/abs/2611.04712v1","html_url":"https://arxiv.org/html/2611.04712v1","pdf_url":"https://arxiv.org/pdf/2611.04712v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04711v1","title":"Cycle WAM: Coupling Action and Video through Cycle Consistency","abstract":"Recent advances in video modeling have driven substantial progress in world action models (WAMs). Existing approaches exploit pretrained video priors by decoding actions from latent representations or inferring them from generated videos. The underlying link is causal: robot actions produce changes in the scene, and video observations of these changes provide evidence for inferring the actions that produced them. However, existing training formulations do not by themselves ensure that actions and their predicted visual consequences are consistent, potentially limiting the use of pretrained capabilities. We treat video and action as paired modalities linked by this causal relationship and learn their correspondence through a unified training framework designed to better exploit pretrained video priors. Cycle WAM first augments video-action co-training with bidirectional conversion to reinforce cross-modal correspondence and recover forward and inverse dynamics. It then introduces a differentiable cycle-reconstruction objective to further couple the two mappings. The resulting model supports both forward and inverse dynamics, with the potential to improve performance through more effective use of pretrained video priors. Cycle WAM achieves state-of-the-art performance among comparable methods on LIBERO-Pro and substantially improves DreamZero on DROID. Comparisons with UWM characterize its inverse-dynamics performance and show sharper visual detail in the displayed forward-dynamics predictions.","authors":["Qinglin Yang","Jiepeng Wang","Yuxing Huang","Haibin Huang","Kai Xu","Chi Zhang","Ruizhen Hu","Xuelong Li"],"published":"2026-11-03T11:33:51Z","updated":"2026-11-03T11:33:51Z","abstract_url":"https://arxiv.org/abs/2611.04711v1","html_url":"https://arxiv.org/html/2611.04711v1","pdf_url":"https://arxiv.org/pdf/2611.04711v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04710v1","title":"DenseTwins: Dense Modality Decoupling for Multimodal Self-Supervision","abstract":"Multimodal perception is central to many computer vision applications, including robotics and autonomous driving, where different sensing modalities provide complementary cues. Self-supervised learning offers a scalable solution for exploiting large amounts of unlabeled multimodal data. However, existing methods either neglect modality-specific information by enforcing feature-space alignment between modalities or learn only global representations without preserving spatial structure. We propose DenseTwins, a multimodal self-supervised framework that learns dense representations by explicitly decoupling the dense feature space into shared and modality-specific components. The proposed approach combines dense cross-modal correspondences with redundancy-reduction objectives, enabling the model to capture both shared semantics and modality-specific cues within a structured dense embedding space. DenseTwins jointly optimizes an intra-modal objective across augmented views and a cross-modal objective that aligns shared features while decorrelating modality-specific information. We evaluate DenseTwins across multiple multimodal benchmarks and sensing setups, achieving state-of-the-art or competitive performance across multimodal self-supervised baselines. Code available at: https://github.com/CarloSgaravatti/DenseTwins.","authors":["Carlo Sgaravatti","Daniele Kopyshevskiy","Davide Secco","Giacomo Boracchi"],"published":"2026-11-03T11:31:33Z","updated":"2026-11-03T11:31:33Z","abstract_url":"https://arxiv.org/abs/2611.04710v1","html_url":"https://arxiv.org/html/2611.04710v1","pdf_url":"https://arxiv.org/pdf/2611.04710v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04709v1","title":"Learning from Unlabeled Photographs for General Oral Image Analysis","abstract":"Oral photographs contain rich clinical information and hold significant potential for artificial intelligence applications; however, most models are trained for individual tasks and rely on costly expert annotations. We hypothesized that self-supervised training on unlabeled oral photographs could produce transferable visual representations for heterogeneous vision tasks. To test this hypothesis, we developed DOVE (Dental Optical Visual Encoder) by domain-adaptive self-supervised pretraining on approximately 530,000 unlabeled oral photographs collected from publicly accessible sources. DOVE was benchmarked against 3 established baselines across 5 classification datasets and 4 segmentation datasets, covering both frozen backbone evaluation and end-to-end finetuning. DOVE achieved the strongest overall performance, ranking best in few-shot transfer and label efficiency on most benchmarks. Under the 20-shot frozen-backbone protocol, DOVE outperformed the second best DINOv3 by 4.37 percentage points in mean macro-F1 across classification datasets and by 4.49 percentage points in mean macro-Dice across segmentation tasks. Under end-to-end finetuning, DOVE achieved at least 80% of the strongest full-data baseline's performance across most evaluation datasets using only 10% of the labeled training data. Qualitative retrieval and feature analyses further indicated better organization of image-level and spatial representations. These findings support DOVE as a generalizable and label-efficient backbone for oral vision research.","authors":["Zhong-Shi Zhang","Zi-Li Yu","Xiao Xiao","Huan Liu","Gui-Song Xia","Cui Huang","Meng-Xun Li"],"published":"2026-11-03T11:28:54Z","updated":"2026-11-03T11:28:54Z","abstract_url":"https://arxiv.org/abs/2611.04709v1","html_url":"https://arxiv.org/html/2611.04709v1","pdf_url":"https://arxiv.org/pdf/2611.04709v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04666v1","title":"Phase-DGS: Phase-guided Dynamic Gaussian Splatting from Unsynchronized Multi-view Video","abstract":"Spatiotemporal scene reconstruction with Dynamic Gaussian Splatting (DGS) fundamentally depends on perfect temporal synchronization across all cameras, an assumption rarely achievable in practice. Industry-standard synchronization requires expensive specialized hardware and complex setup, while data-driven alternatives including audio-based alignment, geometry matching, and pose tracking remain limited by restrictive environmental or scene-specific assumptions. To overcome these limitations, we propose Phase-DGS, a framework that replaces conventional timestamps with a semantic phase representing each frame's inherent state within the underlying motion cycle. Frames capturing the same motion state share the same phase regardless of which camera records them or when, naturally establishing spatiotemporal correspondence across unsynchronized cameras. We validate Phase-DGS under temporal offsets, frame drops, and camera freezes, achieving up to +8.5 dB PSNR improvement over baselines while enabling seamless integration with existing DGS backbones including RealTime-4DGS and FreeTimeGS.","authors":["Hosung Jeon","Jun Young Jeong","Sangwoon Kwak","Joonsoo Kim","Sangmin Kim","Jaesik Park","Won-Sik Cheong","Hyon-Gon Choo"],"published":"2026-11-03T10:51:33Z","updated":"2026-11-03T10:51:33Z","abstract_url":"https://arxiv.org/abs/2611.04666v1","html_url":"https://arxiv.org/html/2611.04666v1","pdf_url":"https://arxiv.org/pdf/2611.04666v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04654v1","title":"BhopalMLS: A LiDAR Dataset for Semantic Scene Understanding in Heterogeneous Urban Environments","abstract":"We introduce BhopalMLS, a large-scale Mobile Laser Scanning (MLS) dataset from a dense, heterogeneous urban environment in Bhopal, India, with mixed traffic, informal structures, and narrow unplanned streets. It spans approximately 10 km of road corridors with over 1.2 billion points and 19,518 annotated instances across 62 fine-grained static categories, grouped into 12-class and 21-class benchmark taxonomies; 6 optional moving-class subclasses support dynamic-object analysis. Existing 3D datasets, collected in well-planned cities, are structurally more uniform than such unplanned settings, and lack their subtype diversity. On semantic and instance segmentation at both granularities, fine-tuned foundation models surpass supervised baselines: Utonia(L) reaches 71.28% mIoU (vs. PTv3's 68.04% from scratch) and 44.07% mAP50 on the 12-class benchmark. Cross-region experiments against four established datasets (Ke-MLS, Toronto-3D, Paris-Lille-3D, SemanticKITTI) reveal a consistent asymmetric transferability: models trained on BhopalMLS transfer better than the reverse on every pair, for both Utonia(L) and Concerto(L) (mean 21.5, up to 36 mIoU points), holding even when the target is denser. Factor-controlled retraining at a fixed label budget, repeated on both models, attributes this to the coverage of BhopalMLS's subtype inventory rather than to dataset size or corridor geometry: collapsing each class to a single subtype costs 13.0 and 13.3 mIoU points for Utonia(L) and Concerto(L). BhopalMLS therefore offers a testbed for 3D perception beyond well-planned cities. Data and an interactive viewer are at https://geoai4cities.github.io/bhopalmls.","authors":["Pyare Lal Chauhan","Vaibhav Kumar","Bharat Lohani"],"published":"2026-11-03T10:41:37Z","updated":"2026-11-03T10:41:37Z","abstract_url":"https://arxiv.org/abs/2611.04654v1","html_url":"https://arxiv.org/html/2611.04654v1","pdf_url":"https://arxiv.org/pdf/2611.04654v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04645v1","title":"Therapy-FIS: A Dataset for Assessing Facilitative Interpersonal Skills in Psychotherapeutic Setting","abstract":"Facilitative Interpersonal Skills (FIS) is a performance-based assessment method that provides a structured framework for evaluating the interpersonal competencies of mental health professionals. However, existing FIS assessment relies heavily on human observer ratings, making the evaluation process labor-intensive, costly, and difficult to scale. Progress toward automated FIS assessment has also been constrained by the lack of publicly available professional data in psychotherapy settings. To address this limitation, we introduce Therapy-FIS, a dataset for automated FIS assessment in standardized psychotherapy tasks. To our knowledge, Therapy-FIS is the first publicly available dataset in this domain. It contains facial, acoustic, and textual signals derived from standardized therapist responses to standardized mock patient stimulus clips, based on 890 therapist video recordings and 8 patient videos, and is rated with eight FIS subscale ratings and an overall FIS score. Built on Therapy-FIS, we further establish a benchmark with two downstream tasks: Therapist Performance Rating and Joint Therapist--mock-Patient Performance Rating. We also introduce a competitive baseline, DyadicFIS, with gated fusion and routed readout under therapist-only and dyadic settings. DyadicFIS obtains the best macro CCC(Concordance Correlation Coefficient) scores on both tasks (0.2807 and 0.3299). Therapy-FIS offers a reproducible resource for data-driven automated assessment of therapeutic interpersonal skills in mental health.","authors":["Qijian Zheng","Wanqing Lin","Yuanfang Wang","Yijun Ge","Jordan Bate","Katie Aafjes-van Doorn","Feng Liu"],"published":"2026-11-03T10:35:21Z","updated":"2026-11-03T10:35:21Z","abstract_url":"https://arxiv.org/abs/2611.04645v1","html_url":"https://arxiv.org/html/2611.04645v1","pdf_url":"https://arxiv.org/pdf/2611.04645v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04633v1","title":"ReXMo: End-to-End Video Character Replacement with Expression and Motion Preservation","abstract":"Video character replacement aims to replace actors while preserving facial expressions, motions, and scene dynamics. Existing methods typically rely on masked generation with pose guidance, limiting fine-grained expression and motion preservation in complex scenes. We propose ReXMo, an end-to-end framework that supports single-, multi-, and selective character replacement scenarios. ReXMo introduces paired triplet supervision, where synthesized driving videos and original videos share identical performances but different identities, enabling scalable training through synthetic data generation. An In-Context Diffusion Transformer learns identity transformation by jointly conditioning on driving videos, reference identities, and text prompts, while an Expression Enhancement Adapter improves facial expression preservation in multi-person scenes. Extensive experiments demonstrate that ReXMo outperforms existing methods in identity fidelity, motion consistency, expression preservation, and visual quality. Our dataset and code will be publicly released.","authors":["Hualiang Wei","Wenhui Li"],"published":"2026-11-03T10:22:09Z","updated":"2026-11-03T10:22:09Z","abstract_url":"https://arxiv.org/abs/2611.04633v1","html_url":"https://arxiv.org/html/2611.04633v1","pdf_url":"https://arxiv.org/pdf/2611.04633v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04626v1","title":"MambaHand: Local Identity and Behavioral Sequence Learning with Mamba for Dynamic Hand Gesture Authentication","abstract":"Dynamic hand gesture authentication (DHGA) is an emerging biometric technique that contains both physiological and behavioral identity characteristics. However, existing methods primarily rely on convolutional networks or manually designed motion representations, making it difficult to jointly capture fine-grained local identity differences and long-range behavioral dependencies during hand gesture execution. To address these challenges, we propose a two-stream identity representation learning framework, MambaHand Net, to combine CNNs with Mamba for DHGA. The proposed framework consists of a Local Identity Stream (LIS) and a Behavioral Sequential Stream (BSS). The LIS extracts frame-wise local identity cues with a convolutional network, while the BSS preserves spatial tokens from intermediate visual features and constructs first-order and second-order temporal difference sequences to model multi-order behavioral variations. Moreover, the bidirectional Mamba is incorporated into the BSS to model semantic motion across different spatial locations, enabling efficient long-range modeling of hand gesture execution habits. Finally, attention-guided spatial token aggregation and a two-stream fusion strategy are used to integrate local identity cues and multi-order behavioral patterns into a discriminative identity representation. Our method achieves state-of-the-art (SOTA) average performance on the SCUT-DHGA benchmark dataset, demonstrating that combining CNNs with Mamba is an effective new solution for DHGA.","authors":["Zenan Lin","Junduan Huang","Xilai Wang","Wenxiong Kang"],"published":"2026-11-03T10:16:43Z","updated":"2026-11-03T10:16:43Z","abstract_url":"https://arxiv.org/abs/2611.04626v1","html_url":"https://arxiv.org/html/2611.04626v1","pdf_url":"https://arxiv.org/pdf/2611.04626v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04616v1","title":"Gradient-Guided Orientation Learning for Weakly Supervised Oriented Object Detection","abstract":"Weakly supervised oriented object detection (WS-OOD) aims to reduce the annotation cost of rotated bounding boxes by leveraging cheaper annotations such as horizontal boxes or points. However, these weak annotations provide no explicit orientation information, forcing existing methods to infer object angles through indirect geometric consistency or equivariant constraints. Such indirect supervision often becomes ambiguous and unstable under real-world appearance variations, including illumination changes, color shifts, shadows, and background clutter. In this paper, we present a simple yet effective gradient-guided orientation learning strategy for WS-OOD. Motivated by the observation that the input image itself contains useful orientation priors, our method extracts dominant gradient-based orientation cues from object regions and converts them into pseudo-angle labels for auxiliary supervision, enabling the detector to learn orientation-aware representations without requiring rotated bounding box annotations or extra learnable parameters. Furthermore, since AP can mask substantial angular errors when spatial IoU remains high, we introduce an orientation-aware evaluation metric that incorporates angular discrepancies into the standard AP protocol. Extensive experiments on weakly supervised oriented detection benchmarks demonstrate that the proposed pseudo-angle supervision improves both detection performance and orientation estimation quality, while the proposed metric provides a more faithful assessment of angle prediction than conventional AP alone.","authors":["Junyong Jang","Juheon Park","Minyoung Jeon","Jaehyup Lee"],"published":"2026-11-03T10:07:49Z","updated":"2026-11-03T10:07:49Z","abstract_url":"https://arxiv.org/abs/2611.04616v1","html_url":"https://arxiv.org/html/2611.04616v1","pdf_url":"https://arxiv.org/pdf/2611.04616v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04604v1","title":"Sparse-View 3D Coronary Reconstruction from Vessel Segmentations Using a Diffusion Prior","abstract":"Reconstructing three-dimensional (3D) coronary anatomy from sparse angiographic views could support percutaneous coronary intervention, but limited angular coverage and imperfect vessel segmentations introduce substantial geometric ambiguity. We propose a vessel-specific reconstruction framework combining a learned 3D diffusion prior, visual-hull initialization, and projection-based data consistency. The unconditional diffusion model is trained on coronary vessel masks without paired 2D--3D data and reused across different view counts without retraining. During inference, a scaled visual hull initializes reconstruction, while projection-based updates constrain diffusion refinement using patient-specific vessel observations. We evaluated the framework on simulated angiograms derived from ImageCAS computed tomography angiography volumes using two, four, and eight views at two contrast levels. Across 50 evaluation coronary-tree cases, the proposed method achieved higher mean Dice and clDice than visual hull, deep image prior (DIP), and hash-grid implicit neural representation (INR) at all view counts under reduced contrast. With eight views, improvements over DIP, the best-performing baseline at lower contrast, were approximately 0.13 in Dice and 0.22 in clDice. At higher contrast, performance remained competitive with hash-grid INR, the best-performing eight-view baseline. The preferred diffusion starting timestep depended on observation quality and view count, with excessive refinement reducing accuracy at higher contrast. Projection guidance improved both metrics across all conditions. Averaging stochastic reconstructions further improved accuracy, while sample disagreement localized errors with average-precision gains of 0.14--0.21 over error prevalence. These findings support diffusion-prior reconstruction from sparse vessel observations, although clinical validation remains necessary.","authors":["Tianyuan Wang","Kenan Niu","Stefano Stramigioli"],"published":"2026-11-03T09:58:45Z","updated":"2026-11-03T09:58:45Z","abstract_url":"https://arxiv.org/abs/2611.04604v1","html_url":"https://arxiv.org/html/2611.04604v1","pdf_url":"https://arxiv.org/pdf/2611.04604v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04583v1","title":"Multi-Path Mamba Diffusion for 3D Point Cloud Semantic Scene Completion","abstract":"3D semantic scene completion plays a critical role in enabling various downstream tasks within autonomous systems by estimating both missing geometric structures and semantic information in scene data. In this work, we introduce a unique neural framework that integrates state space modeling with diffusion-based generative approaches to enhance 3D point cloud semantic scene completion. We propose \\textit{MPath Mamba} diffusion network, leveraging a skip-triple Mamba structure, dimensional decomposition residuals, and multi-directional dilations within multi-path data to efficiently process long-sequence data for feature extraction. The proposed method operates in the conditioned latent space of a variational autoencoder, enhanced by a state-space mechanism to improve 3D point cloud representation and reconstruction. Extensive experiments conducted on the SemanticKITTI benchmark demonstrate that our approach achieves highly competitive performance for 3D point cloud semantic scene completion.","authors":["Li Liang","Naveed Akhtar","Jordan Vice","Anwaar Ulhaq","Ajmal Saeed Mian"],"published":"2026-11-03T09:41:50Z","updated":"2026-11-03T09:41:50Z","abstract_url":"https://arxiv.org/abs/2611.04583v1","html_url":"https://arxiv.org/html/2611.04583v1","pdf_url":"https://arxiv.org/pdf/2611.04583v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04554v1","title":"SEEK-VAU: Towards Evidence-Faithful Video Anomaly Understanding via Agentic Search","abstract":"Most video anomaly understanding (VAU) systems still infer anomaly judgments from evidence collected in a feed-forward way under predefined rules, typically sampled frames, or events clustered from such frames. This protocol fails when the collected evidence is incomplete under imperfect predefined rules, because once reasoning begins the model can no longer search for the missing evidence. We address this limitation with SEEK-VAU, which reframes VAU as an agentic search-and-verify interaction protocol under a bounded search budget: instead of passively reasoning over pre-collected evidence, the policy actively gathers evidence across the three stages of an anomaly event chain (precursor, trigger, and aftermath) and verifies its sufficiency before finalization, turning event-chain completeness into an explicit design rather than an outcome of predefined rules. A bounded budget caps the cost of this search, but does not by itself teach the policy where to look or when to stop. To make this behavior learnable, we introduce evidence-faithful counterfactual verification (EFCV), which rewards selected evidence that remains supportive, compact, and necessary under counterfactual verification. We further introduce SEEK-Bench, featuring video-level episodes with temporal interval annotations, semantic QA and event-chain stage labels. Together, SEEK-VAU and SEEK-Bench establish a strong foundation for evidence-faithful and actively verifiable VAU.","authors":["Minghe Wang","Weijun Zeng","Dapeng Luo","Xinyue Wang","Nong Sang"],"published":"2026-11-03T09:19:58Z","updated":"2026-11-03T09:19:58Z","abstract_url":"https://arxiv.org/abs/2611.04554v1","html_url":"https://arxiv.org/html/2611.04554v1","pdf_url":"https://arxiv.org/pdf/2611.04554v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04548v1","title":"Predicting Void Points in Self-Occluding Forest Volumes","abstract":"Synthetic Aperture Imaging (SAI) enables drones to observe forest canopies by warping and averaging multiple displaced views at a common depth. However, occlusion is suppressed rather than eliminated, causing poorly observed regions to appear occupied and leading to systematic biomass overestimation. The Deep Forest project cannot distinguish reconstruction artifacts from real vegetation because its training data relies on measured reflectance points, excluding empty space and preventing the network from learning explicit occupancy boundaries. This thesis addresses the problem by modifying training labels rather than the imaging process. Each simulated scene is rendered twice: as a 9x9 grid of top-down captures for focal-stack generation and as 550 depth-clipped slabs derived from scene geometry to provide occupancy labels, explicitly representing void space as a negative class. A Gazebo pipeline generates procedural forest stands containing 80-200 trees across three species. A pretrained Pix2Pix model translates rendered RGB images into a synthetic near-infrared band, and Light Field Rendering produces aligned focal stacks of 550 planes across three channels. Four architectures were evaluated on a held-out scene. The plain 2D U-Net achieved an IoU of 0.6290, outperforming the volumetric 3D U-Net (0.5707). Established reconstruction methods performed substantially worse: COLMAP achieved 0.3446 and DepthAnything3 0.2959, both after their respective optimal dilation sweeps. An RGB-input variant of the volumetric architecture achieved the highest IoU of 0.6514 without dilation or per-scene calibration. These results highlight the limitations of conventional reconstruction methods, which recover visible surfaces but struggle to infer occupancy within closed canopies.","authors":["Benjamin Bachmayr","Mohamed Youssef","Oliver Bimber"],"published":"2026-11-03T09:12:46Z","updated":"2026-11-03T09:12:46Z","abstract_url":"https://arxiv.org/abs/2611.04548v1","html_url":"https://arxiv.org/html/2611.04548v1","pdf_url":"https://arxiv.org/pdf/2611.04548v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04529v1","title":"Learning to Falsify: Hierarchical Multiple Instance Learning for High Resolution AI-Generated Image Detection","abstract":"Recent advances in generative models have made synthetic images increasingly photorealistic, posing growing challenges to reliable and generalizable detection of AI-generated images. Existing methods typically rely on holistic image-level classification, which may overlook local artifacts, especially in high-resolution images. To address this limitation, we formulate this task as a falsification-driven multiple instance learning problem, where a single fake patch can falsify the whole image, while a real image requires all patches to be authentic. Based on this formulation, we propose \\textit{Learning to Falsify (LTF)}, a hierarchical multiple instance learning framework that models an image as multiple bags of instances across different spatial levels and aggregates their predictions under the falsification-inspired principle. We further introduce Cross-Shuffle during training to encourage the model to learn local artifact evidence rather than image-level shortcuts. Furthermore, we propose the \\textit{Falsification-driven Test-time Aggregation Strategy (FATAS)}, a plug-and-play module that extends the same falsification-inspired principle to existing detectors by aggregating patch-level predictions. Extensive experiments demonstrate that LTF achieves strong generalization and robustness across multiple benchmarks, while FATAS substantially improves representative detectors in high-resolution scenarios without retraining. Code is available at https://github.com/HuiGuanLab/LTF.git","authors":["Haoran Chen","Daiqi Gao","Xinyuan Li","Yongwei Wang","Lei Zhu","Rui Cai","Jianfeng Dong"],"published":"2026-11-03T08:58:26Z","updated":"2026-11-03T08:58:26Z","abstract_url":"https://arxiv.org/abs/2611.04529v1","html_url":"https://arxiv.org/html/2611.04529v1","pdf_url":"https://arxiv.org/pdf/2611.04529v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04524v1","title":"E2I-Flow: EEG-to-Image Reconstruction via Wavelet-Temporal Cross-Attention and Conditional Flow Matching","abstract":"Electroencephalography (EEG)-based visual decoding and reconstruction aims to recover visual information from non-invasive brain signals. But there are challenges due to the complex temporal-frequency characteristics of EEG signals and the difficulty of discrete denoising framework in mapping neural activity to meaningful visual representations. Here, we propose E2I-Flow, an EEG-to-image decoding and reconstruction framework that combines a novel EEG encoder for time-frequency representation learning from EEG features, and conditional flow matching for visual decoding. A stationary-wavelet frequency branch and a temporal-mixing branch are integrated through bidirectional cross-attention and adaptive fusion, with the resulting EEG representations aligned to ground-truth image embeddings using contrastive and mean-squared-error loss supervisions. The aligned EEG representation is then used as a condition for a Transformer-based flow-matching model to predict the corresponding visual embedding for image synthesis. Experimental results show strong zero-shot EEG-to-image retrieval and improved visual reconstruction performance, outperforming several state-of-the-art baselines.","authors":["Haowei Pan","Hwa Hui Tew","Junn Yong Loo","Fuad Noman","Hernando Ombao","Chee-Ming Ting"],"published":"2026-11-03T08:52:29Z","updated":"2026-11-03T08:52:29Z","abstract_url":"https://arxiv.org/abs/2611.04524v1","html_url":"https://arxiv.org/html/2611.04524v1","pdf_url":"https://arxiv.org/pdf/2611.04524v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04498v1","title":"3DGS-VBench+ and 3DGSV-Assessor: A Multi-Dimensional Subjective Benchmark and a Reference-Flexible Objective Model for 3D Gaussian Splatting Video Quality Assessment","abstract":"3D Gaussian Splatting (3DGS) enables real-time novel view synthesis (NVS), but its heavy storage makes compression essential, and both training and compression introduce representation-specific distortions. Since generative compression in many methods treats geometric and color attributes via different parameters, it can induce dimension-specific distortions, motivating multi-dimensional assessment. Moreover, real-world captures generally lack an aligned ground-truth video for a synthesized, continuous camera trajectory, leaving only sparse captured views as references. To enable multi-dimensional quality assessment of 3DGS videos with scarce aligned references, we first present 3DGS-VBench+, a large-scale subjective video quality assessment (VQA) benchmark comprising 3{,}036 3DGS reconstructions, each paired with a rendered video, across 11 real-world and 22 synthetic scenes, generated by 6 representative compression algorithms at systematically designed levels and annotated with 9{,}108 MOSs covering overall, geometry, and color quality. Based on 3DGS-VBench+, we propose 3DGSV-Assessor, a reference-flexible, large multimodal framework that scores all three dimensions in one generation pass and fuses a ranking-based reference cue into the frozen regressor through a bounded gate, supporting both reduced-reference (RR) and no-reference (NR) assessment. Extensive experiments demonstrate state-of-the-art correlation with human perception on 3DGS-VBench+ and strong zero-shot generalization to other NVS benchmarks. The dataset and code will be released at https://github.com/YukeXing/3DGSV-Assessor.","authors":["Yuke Xing","William Gordon","Jiarui Wang","Yujie Zhang","Guangtao Zhai","Yiling Xu"],"published":"2026-11-03T08:26:13Z","updated":"2026-11-03T08:26:13Z","abstract_url":"https://arxiv.org/abs/2611.04498v1","html_url":"https://arxiv.org/html/2611.04498v1","pdf_url":"https://arxiv.org/pdf/2611.04498v1.pdf","matched_keywords":["video","3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04492v1","title":"Hybrid Particle-Voxel Dynamics for Multimodal 3D World Simulation","abstract":"Predicting how the world evolves in response to robot actions is central to policy learning, evaluation, and planning. However, many action-conditioned world models predict future observations in 2D image or video space without explicitly modeling the underlying 3D scene, making spatial consistency across viewpoints and over long-horizon interactions challenging. We introduce 3D World Simulator, an action-conditioned multimodal world modeling framework that jointly predicts appearance, geometry, and tactile observations from a unified 3D representation. Our approach combines a hybrid particle-voxel autoencoder that compresses point clouds into compact 3D voxel latents with an action-conditioned latent dynamics model that predicts their evolution. The shared 3D representation supports geometrically consistent rendering from arbitrary viewpoints and flexible integration of spatially aligned tactile signals. Our experiments demonstrate interactive, long-horizon, multimodal prediction at 50 Hz. We then show how our model enables scalable data generation for policy training and evaluation using tactile and multi-view visual observations, including wrist-mounted and novel camera views. Furthermore, we scale our method to large datasets containing diverse objects and demonstrate model-based planning with unseen objects and robot configurations. Together, these results highlight the potential of hybrid particle-voxel dynamics as a foundation for multimodal 3D world simulation.","authors":["Jimmy Wang","Yifan Chou","Kaifeng Zhang","Yixuan Wang","Binghao Huang","Tao Yu","Saleh Nabi","Yunzhu Li"],"published":"2026-11-03T08:20:53Z","updated":"2026-11-03T08:20:53Z","abstract_url":"https://arxiv.org/abs/2611.04492v1","html_url":"https://arxiv.org/html/2611.04492v1","pdf_url":"https://arxiv.org/pdf/2611.04492v1.pdf","matched_keywords":["video","3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04490v1","title":"Polarimetric Scattering-Structure Contrastive Learning for Few-Shot HRRP Recognition","abstract":"Few-shot high-resolution range profile (HRRP) recognition is challenged by strong aspect-dependent variation and sparse novel-class support. We propose polarimetric scattering-structure contrastive learning (PSS-CL), which supplies an episodic HRRP encoder with a structured physical training view. Dominant local responses are represented by their soft affinities to canonical polarimetric mechanisms, normalized range locations, and energy contributions. A symmetric cross-view objective transfers this scattering structure to the learned HRRP representation, while episodic prototype learning supports novel-class inference without the physical branch. We conduct Random-aspect and Cross-aspect experiments on a six-class measured dataset. In Cross-aspect 1-, 3-, and 5-shot recognition, PSS-CL achieves 81.73%, 86.92%, and 90.98% mean class accuracy (MCA), respectively, outperforming the best competing results by 5.62%, 3.09%, and 3.56%.","authors":["Fangyi Wang","Peng Zhao","Haipeng Wang"],"published":"2026-11-03T08:19:44Z","updated":"2026-11-03T08:19:44Z","abstract_url":"https://arxiv.org/abs/2611.04490v1","html_url":"https://arxiv.org/html/2611.04490v1","pdf_url":"https://arxiv.org/pdf/2611.04490v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04489v1","title":"Bridging CLIP with DINO: Cross-Modal Information Maximization for Online Test-Time Adaptation","abstract":"Vision-language models such as CLIP enable zero-shot classification from arbitrary class names, but under test-time corruptions, their visual encoder projects distorted features onto incorrect textual anchors with high confidence: a phenomenon we term modality bias. Standard entropy minimization reinforces these overconfident errors, which creates a confirmation-bias loop and collapses the predicted label distribution. We propose an online test-time adaptation (TTA) method that breaks this loop at three levels. At the representation level, a frozen self-supervised backbone (e.g., DINO v2) is combined with CLIP through a cross-covariance logit ensemble. CLIP text prototypes are projected into the feature space of this text-free backbone, so the self-supervised branch classifies native image features and is less affected by the text bias of CLIP. At the optimization level, a gated test-time information-maximization objective pairs per-sample sharpening with batch-level diversity, while an adaptive gate excludes unreliable samples from the gradient. At the prediction level, an online logit adjustment corrects the residual class-distribution skew. CDIM outperforms the compared CLIP-based online TTA baselines on ImageNet-C, CIFAR10-C, and CIFAR100-C, and remains competitive in continual and mixed-domain TTA. Extensive analyses and ablation studies verify the contribution of each of its components. Our code is available at https://github.com/B1ueC1oud/CDIM","authors":["Taehoon Kim","Wonjun Hwang","Hyunsouk Cho"],"published":"2026-11-03T08:19:29Z","updated":"2026-11-03T08:19:29Z","abstract_url":"https://arxiv.org/abs/2611.04489v1","html_url":"https://arxiv.org/html/2611.04489v1","pdf_url":"https://arxiv.org/pdf/2611.04489v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04476v1","title":"KeyWise: Efficient Video-Only Piano Transcription with a Lightweight Per-Key Architecture","abstract":"Audio-based piano transcription is hampered by the sustain pedal and by noisy or missing soundtracks, problems that video-only transcription avoids, since a top-view video shows directly when each key is pressed and released. Most visual transcription networks, however, describe the whole keyboard with one global feature vector and must learn where each key is. In this paper, we propose KeyWise, a lightweight per-key architecture that exploits the known geometry of the keyboard instead of learning it. The rectified keyboard is divided into 88 equal tiles that serve as regions of interest (ROIs), and one small recurrent network, shared by all keys, follows each key over time. On PianoVAM, KeyWise reaches the onset accuracy of the state-of-the-art V2N (95.0% vs. 94.7% onset F1 at 50 ms and 97.8% vs. 97.0% at 100 ms) with 1.3 M instead of 28.2 M parameters, and it runs 4.7 times faster on the same GPU. At 100 ms, it is also significantly more accurate when the key releases (97.0% vs. 95.5% F1) or the velocities (89.4% vs. 84.5% F1) must be correct as well. On PianoYT, KeyWise pre-trained on PianoVAM reaches 69.4% onset F1 at 100 ms, comparable to the best published result, although it needs fine-tuning for new recording conditions.","authors":["Anastasios Chatzigiannis","Natalia Panagou","Maria Koziri"],"published":"2026-11-03T08:08:59Z","updated":"2026-11-03T08:08:59Z","abstract_url":"https://arxiv.org/abs/2611.04476v1","html_url":"https://arxiv.org/html/2611.04476v1","pdf_url":"https://arxiv.org/pdf/2611.04476v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04472v1","title":"Beyond Token Representations: Explicit Visual Object Grounding for Video Reasoning Segmentation","abstract":"Video Reasoning Segmentation (VRS) aims to infer and segment target objects specified by reasoning queries in videos. Existing methods typically first infer the target and generate a few segmentation tokens for it, which are then fed into a mask decoder for mask prediction. However, such segmentation tokens tend to be both semantically monotonous and spatially ambiguous, making them largely insufficient to represent the target to guide mask prediction. In this paper, we propose an explicit visual object grounding framework for VRS. Specifically, we first propose a spatial-aware prompt generation and refinement scheme, in which we query a multimodal large language model to generate explicit spatial prompts (i.e., bounding box and point set) for the target and then refine them through multi-step dialogue. Furthermore, we introduce a query diversification and alignment module to generate auxiliary queries that describe the same target from different perspectives. We then enforce cross-query consistency between their predicted spatial prompts to alleviate the training bias caused by query limitations. Finally, we select several reliable frames using a prompt-based keyframe selection strategy to support mask decoding and propagation. Extensive experiments on eight datasets demonstrate that our method significantly outperforms state-of-the-art methods. The code is available at https://github.com/viscom-tongji/EVOG.","authors":["Jun Huang","Junyang Zhang","Zijie Yue","Bingkun Wang","Yong Luo","Miaojing Shi"],"published":"2026-11-03T07:59:55Z","updated":"2026-11-03T07:59:55Z","abstract_url":"https://arxiv.org/abs/2611.04472v1","html_url":"https://arxiv.org/html/2611.04472v1","pdf_url":"https://arxiv.org/pdf/2611.04472v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04467v1","title":"Is Forgetting Unified? Exploring Concept Unlearning in Unified Multimodal Models","abstract":"Unified multimodal models (UMMs) integrate image generation and visual understanding, but are existing single-pathway unlearning methods sufficient to suppress target concepts across both? In this work, we study cross-pathway concept unlearning. Our goal is to prevent a model from both generating images of a target concept and identifying it in input images, while preserving other capabilities. To this end, we introduce UUBench, a diagnostic benchmark covering 30 target concepts and 60 semantically related neighboring concepts. Experiments on representative UMMs show that the evaluated single-pathway methods achieve limited joint forgetting: generation-side editors strongly suppress target generation but yield limited forgetting in visual understanding, while understanding-side baselines struggle to achieve substantial forgetting even in their own pathway. Their direct composition also yields limited joint forgetting. We therefore propose UniForget, achieving joint forgetting rates of 80.0% on BAGEL-7B-MoT and 92.7% on Janus-Pro-7B, outperforming representative baselines. Further analysis reveals trade-offs between joint forgetting and capability preservation.","authors":["Zhongkai Xue","Junkai Chen","Mingcong Lei","Rumo Zhang","Yixiao Liu","Zhimin Sun","Shu Wu","Qiang Liu","Lihua Zhang","Liang Wang"],"published":"2026-11-03T07:56:19Z","updated":"2026-11-03T07:56:19Z","abstract_url":"https://arxiv.org/abs/2611.04467v1","html_url":"https://arxiv.org/html/2611.04467v1","pdf_url":"https://arxiv.org/pdf/2611.04467v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04452v1","title":"DynOSeg: Dynamic Object Segmentation via Motion-Geometry Fusion","abstract":"Moving Object Segmentation (MOS) detects and separates dynamic objects from the static background in a video, which plays a fundamental role in dynamic-scene understanding. Most MOS methods rely on pure visual motion cues alone, such as optical flow or point tracks, which is inherently ambiguous due to the compounded camera and object motions as well as motion-induced appearance changes, e.g. shadows and reflections. Naive fusion of additional information such as depth and semantics, however, cannot leverage their complementarity to the fullest extent. We therefore propose DynOSeg, a novel MOS approach that takes on a two-stage fusion structure. DynOSeg first combines a geometry-aware residual map and depth encoding into a geometric representation of motion, delineating camera motions and object dynamics. We then further incorporate semantic features to refine object understanding. We have additionally curated a diverse training corpus including CARLA-MOS, a new synthetic urban-driving dataset for MOS training. Our experiments show that DynOSeg consistently outperforms published state-of-the-art MOS methods across a diverse range of datasets. Our code and pretrained models can be found at https://github.com/ACFR-RPG/DynOSeg","authors":["Xu Han","Yiduo Wang","Yiran Wang","Viorela Ila"],"published":"2026-11-03T07:42:35Z","updated":"2026-11-03T07:42:35Z","abstract_url":"https://arxiv.org/abs/2611.04452v1","html_url":"https://arxiv.org/html/2611.04452v1","pdf_url":"https://arxiv.org/pdf/2611.04452v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04438v1","title":"Entropy-Gated Dynamic Rectification for Object Hallucination in Large Vision-Language Models","abstract":"Large Vision-Language Models (LVLMs) routinely name objects that are absent from the image. Latent steering can reduce this failure in one model forward pass, but a fixed gate treats early and late decoding steps by the same criterion. We observe that predictive entropy varies sharply within free-running generation, while states that commit to short answers occupy a narrow, confident band. We exploit this temporal mismatch by using uncertainty as a causally available, token-local control signal for an existing steering gate. We propose Entropy-Gated Dynamic Rectification (EGDR), which lowers the intervention threshold when entropy derived from the preceding step's already available logits is high and retains the calibrated operating point when it is low. On LLaVA-1.5-7B, the underlying static gate lowers CHAIR CS/CI from 53.00/15.30 to 32.00/14.30; replacing only its constant threshold with EGDR further lowers them to 29.00/13.60. At a matched 58% intervention rate, the corresponding static control obtains 30.50/14.00. The gain over the static gate holds on LLaVA-NeXT-7B and grows with the generation budget, while POPE scores and general multimodal capability remain effectively unchanged. EGDR requires no additional model forward pass and adds roughly 2% measured latency. Our code is available at https://github.com/alvi-uiu/EGDR.","authors":["Riasad Alvi","Md. Asaduzzaman Shuvo","Md. Ahashan Habib","Md. Faiyaz Abdullah Sayeedi"],"published":"2026-11-03T07:31:21Z","updated":"2026-11-03T07:31:21Z","abstract_url":"https://arxiv.org/abs/2611.04438v1","html_url":"https://arxiv.org/html/2611.04438v1","pdf_url":"https://arxiv.org/pdf/2611.04438v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04423v1","title":"SWAP-INR: Implicit Neural Representation with Switchable Attention Paths for Time-varying Multivariate Scientific Data Compression","abstract":"Visualizing multivariate scientific simulation data is essential for understanding complex physical phenomena, yet the massive scale of such data imposes a severe storage bottleneck in high-performance computing environments. Implicit neural representations (INRs) have emerged as a promising continuous alternative to traditional lossy compressors, but existing methods struggle to explicitly capture cross-variable interactions and to adapt to the diverse spectral characteristics of physical variables. To address these limitations, we propose SWAP-INR, an architecture for high-fidelity compression of multivariate, time-varying simulation data. SWAP-INR introduces two key components: (1) The switchable attention path (SWAP) module explicitly models cross-variable interactions through a cross-variable attention layer, then routes each variable to an attention or non-attention path by a deterministic, loss-driven criterion, and prunes the inactive layers for structural compression. (2) The adaptability amplification SIREN (A2-SIREN) replaces rigid frequency scaling with channel-wise learnable modulation, adapting to heterogeneous physical features with negligible overhead. Combined with post-training 16-bit quantization, SWAP-INR achieves state-of-the-art performance on small modular reactor (SMR) datasets and remains competitive on public physics simulation datasets, while maintaining a constrained memory footprint. Our code is https://github.com/hvcl/SWAP-INR.","authors":["Hyunsoo Son","Jeonghyun Noh","Chaoli Wang","Won-Ki Jeong"],"published":"2026-11-03T07:10:43Z","updated":"2026-11-03T07:10:43Z","abstract_url":"https://arxiv.org/abs/2611.04423v1","html_url":"https://arxiv.org/html/2611.04423v1","pdf_url":"https://arxiv.org/pdf/2611.04423v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04422v1","title":"GVT3D: Gesture-Vision-Text Token Enrichment for 3D Embodied Reference Understanding","abstract":"Natural human-robot interaction requires robots to interpret language and gestures within a 3D environment to support tasks such as pick-and-place and object retrieval. 3D Embodied Reference Understanding (3D-ERU) supports this by identifying the 3D location of a target object from a scene (point-cloud) containing a human pointing gesture and an accompanying language description. However, current 3D-ERU models lack alignment of cross-modal representations and incur high processing costs that increase with the point-cloud's size. To address this, we propose GVT3D, which employs an Embodied Fusion module that jointly models language, gesture, and vision inputs within a shared embedding space, promoting cross-modal alignment. We additionally introduce a foveation approach that selectively processes the point cloud within a coarse region around the estimated pointing direction to reduce computations. GVT3D achieves ~8% higher accuracy and foveation enables 2.95x faster execution while maintaining comparable accuracy, relative to prior 3D-ERU models.","authors":["Vimarsh Shah","Dulanga Weerakoon","Ajinkya Deshpande","Saksham Agarwal","Nilesh Bhatia","Neel Kiran Naik","Parth Shah","Sravan Danda","Sanjay E. Sarma","Archan Misra","Vigneshwaran Subbaraju","Sougata Sen"],"published":"2026-11-03T07:09:31Z","updated":"2026-11-03T07:09:31Z","abstract_url":"https://arxiv.org/abs/2611.04422v1","html_url":"https://arxiv.org/html/2611.04422v1","pdf_url":"https://arxiv.org/pdf/2611.04422v1.pdf","matched_keywords":["retrieval","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04418v1","title":"VidUEU-Agent: A Data-Curation Agent for Multimodal Understanding, Editing, and Unified Tasks","abstract":"The advancement of multimodal learning is heavily constrained by the scarcity and high annotation cost of high-quality instruction data. While raw videos offer an abundant and dynamic source of visual knowledge, transforming them into precise instruction data remains highly challenging. To bridge this gap, we present VidUEU-Agent, an automated pipeline that synthesizes instruction data from raw videos for multimodal understanding, editing, and unified tasks. VidUEU-Agent follows a four-stage pipeline: it performs global perception to filter low-quality shots, mines keyframes and multimodal signals, constructs metadata and routes the metadata to synthesize instruction samples. More importantly, our agent framework can autonomously iterate the data distribution based on downstream training results, thereby optimizing data quality, balance, and training effectiveness. Scaling this pipeline, we construct VidUEU-100K, a large-scale dataset of 100K training samples spanning multiple domains and tasks, providing a robust foundation for developing comprehensive multimodal capabilities. Extensive experiments demonstrate that fine-tuning baseline models on VidUEU-100K yields significant and consistent performance gains across diverse representative benchmarks, validating the effectiveness of our proposed agent framework and dataset.","authors":["Tengju Ru","Weitong Lian","Zecong Tang","Lingyi Meng","Haoran Li","Zhejun Cui","Yichen Zhu","Hangshuo Cao","Qi Kang","Yechi Liu","Kaixuan Wang","Yu-Jie Yuan","Chunwei Wang","Yu Zhang","Bo Dai"],"published":"2026-11-03T07:02:55Z","updated":"2026-11-03T07:02:55Z","abstract_url":"https://arxiv.org/abs/2611.04418v1","html_url":"https://arxiv.org/html/2611.04418v1","pdf_url":"https://arxiv.org/pdf/2611.04418v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04416v1","title":"Efficient and Faithful High-Resolution Image Editing with Sparse Cross-Resolution Denoising","abstract":"Instruction-based image editors still primarily operate at 1K, whereas practical editing increasingly requires faithful 2K/4K outputs. Dense high-resolution adaptation preserves the editing trajectory but incurs expensive target-source attention; editing at 1K followed by external refinement is cheaper but can separate detail restoration from the editing trajectory. We introduce FLASH, a native high-resolution editor based on sparse cross-resolution denoising. A frozen 1K branch provides a semantic and structural anchor, while a target-resolution branch reconstructs local detail within the same Transformer. An asymmetric topology retains full 1K attention, guides high-resolution queries with spatially aligned low-resolution noisy-target states, and confines high-resolution target-reference interaction to local Halo neighborhoods. Resolution-specific diffusion-state mapping and spatial YaRN adapt the pretrained editor to larger grids. An optional, training-free progressive path replaces early high-resolution denoising with a 1K prefix and completes refinement in the same editor. On VINS-4KEval, the direct model achieves the strongest structural fidelity among the compared methods at both 2K and 4K. A separate 4K forward benchmark with R = 1 records 4.2x faster total forward execution and 25.3x faster attention than dense target-reference attention. Progressive inference reduces end-to-end 4K latency by 30.5%, with a modest quality cost.","authors":["Maosen Zhao","Xianfang Zeng","Pengtao Chen","Peng Ye","Gang Yu","Jiayuan Fan","Tao Chen"],"published":"2026-11-03T06:58:26Z","updated":"2026-11-03T06:58:26Z","abstract_url":"https://arxiv.org/abs/2611.04416v1","html_url":"https://arxiv.org/html/2611.04416v1","pdf_url":"https://arxiv.org/pdf/2611.04416v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"}],"favorites":[],"latest":{"generated_at_utc":"2026-11-04T07:10:12+00:00","category":"cs.CV","keywords":["video","retrieval","3d","agent","representation","instance","multimodal","diffusion"],"fetch_window_hours":72,"daily_window_hours":30,"match_count":68,"new_or_recent_papers":[{"id":"2611.05377v1","title":"DreamX: Video Diffusion Model is a Universal Latent Action Learner","abstract":"Learning a universal action representation from video requires modeling dynamics that are consistent across different executions of the same action yet invariant to changes in embodiment and appearance. Existing latent action models infer actions from visual transitions, but their representations often entangle the underlying action with irrelevant visual variations, limiting transfer across embodiments. We introduce DreamX, which repurposes a pretrained video diffusion model as a universal latent action learner. Our approach extracts compact latent actions from the video model's rich spatiotemporal features, compressing each latent video frame by $\\boldsymbol{300\\times}$ ($\\boldsymbol{1{,}200 \\rightarrow 4}$ tokens). In addition, by leveraging the video model's generative prior, these latent actions capture action-relevant dynamics disentangled from visual appearance. The resulting latent space serves as a shared action interface across embodiments (human and robot), environments, and action parameterizations. On LARY-Bench, DreamX achieves state-of-the-art performance among latent action models. Moreover, actions encoded in one setting remain effective in another: the latent space supports any-to-any video transfer and zero-shot action transfer across diverse embodiments and environments. Furthermore, this shared interface also enables policy learning in a compact latent action space, reducing the computational cost of video-diffusion-based policies.","authors":["Jisoo Kim","Chaehyun Kim","Junsu Kim","Jiho Park","Seongchan Kim","Eunbeen Hong","Soowon Son","Fu-En Yang","Seungryong Kim"],"published":"2026-11-03T18:59:56Z","updated":"2026-11-03T18:59:56Z","abstract_url":"https://arxiv.org/abs/2611.05377v1","html_url":"https://arxiv.org/html/2611.05377v1","pdf_url":"https://arxiv.org/pdf/2611.05377v1.pdf","matched_keywords":["video","representation","diffusion"],"source_used":"html","source_text_chars":66352,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, diffusion 相关；摘要显示其主要贡献为：Learning a universal action representation from video requires modeling dynamics that are consistent across different executions of the same action yet invariant to changes in embodiment and appearance. Existing latent action models infer actions from visual...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05361v1","title":"Visibility-Aware Reference Generation for Benchmarking Visual 3D Reconstruction in Vegetation-Rich Environments","abstract":"Reliable evaluation of visual 3D reconstruction and depth estimation in vegetation-rich outdoor environments is limited by the scarcity of geometric ground-truth data and the cost of complete scanner surveys. We present a LiDARbased reference-generation pipeline for evaluating the zero-shot performance of feed-forward visual-geometry models alongside conventional structure-from-motion (SfM) methods. The pipeline reuses camera images, LiDAR scans, and reference poses from existing multi-sensor localization datasets to generate per-view depth maps and visible reference point clouds. To address visibility errors in accumulated LiDAR scans, we introduce the LargeDepth-Gap Visibility Score (LDGVS) for point-wise visibility filtering and automatic scale selection in Hidden Point Removal(HPR). Experiments on TartanAirV2 and TartanGround show that, compared with Poisson surface reconstruction, which is an approach suited to completed scan surveys, the combined HPR and LDGVS filtering retains approximately three times the point density at comparable absolute relative error. We also apply the pipeline to the BotanicGarden dataset to systematically compare depth estimation and 3D reconstruction methods. Feedforward methods produce dense depth predictions efficiently, but their 3D reconstructions can contain duplicated structures. Conventional SfM generally produces more coherent geometry, but its reconstructions remain sparse and more prone to failure in challenging vegetated scenes. The benchmark toolkit and datasets will be released.","authors":["Zhipeng Zhong","Matthew Coombes","Cunjia Liu"],"published":"2026-11-03T18:54:52Z","updated":"2026-11-03T18:54:52Z","abstract_url":"https://arxiv.org/abs/2611.05361v1","html_url":"https://arxiv.org/html/2611.05361v1","pdf_url":"https://arxiv.org/pdf/2611.05361v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":100152,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Reliable evaluation of visual 3D reconstruction and depth estimation in vegetation-rich outdoor environments is limited by the scarcity of geometric ground-truth data and the cost of complete scanner surveys. We present a LiDARbased reference-generation pipel...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05359v1","title":"GSCV++: Lightweight 3D Gaussian Splatting Sequence Compression via Standard Video Codecs","abstract":"This paper presents GSCV++, a lightweight pipeline for 3D {G}aussian {S}platting (GS) sequences {C}ompression with standard {V}ideo codecs. To meet the requirements of low-complexity and hardware compatibility from the industry, GSCV++ jointly improves preprocessing, 3D-to-2D mapping, and practical video compression configuration of GS compression. First, for preprocessing, energy-adaptive inter-frame spherical harmonic (SH) alternative current (AC) dimensionality reduction (EA-SHDR) is proposed to produces a compact and stable temporal SH AC feature space. It can reduce the data volume of following mapping and practical compression, as well as less complexity while eliminating redundant information. Second, for 3D-to-2D mapping, prior-based Inter-MiniPLAS (P-MiniPLAS) is designed to generate smooth 2D feature maps through prior-based weighting factor inference and small scale remapping. Compared with vanilla Parallel Linear Assignment Sorting (PLAS) and Morton scan, P-MiniPLAS ensures the generated 2D maps are more suitable for the video codec while maintaining a low level of computational complexity. Third, for practical compression, content-aware generalized compression (CA-GC) is developed to use a non-uniform bit-depth split for coordinate map generation, and a coding unit size selection is introduced for efficient compression complexity control, which fully exploits the performance of video codecs without involving normative changes. Experiments demonstrate that GSCV++ reports over 20\\% in intra- and 60\\% in inter-prediction rate-distortion gains compared with state-of-the-art (SOTA) methods. GSCV++ also achieves faster 2D map generation, encoding, and decoding than other SOTA methods using the same type of video codecs. Ablation studies verify the effectiveness and robustness of the proposed modules and provide insights for subsequent research.","authors":["Qi Yang","Yingzhan Xu","Kai Zhang","Li Zhang"],"published":"2026-11-03T18:54:29Z","updated":"2026-11-03T18:54:29Z","abstract_url":"https://arxiv.org/abs/2611.05359v1","html_url":"https://arxiv.org/html/2611.05359v1","pdf_url":"https://arxiv.org/pdf/2611.05359v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":1973,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, 3d 相关；摘要显示其主要贡献为：This paper presents GSCV++, a lightweight pipeline for 3D {G}aussian {S}platting (GS) sequences {C}ompression with standard {V}ideo codecs. To meet the requirements of low-complexity and hardware compatibility from the industry, GSCV++ jointly improves prepro...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05291v1","title":"Low-Density 3D Point Cloud Classification","abstract":"3D point cloud classification, a task in computer vision, has recently gained substantial interest due to its extensive applications across various domains such as augmented and virtual reality, robotics, and autonomous driving. However, classifying 3D point clouds becomes challenging in real-world scenarios where the density levels vary. These variations are due to limitations inherent to current sensing technologies and variable environmental conditions, which often prevent the capture of detailed and comprehensive geometric representations. Existing classification methods, which have demonstrated impressive results on dense point clouds, may be affected and could experience reduced performance when dealing with low-density point clouds. Addressing this challenge, this paper introduces LD-PointNet++, an architecture optimized for the classification of low-density point clouds. To pave the way for LD-PointNet++, we conduct the first benchmarking study that systematically evaluates state-of-the-art point cloud classification methods across varying densities, revealing significant performance declines in low-density environments. Experimental results on the ModelNet benchmark dataset demonstrate that LD-PointNet++ not only outperforms these methods in low-density scenarios but also demonstrates consistent accuracy above 90% across different density levels.","authors":["Ahmed Baha Ben Jmaa","Faten Chaieb"],"published":"2026-11-03T18:07:11Z","updated":"2026-11-03T18:07:11Z","abstract_url":"https://arxiv.org/abs/2611.05291v1","html_url":"https://arxiv.org/html/2611.05291v1","pdf_url":"https://arxiv.org/pdf/2611.05291v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":39741,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：3D point cloud classification, a task in computer vision, has recently gained substantial interest due to its extensive applications across various domains such as augmented and virtual reality, robotics, and autonomous driving. However, classifying 3D point...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05280v1","title":"YANAMI: A Large-Scale Multimodal Dataset and Benchmark for Multiturn Stateful Interaction","abstract":"Unified Multimodal Models (UMMs) integrate visual understanding, generation, and editing within a single unified framework. However, existing unified multimodal datasets and benchmarks remain dominated by single-turn tasks. Even in recent multi-turn datasets, many turns can be solved independently without tracking information across turns. Consequently, they provide limited supervision and evaluation for multimodal stateful interaction, which requires models to understand, maintain, update, and faithfully realize evolving dialogue states across turns. To address this gap, we introduce YANAMI, the first large-scale multimodal dialogue dataset and benchmark for stateful interaction, comprising YANAMI-400K and YANAMI-Bench. YANAMI-400K contains 400K multi-turn multimodal dialogues, with more than 2M images and 2.6M dialogue turns. The dialogues span four representative scenarios: Multi-Image Fusion, Image Editing, World Modeling, and Visual Reasoning, and require models to continuously track, preserve, and revise evolving multimodal dialogue states across turns. YANAMI-Bench comprises 400 multi-turn dialogues for systematically evaluating multimodal stateful interaction. It jointly evaluates Dialogue State Understanding and Visual Realization, characterizing the gap between models' ability to understand evolving dialogue states and their ability to faithfully realize them in visual outputs. Experiments show that fine-tuning BAGEL on YANAMI-400K improves image editing, generation, and multimodal stateful interaction by 10.3%, 2.0%, and 13.23%, respectively, while preserving its general visual understanding capabilities. Evaluations on YANAMI-Bench further reveal that existing UMMs still struggle to maintain, update, and visually realize evolving multimodal dialogue states.","authors":["Shengyu Wang","Tengyue Nong","Junming Liu","Haosong Peng","Siyu Li","Ruiqi Lei","Fushuo Huo","Yuhao Pan","Yunfeng Fan","Ding Wang","Nan Cheng","Haozhao Wang","Wenchao Xu"],"published":"2026-11-03T17:59:36Z","updated":"2026-11-03T17:59:36Z","abstract_url":"https://arxiv.org/abs/2611.05280v1","html_url":"https://arxiv.org/html/2611.05280v1","pdf_url":"https://arxiv.org/pdf/2611.05280v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":108524,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Unified Multimodal Models (UMMs) integrate visual understanding, generation, and editing within a single unified framework. However, existing unified multimodal datasets and benchmarks remain dominated by single-turn tasks. Even in recent multi-turn datasets,...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05279v1","title":"Möbius: A Unified Motion-Language Model Bridging Understanding and Generation","abstract":"We aim to build a truly unified motion model that can understand, generate, and edit human motion within a single framework. Existing motion UMMs remain only partially unified: motion understanding is handled by a language model, while generation is often delegated to a separate diffusion module operating over learned motion latents. We introduce Möbius, which brings the entire diffusion process into the same multimodal representation space used for motion understanding. Clean motion, noisy motion, and text jointly participate in shared attention, while role-specific parameters process understanding and generation streams. Importantly, Möbius operates directly on continuous frame-level raw motion, requiring neither discrete tokenization nor a pretrained motion VAE. This simple formulation naturally supports motion captioning, text-to-motion generation, temporal completion, and instruction-guided editing within a single model. On HumanML3D, Möbius achieves state-of-the-art performance among unified motion models. Scaling to 1.7B parameters and 1,700 hours of motion data further demonstrates that our framework is both effective and scalable.","authors":["Jiazhi Shu","Chengfeng Zhao","Jinyi Wang","Yubo Zhao","Zhiyang Dou","Ronghui Li","Yu Lu","Xinwei Jiang","Zijiao Zeng","Yuan Liu"],"published":"2026-11-03T17:59:16Z","updated":"2026-11-03T17:59:16Z","abstract_url":"https://arxiv.org/abs/2611.05279v1","html_url":"https://arxiv.org/html/2611.05279v1","pdf_url":"https://arxiv.org/pdf/2611.05279v1.pdf","matched_keywords":["3d","representation","multimodal","diffusion"],"source_used":"html","source_text_chars":69653,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, multimodal, diffusion 相关；摘要显示其主要贡献为：We aim to build a truly unified motion model that can understand, generate, and edit human motion within a single framework. Existing motion UMMs remain only partially unified: motion understanding is handled by a language model, while generation is often del...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05275v1","title":"Route Anything: A Study of Model and Policy Routing for General-Purpose AI Systems","abstract":"Artificial general intelligence (AGI) requires a method that can understand, generate, reason, and act across diverse domains and modalities. Rather than relying on a single model to master every capability, a promising path toward AGI now is to orchestrate a heterogeneous ecosystem of specialized models, tools, and policies (candidates) into a unified AI system. At the heart of this vision lies a fundamental question: how can an AI system dynamically select and coordinate the most capable candidate for each task while balancing performance and computational cost? In this work, we present Route Anything, a unified framework for studying model and policy routing across general-purpose AI systems. We develop a unified theoretical foundation that characterizes optimal routing under quality--cost trade-offs and establishes how the information available to a router determines its attainable performance. To systematically investigate routing across diverse capabilities, we first construct an omni-modal trajectory matrix spanning 25 benchmarks across language understanding, image, video, and speech generation, coding and workplace agents, and robotic manipulation, comprising 374,401 scored runs from 452 candidate configurations. Building on this framework, we train and test different routers to investigate the potential of omni-modal model routing, the capabilities of learned routers, and the conditions under which routing improves efficiency. Our results reveal substantial opportunities for capability orchestration: per-input oracle routing outperforms the best fixed candidate by 5.4 points, and learned routers outperform it by 0.3 points across 16 benchmarks, by 2.1 points on video generation, and by 1.1 points on robot manipulation while using 24% less policy time. More importantly, routing raises efficiency by 8.82x on average compared with the reference model.","authors":["Pengfei Zhou","Yixing Ma","Hexin Wang","Weidong Tang","Zhenglin Wan","Wangbo Zhao","Yang You"],"published":"2026-11-03T17:56:42Z","updated":"2026-11-03T17:56:42Z","abstract_url":"https://arxiv.org/abs/2611.05275v1","html_url":"https://arxiv.org/html/2611.05275v1","pdf_url":"https://arxiv.org/pdf/2611.05275v1.pdf","matched_keywords":["video","agent"],"source_used":"html","source_text_chars":133164,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, agent 相关；摘要显示其主要贡献为：Artificial general intelligence (AGI) requires a method that can understand, generate, reason, and act across diverse domains and modalities. Rather than relying on a single model to master every capability, a promising path toward AGI now is to orchestrate a...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05231v1","title":"Diagnosis by Composition: Detecting and Localizing Unseen Diseases by Composing Learned Radiological Findings","abstract":"Deep models for radiological diagnosis are typically trained to predict disease labels directly from images, which limits them to diseases seen during training and makes their decisions hard to interpret in radiologists' terms. Radiology, however, proceeds from visual findings to disease through published guidelines that make this decision rule explicit, interpretable, and reproducible. We introduce diagnosis by composition (DbC), a representation learning framework that encodes this findings-first logic. DbC learns a vocabulary of radiological findings by aligning image features with the text embeddings of the findings, each finding represented as a dense map over the scan. A disease is defined by a set of required findings derived from its guidelines, and its diagnosis map is a fixed, parameter-free composition of the corresponding finding maps. Because the finding-to-disease mapping is derived from guidelines rather than learned, DbC is interpretable and auditable by design, can extend to new diseases by specifying their findings without retraining, and can diagnose unseen diseases by composing their findings. On multi-phase liver CT, DbC detects and localizes unseen diseases, rare diseases from a different institution, and an external cohort significantly better than all comparators, including models that align images with disease names. DbC also improves detection and localization in the fully supervised setting and remains superior across training-set sizes. Although demonstrated on liver CT, DbC applies wherever radiological guidelines define diseases through findings.","authors":["Kaihua Hou","Wei Liu","Yi Huang","Hao Zhang","Haibo Jin","Yifei Sun","Yuan gao","Zuoou Li","Ling Zhang","Ahmed Alaa","Geoffrey H. Tison","Xu Han","Ke Yan"],"published":"2026-11-03T17:14:51Z","updated":"2026-11-03T17:14:51Z","abstract_url":"https://arxiv.org/abs/2611.05231v1","html_url":"https://arxiv.org/html/2611.05231v1","pdf_url":"https://arxiv.org/pdf/2611.05231v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":99002,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Deep models for radiological diagnosis are typically trained to predict disease labels directly from images, which limits them to diseases seen during training and makes their decisions hard to interpret in radiologists' terms. Radiology, however, proceeds fr...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:13+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05206v1","title":"Diffusion Plug-in Priors for Self-Supervised Ultrasound Video Restoration","abstract":"\\textit{Objective:} Ultrasound videos are limited by hardware-constrained spatial resolution and signal-dependent speckle, while paired low- and high-resolution acquisitions for supervised restoration are rarely available. We aim to jointly super-resolve and despeckle ultrasound videos without paired training data or network retraining. \\textit{Methods:} We propose UltraDiff, which uses a frozen pre-trained diffusion model (DM) as a plug-in prior and restores each frame by optimizing the latent seed of the DM sampler under a range-constrained maximum a posteriori formulation. We derive a speckle-aware data-fidelity term from a Rayleigh scale-family model and characterize its relative-residual and variance-adaptive weighting properties. We further introduce a stabilized fidelity that is bounded below and strictly convex in log intensity for positive observations in its unclamped form. A total-variation regularizer complements the DM prior, and a temporal seed update warm-starts each frame from the optimized seed of its predecessor. \\textit{Results:} On EchoNet-LVH videos with simulated speckle and additive noise, UltraDiff with a natural-image prior improves PSNR by 1.24\\,dB over the strongest baseline, and ultrasound-related priors improve it further. On real clinical echocardiography videos, UltraDiff reduces the mean absolute error of zero-shot ejection fraction (EF) prediction from 7.31 to 6.37 EF points relative to DUP, the strongest baseline. \\textit{Conclusion:} Combining a speckle-aware fidelity with frozen diffusion priors enables ground-truth-free ultrasound video restoration that benefits downstream measurement. \\textit{Significance:} UltraDiff needs neither paired data nor retraining and is not tied to a specific diffusion checkpoint. Code associated with this work will be made publicly available upon acceptance.","authors":["Chu Chen","Mingduo He","Yining Li","Yinhao Wu","Wei Tang","Yiwen Luo","Yixuan Chen","Graham Treece","Pasquale Cascarano","Kangning Cui"],"published":"2026-11-03T16:55:01Z","updated":"2026-11-03T16:55:01Z","abstract_url":"https://arxiv.org/abs/2611.05206v1","html_url":"https://arxiv.org/html/2611.05206v1","pdf_url":"https://arxiv.org/pdf/2611.05206v1.pdf","matched_keywords":["video","diffusion"],"source_used":"html","source_text_chars":54147,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, diffusion 相关；摘要显示其主要贡献为：\\textit{Objective:} Ultrasound videos are limited by hardware-constrained spatial resolution and signal-dependent speckle, while paired low- and high-resolution acquisitions for supervised restoration are rarely available. We aim to jointly super-resolve and...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05197v1","title":"Robust Reconstruction of Power Lines from Incomplete Mobile and Aerial LiDAR Data","abstract":"Accurate vegetation-encroachment assessment and risk mitigation require electric utilities to accurately locate and characterize distribution-network assets, including poles and power lines, and distinguish among medium-voltage, low-voltage, neutral, and telecommunication lines. Mobile and aerial Light Detection and Ranging (LiDAR) point clouds provide detailed 3D representations of these assets and their surroundings. However, power-line detection and reconstruction remain challenging because conductor returns are often sparse, incomplete, noisy, or occluded by vegetation. These challenges are especially significant in distribution networks, where lower pole heights and complex line configurations place conductors close to trees. In addition, mobile and aerial LiDAR datasets differ substantially in point density, viewing geometry, spatial coverage, and occlusion patterns. We propose a robust and automated reconstruction method combining scaled density-based clustering, robust polynomial fitting, and iterative fragment merging to recover individual conductors under severe data incompleteness and occlusion. Following semantic classification, the same reconstruction pipeline processes both mobile and aerial LiDAR data without modality-specific code or parameter tuning. The method is evaluated through degradation experiments, benchmarking, parameter sensitivity analysis, and large-scale validation. On the aerial dataset, it achieves 96.87% precision, 96.66% recall, a 96.76% F$_1$-score, and a geometric RMSE of 0.127 m. On the mobile dataset, where conductor-level reference annotations were unavailable, it achieves a point-to-model RMSE of 0.045 m and a reconstruction coverage of 95.27%. Source code, documentation, and evaluation data are publicly available at https://github.com/varen-project.","authors":["Mohamed Gaha","Damos Ayobo Abongo","Philippe Massicotte","Eya Ben Kacem","Wael Jaafar","Rami Langar","Christian Buteau"],"published":"2026-11-03T16:48:56Z","updated":"2026-11-03T16:48:56Z","abstract_url":"https://arxiv.org/abs/2611.05197v1","html_url":"https://arxiv.org/html/2611.05197v1","pdf_url":"https://arxiv.org/pdf/2611.05197v1.pdf","matched_keywords":["3d","representation"],"source_used":"html","source_text_chars":79858,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation 相关；摘要显示其主要贡献为：Accurate vegetation-encroachment assessment and risk mitigation require electric utilities to accurately locate and characterize distribution-network assets, including poles and power lines, and distinguish among medium-voltage, low-voltage, neutral, and tele...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05193v1","title":"Factorized MLLM Embeddings for Composed Image Retrieval","abstract":"Composed Image Retrieval (CIR) aims to retrieve a target image given a reference image and a modification text. Although recent approaches leveraging Multimodal Large Language Models (MLLMs) have shown significant progress, we argue that the MLLM's compositional understanding remains underutilized. This stems from directly mapping composed queries into a retrieval embedding via contrastive supervision alone, without explicitly resolving the intended visual modifications. In this work, we introduce Factorized MLLM Embeddings (FactEmbed), which decouples compositional query comprehension from building discriminative embeddings. Rather than directly projecting the composed query into a single embedding without internal reasoning, FactEmbed employs a set of factorized latents that simulate the intended visual modifications via an intermediate target imagination objective. This process encourages the latents to ground into target semantics before forming discriminative representations for retrieval. Subsequently, to propagate these factorized representations throughout the model for retrieval, we optimize a factor-level contrastive loss while distilling the decomposed representations into a deeper attention layer of the MLLM. Finally, for efficient inference, we retain the [EOS] token to establish a global-level embedding on top of these factorized latents, while we exploit the mean-pooled factorized latents to rerank a short candidate list at negligible cost, as both are produced by the same forward pass. Extensive evaluations demonstrate that FactEmbed outperforms prior works across CIR benchmarks.","authors":["WonJun Moon","Seongchan Kim","Dahun Kim","Seungryong Kim"],"published":"2026-11-03T16:46:45Z","updated":"2026-11-03T16:46:45Z","abstract_url":"https://arxiv.org/abs/2611.05193v1","html_url":"https://arxiv.org/html/2611.05193v1","pdf_url":"https://arxiv.org/pdf/2611.05193v1.pdf","matched_keywords":["retrieval","representation","multimodal"],"source_used":"html","source_text_chars":90388,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 retrieval, representation, multimodal 相关；摘要显示其主要贡献为：Composed Image Retrieval (CIR) aims to retrieve a target image given a reference image and a modification text. Although recent approaches leveraging Multimodal Large Language Models (MLLMs) have shown significant progress, we argue that the MLLM's compositio...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05192v1","title":"From Natural Images to Medical Scans: Transferability of Diffusion Models for Medical Image Generation","abstract":"Transfer learning from natural images is standard in supervised and increasingly adopted in self-supervised medical image analysis, but its role in generative modelling, and in particular diffusion denoisers, remains underexplored. Medical diffusion models typically train the denoiser from scratch, with no systematic evaluation of natural-image transfer. We analyse this across latent and pixel paradigms, model sizes (131M-952M) and two radiology datasets (RadImageNet, BraTS), and ask which aspects of transfer support generation. We find that: i) Natural-image initialisation consistently improves generation, by 21-34% relative gFID in pixel space against 14% in latent space, where the tokeniser supplies much of the prior. gFID gains mirror downstream pathology classification and radiomic-feature FD, both proxies for clinical fidelity. ii) Benefits reflect spatial structure, not semantics: semantic probing does not predict generation quality, whereas a spatial-structure metric adapted to internal denoiser representations tracks gFID at $|r|=0.85$, positioning spatial organisation as a channel through which pretraining manifests. iii) Mixed-domain denoiser training shows that natural and medical images share similar layer-wise representations up to the late blocks, and mixing natural images into medical training improves fidelity. iv) Transfer benefit is tied to natural image initialisation, outperforming in-domain medical pretraining and several reinitialisation schemes. Overall, natural image denoisers transfer positively to medical ones in our setup. Code is available at https://github.com/CAIROLab-Bern/rad-dit","authors":["Efthymios Georgiou","Ioannis Kakogeorgiou","Sarah Brüningk"],"published":"2026-11-03T16:46:15Z","updated":"2026-11-03T16:46:15Z","abstract_url":"https://arxiv.org/abs/2611.05192v1","html_url":"https://arxiv.org/html/2611.05192v1","pdf_url":"https://arxiv.org/pdf/2611.05192v1.pdf","matched_keywords":["representation","diffusion"],"source_used":"html","source_text_chars":74742,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation, diffusion 相关；摘要显示其主要贡献为：Transfer learning from natural images is standard in supervised and increasingly adopted in self-supervised medical image analysis, but its role in generative modelling, and in particular diffusion denoisers, remains underexplored. Medical diffusion models ty...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05181v1","title":"What Does the Model See? Representation Validity in Multimodal LLM-Based Video Analysis","abstract":"Multimodal large language models (MLLMs) allow social scientists to analyze video at scale, but researchers must decide which parts of a video to provide as input. We use the term representation validity to examine how text, audio, video, and combined inputs affect measurement and subsequent analysis. We compare input representations across six open-weight MLLMs and three human-annotated video datasets. No representation consistently performs best. On seven news-related constructs, native-video performance varies little across models (macro-F1 = .70-.77), while extracted-text performance ranges from .52 to .80. Three models perform better with text and three with video. Combining inputs rarely improves performance. Higher classification accuracy also does not reliably produce estimates closer to those based on human codes. The highest-F1 representation best reproduces human-coded regression coefficients in 17 of 42 comparisons. Even when each model uses its highest-F1 deployable representation, 45% of sample-prevalence estimates differ from the human-coded benchmark by more than ten percentage points. Input representation therefore requires validation for both the construct being measured and the quantity estimated from the resulting labels.","authors":["Christian Pipal","Eva-Maria Vogel","Morgan Wack"],"published":"2026-11-03T16:42:49Z","updated":"2026-11-03T16:42:49Z","abstract_url":"https://arxiv.org/abs/2611.05181v1","html_url":"https://arxiv.org/html/2611.05181v1","pdf_url":"https://arxiv.org/pdf/2611.05181v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"html","source_text_chars":119026,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 video, representation, multimodal 相关；摘要显示其主要贡献为：Multimodal large language models (MLLMs) allow social scientists to analyze video at scale, but researchers must decide which parts of a video to provide as input. We use the term representation validity to examine how text, audio, video, and combined inputs...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05158v1","title":"Perturb, Repair, Verify: Self-Play Vision-Language Verifiers for Compositional Understanding","abstract":"Vision-language verifiers judge whether an image faithfully matches a textual description, yet existing training pipelines typically rely on static supervision from stronger external judges or curated hard-negative data. Such supervision requires external generation or annotation, is teacher-bounded, and is difficult to adapt as model failures evolve. We introduce PROVE (Perturb-and-Repair Optimization for Vision-Language Evaluation), a self-play framework that trains verifiers through a closed perturb-verify-repair-verify loop. Starting from a known-correct image-caption pair, a Mutator introduces a typed perturbation over objects, attributes, counts, or relations. The verifier then judges the perturbed caption and provides textual feedback, which a Repairer uses to recover a faithful caption for re-verification. These two verification rounds produce structured rewards for informative mismatches and visually grounded repairs. Since perturbation, verification, and repair are role-conditioned behaviors of the same evolving multimodal backbone, updating the shared parameters also improves the verifier itself. Experiments show that PROVE improves fine-grained compositional verification across model scales and families and strengthens visual-detail robustness on the reference backbone, with limited, benchmark-dependent changes on broader multimodal tasks.","authors":["Zijun Huang","Yingjun Du","Cees G. M. Snoek"],"published":"2026-11-03T16:31:34Z","updated":"2026-11-03T16:31:34Z","abstract_url":"https://arxiv.org/abs/2611.05158v1","html_url":"https://arxiv.org/html/2611.05158v1","pdf_url":"https://arxiv.org/pdf/2611.05158v1.pdf","matched_keywords":["multimodal"],"source_used":"html","source_text_chars":101923,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal 相关；摘要显示其主要贡献为：Vision-language verifiers judge whether an image faithfully matches a textual description, yet existing training pipelines typically rely on static supervision from stronger external judges or curated hard-negative data. Such supervision requires external gen...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05131v1","title":"High-fidelity training-free photovoltaic module mapping from multi-view UAV imagery","abstract":"High-fidelity photovoltaic (PV) module mapping requires complete instance recovery and accurate delineation. Vision foundation models offer zero-shot segmentation, but converting incomplete and inconsistent predictions across views into a complete, geometrically accurate map of individual modules remains challenging. We propose the Multi-View PV Module Mapper (MV-PVMapper), a training-free framework coupling vision foundation models with unmanned aerial vehicle (UAV) photogrammetry. First, Segment Anything Model 3 (SAM 3) generates candidates from original images using text prompts. Their contours are then transferred into object space through per-module slope correction to limit distortion from surface-model noise, and verified against representative module dimensions to guide cross-view instance selection. Finally, accepted instances return to all covering images as box prompts for SAM~3, supplementing text prompts with spatial cues for iterative segmentation, verification and fusion. On five-direction surveys of three operational rooftop PV plants at approximately 1 cm nadir ground sampling distance, two feedback iterations recover 7,710 of 7,711 reference modules with no false positives at an intersection-over-union (IoU) matching threshold of 0.5. Macro-averaged area precision and recall reach 99.00 % and 98.52 %, respectively. Averaged across sites, the aggregated Jaccard index reaches 97.55 %, compared with 60.73 % and 41.24 % for orthomosaic segmentation and multi-view pixel-voting baselines, respectively; average precision at the stricter IoU threshold of 0.95 reaches 95.67 %. Ablation studies show that module-size constraints are critical for instance separation, while slope correction and feedback to all covering views improve boundary accuracy. These results are achieved without task-specific image annotation or segmentation-model weight updates.","authors":["WenHao Duana","Qi Chena","Penglei Zhang","Ruizhe Deng","Zhiling Guo","Haoran Zhang","Yuntian Chen"],"published":"2026-11-03T16:14:16Z","updated":"2026-11-03T16:14:16Z","abstract_url":"https://arxiv.org/abs/2611.05131v1","html_url":"https://arxiv.org/html/2611.05131v1","pdf_url":"https://arxiv.org/pdf/2611.05131v1.pdf","matched_keywords":["instance"],"source_used":"html","source_text_chars":71633,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 instance 相关；摘要显示其主要贡献为：High-fidelity photovoltaic (PV) module mapping requires complete instance recovery and accurate delineation. Vision foundation models offer zero-shot segmentation, but converting incomplete and inconsistent predictions across views into a complete, geometrica...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05106v1","title":"Label-Preserving Fourier Domain Adaptation with Generative-AI and Real Style Donors for 3D Mitral Valve Segmentation","abstract":"Accurate segmentation of the mitral valve from three-dimensional transesophageal echocardiography (3D TEE) is severely restricted by the scarcity of publicly available expert- annotated volumetric datasets. To address this critical limitation, we investigated Fourier Domain Adaptation (FDA), utilizing general-purpose generative-AI images (from platforms like Chat- GPT, Google Gemini, and Microsoft MAI) as annotation-free style donors for 3D mitral valve segmentation. We employed a DeepMitral residual U-Net model on the public MVSeg2023 dataset, comparing six conditions over three runs: real-only training, traditional augmentation, FDA with each generative source, and a non-AI FDA control using real-image style donors, plus an optimization-matched real-only control and a \\b{eta} sensitivity analysis. Case-level paired testing showed that FDA with these generative sources led to significant reductions in boundary- and surface-related errors across all three donor conditions relative to the primary real-only baseline. However, the impact on the core segmentation metric, Generalized Dice Score (GDS), proved generator-dependent. ChatGPT-FDA showed a significant GDS advantage over the optimization-matched control but not over the primary baseline, and Gemini-FDA showed no significant GDS difference. Notably, only MAI-FDA provided a statistically robust and significant increase in GDS compared to the primary baseline. The \\b{eta} sensitivity was not robust across training runs. These findings confirm that FDA remains an important augmentation mechanism. While generative-AI images offer a practical means of acquiring style diversity without new annotations, the non-AI control performed comparably to ChatGPT-FDA, so we do not conclude that this approach is superior to training with real-image donors.","authors":["Javeria Javed","Ahmed Salim","Muhammad Mahboob Ur Rahman"],"published":"2026-11-03T16:01:44Z","updated":"2026-11-03T16:01:44Z","abstract_url":"https://arxiv.org/abs/2611.05106v1","html_url":"https://arxiv.org/html/2611.05106v1","pdf_url":"https://arxiv.org/pdf/2611.05106v1.pdf","matched_keywords":["3d"],"source_used":"html","source_text_chars":46266,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d 相关；摘要显示其主要贡献为：Accurate segmentation of the mitral valve from three-dimensional transesophageal echocardiography (3D TEE) is severely restricted by the scarcity of publicly available expert- annotated volumetric datasets. To address this critical limitation, we investigated...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05102v1","title":"Characterizing the vertical continuity of fuel strata based on TLS point clouds Gaussian decomposition and overlap metrics","abstract":"Vertical forest structure influences fire behavior by regulating understory-to-canopy fuel connectivity, yet operational fuel-type models represent this complexity through discrete classes that only indirectly capture vertical continuity. High-density point clouds offer an opportunity to characterize vertical fuel connectivity in a more explicit and continuous manner, but specific methodological approaches are still required. We applied Gaussian decomposition to vertical height profiles derived from terrestrial laser scanning (TLS) point clouds across 25 permanent forest plots to characterize geometric vertical fuel continuity. A multiscale analysis spanning from the plot scale to ~0.5 $m^2$ units was used to evaluate geometric, probabilistic, and overlap metrics for characterizing fuel strata. The method reproduced the vertical transition between shrub and tree strata, with median Pearson correlations ranging from 0.83 to 0.96 across analysis levels. Probability density overlap metrics and separability indicators, such as the Jeffries-Matusita distance, provided complementary descriptors of vertical continuity. Intermediate spatial scales (3-6 m cells) provided a useful compromise between spatial detail and the consistent representation of shrub-canopy interaction patterns. Finer scales increased variability due to point density reduction and profile irregularity, and low mean squared error values were found insufficient as sole performance indicators. Gaussian decomposition applied to TLS point clouds enables explicit quantification of vertical fuel continuity, a limitation of current discrete classification systems. Continuous vertical connectivity metrics derived from this approach offer a pathway for improving ladder fuel characterization and strengthening decision-making support in wildfire risk assessment.","authors":["Jesús Torralba","Luis Á. Ruiz","Pablo Crespo-Peremarch","Marina Simó-Martí","Juan Pedro Carbonell-Rivera"],"published":"2026-11-03T15:56:46Z","updated":"2026-11-03T15:56:46Z","abstract_url":"https://arxiv.org/abs/2611.05102v1","html_url":"https://arxiv.org/html/2611.05102v1","pdf_url":"https://arxiv.org/pdf/2611.05102v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":1968,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Vertical forest structure influences fire behavior by regulating understory-to-canopy fuel connectivity, yet operational fuel-type models represent this complexity through discrete classes that only indirectly capture vertical continuity. High-density point c...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"abstract","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05083v1","title":"Manifold Embedding of Deep Image Features for Image Matching via Neural Adjoint Maps","abstract":"Estimating semantic correspondences between different object instances of similar categories in real-world images is a fundamental challenge in computer vision. While the recent progress in foundation models has significantly advanced solutions for such difficult image correspondence problems, respective methods are often insufficiently regularised. For example, common nearest-neighbour matching with foundation model features often results in noisy correspondences, which is particularly prominent when solving for dense correspondences. In this work, we tackle image matching via functional maps, which have been popularised for 3D shape matching due to their powerful spectral formalism utilising an efficient low-dimensional linear representation. However, functional maps require that domains (in our cases the rectangular image grids) are equipped with an informative and non-trivial geometry. To define a meaningful manifold structure for images, we use Galerkin's method from finite elements to derive a discrete Laplace-Beltrami operator (LBO) based on a manifold embedding of deep image features. Further, we leverage a neural adjoint map that allows to represent non-linear mappings. We demonstrate that our method sets the new state of the art among zero-shot image correspondence methods on multiple dense correspondence benchmarks of real-world images. Our code is publicly available: https://github.com/NafieAmrani/NAMI","authors":["Nafie El Amrani","Moritz Heep","Florian Bernard"],"published":"2026-11-03T15:42:20Z","updated":"2026-11-03T15:42:20Z","abstract_url":"https://arxiv.org/abs/2611.05083v1","html_url":"https://arxiv.org/html/2611.05083v1","pdf_url":"https://arxiv.org/pdf/2611.05083v1.pdf","matched_keywords":["3d","representation","instance"],"source_used":"html","source_text_chars":110150,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 3d, representation, instance 相关；摘要显示其主要贡献为：Estimating semantic correspondences between different object instances of similar categories in real-world images is a fundamental challenge in computer vision. While the recent progress in foundation models has significantly advanced solutions for such diffi...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:14+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05072v1","title":"Trajectory Evaluation via Rollout-Free World Model for End-to-end Autonomous Driving","abstract":"Although existing candidate trajectory evaluators have substantially improved end-to-end planning accuracy, their underlying mechanism remains suboptimal. Model-based evaluators typically make scoring future-aware by explicitly predicting candidate-conditioned future states over the planning horizon, which we term rollout. However, rollout incurs high inference cost and accumulates prediction errors. We argue that planning does not require reconstructing a full future scene for each candidate, but only future-relevant information for reliable comparison. We therefore propose RFWorld, a Rollout-Free World model for end-to-end trajectory evaluation. RFWorld constructs a shared scene memory and shapes it into a future-readable representation via lightweight training-time temporal readout with semantic supervision, keeping training overhead low. At inference time, candidate trajectories directly query the shared memory via sparse spatial readout for scoring, reducing computation by roughly the planning horizon times the number of candidate trajectories, while avoiding recursive rollout errors. Experiments on NAVSIM and Bench2Drive show that RFWorld learns a more planning-aligned world representation and achieves state-of-the-art performance.","authors":["Junzhe Wang","Jinqing Zhang","Qingjie Liu"],"published":"2026-11-03T15:36:04Z","updated":"2026-11-03T15:36:04Z","abstract_url":"https://arxiv.org/abs/2611.05072v1","html_url":"https://arxiv.org/html/2611.05072v1","pdf_url":"https://arxiv.org/pdf/2611.05072v1.pdf","matched_keywords":["representation"],"source_used":"html","source_text_chars":58700,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 representation 相关；摘要显示其主要贡献为：Although existing candidate trajectory evaluators have substantially improved end-to-end planning accuracy, their underlying mechanism remains suboptimal. Model-based evaluators typically make scoring future-aware by explicitly predicting candidate-conditione...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:15+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05066v1","title":"VIGOR: Visual Gain Ordering for Hallucination Mitigation in Multimodal Discrete Diffusion Language Models","abstract":"Multimodal discrete diffusion language models (dLLMs) generate responses through iterative mask prediction and offer a promising alternative to autoregressive large vision-language models. However, they still suffer from hallucination, producing outputs that are plausible under language priors but insufficiently grounded in the image. We argue that hallucination in multimodal dLLMs is not only a token prediction problem, but also a premature commitment problem: during iterative denoising, some masked positions are unmasked too early because their confidence is driven more by language priors than by visual evidence, and these early commitments can bias later generation. To address this issue, we propose Visual Gain Ordering (VIGOR), a training-free and plug-and-play inference strategy that reorders masked positions according to counterfactual visual evidence. At each denoising step, VIGOR compares the confidence of each candidate token under the original image-conditioned pass and an additional visual-ablation pass, and prioritizes positions whose predictions are more strongly supported by the image. Experiments on LLaDA-V and Lumina-DiMOO show that VIGOR consistently reduces hallucination and improves multimodal reasoning performance across benchmarks. Code is available at https://github.com/THU-BPM/Vigor.","authors":["Junzhe Chen","Tian Qin","Eugenie Shi","Tianshu Zhang","Qiang Ju","Lijie Wen"],"published":"2026-11-03T15:28:11Z","updated":"2026-11-03T15:28:11Z","abstract_url":"https://arxiv.org/abs/2611.05066v1","html_url":"https://arxiv.org/html/2611.05066v1","pdf_url":"https://arxiv.org/pdf/2611.05066v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"html","source_text_chars":76734,"summary":{"model":"fallback-no-api","core_contribution":"该论文与 multimodal, diffusion 相关；摘要显示其主要贡献为：Multimodal discrete diffusion language models (dLLMs) generate responses through iterative mask prediction and offer a promising alternative to autoregressive large vision-language models. However, they still suffer from hallucination, producing outputs that...","method":"未配置 OPENAI_API_KEY，方法细节未调用模型总结。","source_used":"html","created_at":"2026-11-04T07:10:15+00:00","status":"fallback"},"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05062v1","title":"FloMo: 3D Scene Flow as a World Action Model Intermediate for Learning from Human Video","abstract":"Pretrained video generation models distill internet-scale motion priors into robot policies, but full video is a redundant signal for action prediction. We argue that dense 3D motion is the medium through which video pretraining best transfers to robot actions, and that predicting motion rather than video affords better sample-efficiency for action prediction. FloMo is a 5B video-generation model fine-tuned to predict 3D scene-flow and action tokens. Rendering scene flow as RGB and encoding it into the same latent space as video enables a pretrained video generation backbone to efficiently adapt to predict 3D scene flow. Co-trained on action-free human video and action-labeled robot teleoperation data, our model benefits from human-video pretraining and generalizes to unseen objects, motion primitives, and tasks. Replacing motion prediction with a video prediction objective degrades out-of-distribution generalization, while adding a video prediction target alongside motion lowers policy success rather than improving it. When motion, video, and action are predicted jointly, action tokens attend far more to motion than to video, suggesting that predicting video wastes model capacity. Together, these results indicate that motion effectively mediates the transfer from video pretraining to action. More information can be found at flomo-wam.github.io.","authors":["Jeremy Collins","Namra Patel","Ayush Agarwal","Shitij Govil","Animesh Garg"],"published":"2026-11-03T15:25:35Z","updated":"2026-11-03T15:25:35Z","abstract_url":"https://arxiv.org/abs/2611.05062v1","html_url":"https://arxiv.org/html/2611.05062v1","pdf_url":"https://arxiv.org/pdf/2611.05062v1.pdf","matched_keywords":["video","3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05058v1","title":"Do Agentic Policies Need to Look at Every Step? Geometric Abstraction for Reasoning and Action","abstract":"Recent multimodal language models can reason directly about robot scenes, but it is unclear whether they need to repeatedly reinterpret raw visual observations at every step of an interaction. We propose shifting routine spatial reasoning from images to text and symbols through a 3D geometric abstraction that is refreshed locally from observations and read directly by the language models. Specifically, our interface represents scene geometry via typed, evidence-aware symbolic references to object parts, grounds them from calibrated RGB-D, and returns compact textual checkpoints with metric residuals after each action. Symbolic task structure can thus be reused across decisions while metric values are rebound to the current scene, with direct visual reasoning invoked only on demand. Across offline policy synthesis and continuous online execution, reasoning over grounded text and symbols improves multi-step manipulation completion while substantially reducing repeated multimodal queries, positioning explicit geometric state as an effective substrate for agentic robot policies.","authors":["Yihang Liu","Yiming Chen","Mingzhe Zheng"],"published":"2026-11-03T15:22:46Z","updated":"2026-11-03T15:22:46Z","abstract_url":"https://arxiv.org/abs/2611.05058v1","html_url":"https://arxiv.org/html/2611.05058v1","pdf_url":"https://arxiv.org/pdf/2611.05058v1.pdf","matched_keywords":["3d","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.05049v1","title":"On the Learnability of Footwear Robustness: Footstep Recognition Under Unseen Conditions","abstract":"Footstep patterns, captured using pressure or force-sensitive walkways during natural walking, offer a convenient and passive approach to biometric recognition. However, footwear variability poses a major challenge to practical deployment, as it impacts both the foot-sensor interface and the user's underlying gait mechanics. This study considers the particularly difficult scenario where users enroll under one fixed footwear condition but must later be recognized in arbitrary, unseen footwear. Using the StepUP-P150 dataset, we show that footwear-induced shift, while substantial and heterogeneous across individuals, contains shared structure that can be learned from a training population and transferred, zero-shot, to previously unseen users and footwear styles. We do this using BiStepNet, a novel architecture that decomposes spatial and temporal identity cues into independently trainable streams and outperforms compact 3D spatiotemporal baselines for cross-footwear recognition. We demonstrate that cross-footwear recognition performance scales systematically with the volume and diversity of footwear representation in the training set, with gains transferring to footwear styles not directly observed during training. Moreover, we show that auxiliary gait datasets with only partial modality overlap (incorporated through the architecture's decomposed design) can be leveraged to further improve robustness to unseen footwear conditions.","authors":["Robyn Larracy","Erik Scheme"],"published":"2026-11-03T15:16:30Z","updated":"2026-11-03T15:16:30Z","abstract_url":"https://arxiv.org/abs/2611.05049v1","html_url":"https://arxiv.org/html/2611.05049v1","pdf_url":"https://arxiv.org/pdf/2611.05049v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04980v1","title":"ProAlign: Progressive Positional and Prototype-Guided Alignment for Aerial-Ground Person Re-Identification","abstract":"Aerial-Ground Person Re-Identification (AG-ReID) aims to match pedestrian images captured by unmanned aerial vehicles (UAVs) and ground-based surveillance cameras. The task remains highly challenging due to severe viewpoint discrepancies, frequent occlusions, and substantial domain gaps between aerial and ground imagery. Beyond these observable factors, existing methods often overlook two fundamental structural issues: cumulative positional drift during hierarchical feature extraction and semantic inconsistency across cross-view feature distributions. To address these challenges, we propose ProAlign, a Progressive Positional and Prototype-Guided Alignment Network for AG-ReID. ProAlign comprises two key components: a Layer-wise Progressive Positional Embedding (LPPE) module and a View-Aware Prototype Contrastive Learning (PCL) module. LPPE performs adaptive positional calibration throughout transformer layers by employing conditional positional encoding in shallow layers to mitigate local spatial distortions, while introducing learnable static positional embeddings in deeper layers to reinforce global semantic priors. Meanwhile, PCL maintains view-specific aerial and ground prototypes for each identity and enforces cross-view semantic consistency via a dual-prototype contrastive objective. Extensive experiments on CARGO and two real-world AG-ReID benchmarks demonstrate the effectiveness of ProAlign, achieving state-of-the-art overall retrieval performance on CARGO with improvements of 1.60% in Rank-1 accuracy and 5.01% in mAP over the strongest competing methods.","authors":["Qiao Li","Jing Chen","Cong Wu","Kun He","Ruiying Du","Lei Tan"],"published":"2026-11-03T14:33:13Z","updated":"2026-11-03T14:33:13Z","abstract_url":"https://arxiv.org/abs/2611.04980v1","html_url":"https://arxiv.org/html/2611.04980v1","pdf_url":"https://arxiv.org/pdf/2611.04980v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04960v1","title":"An Agentic Framework for Quality-Aware and Scenario-Adaptive Image Compression","abstract":"Despite decades of progress, image codecs remain difficult to adapt to diverse real-world compression scenarios for two main reasons. First, most image codecs are optimized for a specific objective and require substantial redevelopment when the compression goal changes. Second, they typically assume clean inputs, whereas sensor-captured images often contain degradations that alter rate-quality behavior. To address these challenges, we propose Practical Image Coding Agents (PICA), a multi-agent framework that adapts existing codecs to diverse user requirements and potentially degraded inputs. PICA consists of four collaborative agents: a Perception agent that interprets user intent and analyzes image content, an Improvement agent that jointly considers bitrate and reconstruction quality to guide pre-coding restoration, a Coding agent that refines quality-control settings from global to regional levels, and an After-coding improvement agent that addresses residual degradations and compression-induced artifacts through restoration guided solely by image quality. To enable codec-agnostic regional adaptation, we introduce Agentic ROI Coding (AROIC), which treats the codec as a black box and allows the agent to automatically schedule, execute, evaluate, and reflect ROI coding plans without architectural modifications or codec-specific retraining. We integrate these four agents with a Scenario-Guided Quality-Rate (SGQR) evaluation strategy to enable more effective scenario-adaptive compression across heterogeneous codecs. Comprehensive experiments on clean, noisy, and blurred images across standard, perceptual, and machine-vision compression scenarios demonstrate that PICA consistently enhances the compression performance of both the conventional H.266/VVC codec and the neural Cheng2020 codec, outperforming competing compression methods on the Kodak, CLIC2020, and HEVC datasets.","authors":["Zhenghao Chen","Lebin Zhou","Zicong Chen","Naifu Xue","Jiahao Li","Bin Li","Dong Xu","Yan Lu"],"published":"2026-11-03T14:19:39Z","updated":"2026-11-03T14:19:39Z","abstract_url":"https://arxiv.org/abs/2611.04960v1","html_url":"https://arxiv.org/html/2611.04960v1","pdf_url":"https://arxiv.org/pdf/2611.04960v1.pdf","matched_keywords":["agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04950v1","title":"DPAGait: Dynamic Pose-Knowledge-Aware Network for Robust Gait Recognition in the Wild","abstract":"Gait biometrics aims at identity recognition by appearance or pose features captured during unconstrained human walking. Existing methods predominantly rely on binary silhouette images, inherently characterized by low information entropy, and fail to fully utilize the dynamic information in gait sequences, limiting their ability to handle cross-time variations effectively. Consequently, these methods encounter significant challenges in the wild. They are susceptible to variations in clothing, carried objects, and viewpoints, as well as dynamic environmental conditions, all of which lead to substantial degradation in recognition accuracy and robustness. To overcome these challenges, we propose a pose-knowledge-aware approach specifically designed for robust gait recognition in the wild. First, we propose a novel Dynamic Pose-Parsing enhanced Silhouette gait representation paradigm that substantially enhances the information entropy and effectively captures fine-grained behavioral cues by integrating pose-parsing cues with traditional silhouettes. Subsequently, we develop a dual-branch Dynamic Pose-Knowledge-Aware Gait network. The framework consists of two complementary branches: (1) a 2D dynamic pose-aware branch that extracts pose-enhanced features from our proposed DPPS representations, and (2) a 3D Skinned Multi-Person Linear branch that leverages the 3D SMPL model to capture rich and comprehensive 3D dynamic pose information. Finally, the features are integrated to facilitate accurate and robust gait recognition. Extensive experiments on four challenging in-the-wild gait datasets demonstrate the effectiveness and generalizability of the proposed DPPS representation. The complete framework is further evaluated on SUSTech1K, CCPG, and Gait3D, where SMPL information is available or can be consistently estimated, achieving competitive performance under diverse real-world conditions.","authors":["Zenan Lin","Junduan Huang","Kun Liu","M. Saad Shakeel","Wenxiong Kang"],"published":"2026-11-03T14:11:15Z","updated":"2026-11-03T14:11:15Z","abstract_url":"https://arxiv.org/abs/2611.04950v1","html_url":"https://arxiv.org/html/2611.04950v1","pdf_url":"https://arxiv.org/pdf/2611.04950v1.pdf","matched_keywords":["3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04948v1","title":"PATTS: Parallel-Aware Test-Time Scaling for Thought-Image Generation in Multimodal Discrete Diffusion LLMs","abstract":"Test-time scaling (TTS) improves generative models by allocating additional inference-time computation to sampling, search, and verification. Existing image generation approaches, however, typically rank completed images or image-centric intermediate states. We study TTS for parallel multimodal discrete diffusion language models, in which reasoning tokens and image tokens are decoded jointly within a single generation trajectory. We first diagnose a limitation of conventional final-image selection: on GenEval, a CLIP-style image-prompt score is weakly aligned with within-prompt compositional correctness, leaving substantial headroom between verifier selection and oracle selection. We then propose PATTS, a novel parallel-aware TTS framework that searches over intermediate thought-image states using cross-modal verifier signals. PATTS uses a state-dependent reliability weight, derived from model-internal trajectory diagnostics, to modulate the influence of external semantic verification during generation. In the fixed N=32 evaluation on MMaDA-Parallel, the PATTS reaches a GenEval score of 0.844, compared with 0.628 without TTS, 0.787 for Best-of-N, and 0.810 for FKD. These results show that reliability-aware trajectory verification can improve test-time selection for parallel thought-image co-generation under the evaluated search budget. Our code release is at https://github.com/Ringo-Star/PATTS.git","authors":["Yasong Dai","Zeeshan Hayder","David Ahmedt-Aristizabal","Hongdong Li"],"published":"2026-11-03T14:10:56Z","updated":"2026-11-03T14:10:56Z","abstract_url":"https://arxiv.org/abs/2611.04948v1","html_url":"https://arxiv.org/html/2611.04948v1","pdf_url":"https://arxiv.org/pdf/2611.04948v1.pdf","matched_keywords":["multimodal","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04932v1","title":"VISTA: Vision-Language Integrated Semantic Triage Architecture for Online Face Clustering in Long Videos","abstract":"Clustering faces by identity in long, continuous video streams is a challenging task that serves as a building block for human-centric video analysis. The majority of existing face clustering models are offline, i.e., they assume the entire data to be available altogether. In many practical scenarios, however, the entire data is either unavailable or poses computational challenges to be processed in its entirety. A handful of online methods that exist rely on geometric visual features and simple thresholding techniques, which fail when the faces exhibit significant appearance variations in long, unconstrained videos. To this end, we present VISTA, the first vision language framework for online face clustering in long videos. VISTA leverages semantic reasoning in a controlled, uncertainty aware fashion to maintain both high cluster purity and long range identity continuity. This makes it robust to the variations in illumination, pose, and costume changes that the faces and characters exhibit in long real world videos. Extensive experiments on the VPCD benchmark dataset (with 15 full episodes from The Big Bang Theory [2007-2019], Buffy the Vampire Slayer [1997-2003], and Sherlock [2010-2017]) demonstrate that VISTA achieves a robust precision and recall balance, consistently improving over the strongest matched online unsupervised baseline (COFC) under identical detector, embeddings, and evaluation protocol. Code and supplementary material: https://github.com/SkyJiashu/VISTA.","authors":["Jiashu Liao","Joanne Garde-Hansen","Sanjay Sharma","Tanaya Guha"],"published":"2026-11-03T14:02:57Z","updated":"2026-11-03T14:02:57Z","abstract_url":"https://arxiv.org/abs/2611.04932v1","html_url":"https://arxiv.org/html/2611.04932v1","pdf_url":"https://arxiv.org/pdf/2611.04932v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04916v1","title":"Behind Video Generation: Observations and Insights on Multimodal Understanding from Kling","abstract":"Video generation has progressed from isolated clips to coherent short-form audiovisual sequences, and the bottleneck is shifting from rendering to semantic control. This report summarizes the observations and insights on multimodal understanding gained from successive generations of Kling. We argue that generation quality is the projection of multimodal understanding through the entire data--conditioning--alignment--evaluation chain, and we examine this chain module by module. Kling-MLLM, a shared multimodal foundation model that unifies image, video, audio, synchronized audio--video, and interleaved inputs, is specialized for each downstream module. Because a DiT is trained on far fewer training samples than a language model, we treat captioning as a semantic contract that maximizes description density, and extend it to reference-grounded captioning that makes reference bindings explicit. Prompt enhancement translates user intent into this caption distribution: basic PE is derived from captions of compelling videos and refined with text-level and generator-in-the-loop reinforcement learning, while agentic PE refines the story and retrieves compelling examples. We show that a reliable text encoder comes from perceptual training rather than from stronger language ability, and that candidates can be screened from text alone before end-to-end training. Reward modeling pairs a general reward model for explainable, localized critiques with a decision reward model for fast multidimensional scoring, treating perceptual bandwidth as a first-class design parameter. Finally, we review task-specific automatic evaluation, focusing on protocols that expose scoring shortcuts and help trace failures to their upstream source. We hope these lessons offer practical guidance for building the understanding stack behind controllable video generation.","authors":["Kling Team","Dong Chen","Jialu Chen","Xinlong Chen","Yifan Dai","Haotian Dong","Binzong Geng","Yushuo Guan","Minghui Guo","Guanlin He","Guanxiao He","Jingyun Hua","Yanwei Huang","Yiyan Ji","Xueping Jia","Yizhuo Jia","Bozhou Li","Jiaze Li","Min Li","Shihao Li","Shujie Li","Shengyi Liao","Weihong Lin","Shiyuan Liu","Xinyu Liu","Siyang Mao","Xiaoru Qu","Dianmo Sheng","Yang Shi","Jiafu Tang","Longxiang Tang","Yuqi Tang","Chengzhuo Tong","Kuo Wang","Qixun Wang","Rui Wang","Tianduo Wang","Yuran Wang","Zekun Wang","Zihao Wang","Boyang Xia","Yifan Xu","Liu Yang","Zhenlong Yuan","Bohan Zeng","Mujin Zhang","Yuanxing Zhang","Zhicheng Zhang","Zhuoran Zhang","Yuanhong Zheng","Kun Gai","Chengru Song","Pengfei Wan"],"published":"2026-11-03T13:56:06Z","updated":"2026-11-03T13:56:06Z","abstract_url":"https://arxiv.org/abs/2611.04916v1","html_url":"https://arxiv.org/html/2611.04916v1","pdf_url":"https://arxiv.org/pdf/2611.04916v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04913v1","title":"EP-LVMQA: Evidence-Preserving Coarse-to-Fine Localization for Low-Quality Long Video Moment Question Answering","abstract":"Long instructional videos are increasingly used in medical education, industrial training, and procedural knowledge transfer, yet their evidence is often incomplete or unreliable: subtitles may be missing, ASR noisy, OCR sparse, and decisive actions briefly shown without narration. Existing VideoQA systems typically return labels or free-form text, making answer support difficult to inspect. We study Long Video Moment Question Answering (LVMQA), where a system returns timestamped answer-supporting evidence. We propose EP-LVMQA, an evidence-preserving coarse-to-fine framework comprising an Uncertainty-Aware Multimodal Evidence Timeline, a Coarse Evidence Planner, and an Evidence-Conditioned Fine Localizer. An evidence card transfers planner scores, matched cues, source-confidence proxies, modality-specific evidence, neighboring context, and a temporal prior between the latter two modules. On MedVidQA, EP-LVMQA achieves 26.1 R1@0.5 and 31.8 mIoU, improving the strongest non-ours results by 6.3 and 5.1 points. It raises Suff.@2 and Ver.@2 to 25.4 and 22.6, gains of 9.5 and 8.8 points. Under matched low-quality perturbations, average relative degradation is reduced from the strongest non-ours value of 14.6% to 11.1%. On Ego4D-NLQ and QVHighlights, EP-LVMQA remains broadly comparable to established task-specific localization methods.","authors":["Guoning Chen","Zhexun Hu","Yifan Wei","Yixuan Weng","Bin Li","Yufei Zhao"],"published":"2026-11-03T13:53:08Z","updated":"2026-11-03T13:53:08Z","abstract_url":"https://arxiv.org/abs/2611.04913v1","html_url":"https://arxiv.org/html/2611.04913v1","pdf_url":"https://arxiv.org/pdf/2611.04913v1.pdf","matched_keywords":["video","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04912v1","title":"MiCaDe: Online LiDAR-Camera Miscalibration Change Detection for Autonomous Driving","abstract":"Reliable multi-sensor perception in autonomous vehicles requires accurate calibration between cameras and LiDAR. However, calibration drift is often unavoidable in long-term deployments: vibrations, thermal effects, and minor mechanical shocks may alter the relative pose between sensors, leading to systematic errors in downstream fusion tasks. We propose MiCaDe (Miscalibration Change Detection), an online solution detecting when the extrinsic LiDAR-camera calibration parameters are no longer accurate by means of sequential change detection. MiCaDe requires no calibration targets, or modification of the perception stack, providing low false-alarm rates with negligible computational overhead. Our key insight is that 3D and 2D bounding boxes produced by standard object detectors should remain geometrically consistent under correct calibration. By matching cross-modal detections, we derive geometric consistency metrics that serve as sensitive indicators of extrinsic drift. These metrics are aggregated into fixed-size batches and scored against a reference distribution, producing a likelihood stream that is monitored by a Change Point Model (CPM). Crucially, the CPM accumulates statistical evidence over time, enabling detection of subtle drifts that would otherwise go unnoticed. Experiments on multiple long-sequence datasets and on a real-world dataset with physically induced miscalibration confirm reliable detection under diverse conditions. Code available at: https://github.com/CarloSgaravatti/MiCaDe.","authors":["Carlo Sgaravatti","Riccardo Pieroni","Matteo Corno","Sergio M. Savaresi","Luca Magri","Giacomo Boracchi"],"published":"2026-11-03T13:52:45Z","updated":"2026-11-03T13:52:45Z","abstract_url":"https://arxiv.org/abs/2611.04912v1","html_url":"https://arxiv.org/html/2611.04912v1","pdf_url":"https://arxiv.org/pdf/2611.04912v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04903v1","title":"Heads That Write, Not Just Point: Image Retrieval Heads in Vision-Language Models","abstract":"Large vision-language models (LVLMs) can process interleaved text and multiple images in a single context, but how they internally identify the image relevant to a question remains poorly understood. We study this grounding step as in-context image retrieval and introduce ICIR-MCQ, a controlled probe for head-level analysis of image retrieval. Using each head's attention mass over image-token spans, we first identify sparse pointer heads that reliably point to the target image. These heads transfer beyond the probe: a single pointer head is competitive with external vision-language retrievers on a naturalistic multi-image retrieval benchmark, showing that LVLMs contain a strong internal image retrieval signal. Attention alone, however, shows where a head reads from, not what its output passes on to later layers, so we introduce a complementary output-side analysis. For each head, we train a lightweight image retriever on its value-weighted output and use it to identify writer heads, whose outputs contain enough information to identify the target image. Surprisingly, the pointer and writer criteria select substantially different head sets, with only 35 to 47 heads overlapping among the top-100 heads under each criterion. Targeted set-partition ablations show that the heads most important for standard multi-image inference are concentrated in this pointer-writer intersection, while heads selected by only one criterion show less consistent separation from random-head controls. The most consistent causal effects arise from heads selected by both the attention-based pointer and output-side writer criteria. Code and data: https://github.com/parkquasar/Image-Retrieval-Heads.","authors":["Junsung Park","Sangwon Yu","Donghun Kang","Yeongtak Oh","Jaewon Jeong","Gyeongtae Yoo","Han Cheol Moon","Jungbeom Lee","Sungroh Yoon"],"published":"2026-11-03T13:48:28Z","updated":"2026-11-03T13:48:28Z","abstract_url":"https://arxiv.org/abs/2611.04903v1","html_url":"https://arxiv.org/html/2611.04903v1","pdf_url":"https://arxiv.org/pdf/2611.04903v1.pdf","matched_keywords":["retrieval"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04894v1","title":"VisSearch-Bench: Evaluating Long Horizon Visual Search in Multimodal Agents","abstract":"Multimodal agents use web and image tools to answer questions beyond their internal knowledge. Some search tasks use images mainly to identify an initial entity, then rely on text retrieval. These tasks offer limited insight into how agents connect information across images, objects, and search steps. We therefore focus on visual context management. This involves organizing and using visual information and linking it to other findings during search. Visually intensive tasks require agents to combine object appearance, local details, or spatial relations with external information. We introduce VisSearch-Bench, with 204 human-written tasks across 7 main domains and 25 subdomains. It covers Set-wise Visual Search, Sequential Visual Search, Hybrid Wide-Deep Search, Competitive Visual Disambiguation, and Visual-Structure-Guided Search. Each task provides a reference answer, traceable evidence, and scoring rules. Accuracy measures complete task success, while Process Score measures the correctness and completeness of individual results and subquestion answers. Across 16 multimodal models, the best system fully solves only 26.47% of tasks, even with search tools. These results highlight the challenge of linking visual evidence with search results to produce complete answers.","authors":["ZhengXian Wu","Qianhao Nie","Zhuohong Chen","Junjie Gao","Yuyao Zhang","Yunyao Yu","Hangrui Xu","Cheng Cheng","Guiyu Ma","Jin Zhang","Xingzhong Xu","Kai Yang","Haoqian Wang"],"published":"2026-11-03T13:40:41Z","updated":"2026-11-03T13:40:41Z","abstract_url":"https://arxiv.org/abs/2611.04894v1","html_url":"https://arxiv.org/html/2611.04894v1","pdf_url":"https://arxiv.org/pdf/2611.04894v1.pdf","matched_keywords":["retrieval","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04873v1","title":"Trusting Imagined Futures: Auditing Imagined Rewards for VLA Post-Training","abstract":"Video world models enable candidate actions to be evaluated through imagined outcomes, but high predicted rewards can favor trajectories with poor execution quality. We introduce Trusting Imagined Futures (TIF), an offline supervision selection method for vision-language-action (VLA) post-training that audits predicted rewards using execution feedback. A multidimensional reward model predicts a utility score for candidate ranking and five dimensions of execution quality. An auditor uses reward predictions and uncertainty to identify overestimation patterns learned from paired imagined videos and real executions. TIF accepts the candidate with the highest predicted utility when its advantage over the existing trajectory exceeds a margin and its audit risk passes a threshold; otherwise, it retains the existing supervision. The retained real trajectories then supervise behavior cloning. Across four LIBERO suites and three training seeds, TIF achieves a mean success rate of 76.25%, improving over training on the existing trajectories by 3.00 percentage points with the same trajectory count and training budget. Adding audit gating yields 1.47 percentage points with the reward model and advantage margin held fixed. The gains persist against advantage ranking and logistic regression risk selection at matched replacement counts. On recorded videos from three real robot tasks, TIF increases clean completion among selected trajectories from 58.33% to 70.00% across 60 candidate pools.","authors":["Zicheng Kong","Zhenbo Xu","Haoyan Zhang","Jinghan Yang","Zhenzhen Li","Yiwei Ru","Liuyu Xiang","WanTing Xu","Min Ren","Zhaofeng He"],"published":"2026-11-03T13:26:53Z","updated":"2026-11-03T13:26:53Z","abstract_url":"https://arxiv.org/abs/2611.04873v1","html_url":"https://arxiv.org/html/2611.04873v1","pdf_url":"https://arxiv.org/pdf/2611.04873v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04811v1","title":"NightIQA: A Comprehensive Dataset and Benchmark for MLLM-Based Nighttime Image Quality Assessment","abstract":"Nighttime images are inherently susceptible to complex, compound degradations, making accurate quality assessment exceptionally challenging. Score-based IQA methods condense quality into a single number, lacking the multi-dimensional, language-grounded reasoning required for nighttime evaluation. Multimodal Large Language Models (MLLMs) offer a more comprehensive alternative, yet remain constrained by a critical data gap: existing real-world IQA datasets are overwhelmingly daytime-centric and often built from outdated captures, while synthetic alternatives lack nighttime-specific degradation modeling, yielding artifacts far removed from authentic nighttime conditions. To bridge this gap, we present NightIQA, a dataset and benchmark suite purpose-built for MLLM-based nighttime IQA. It comprises three core components: NightIQA-Real, a real-world dataset of 1,769 high-resolution images that we captured ourselves with modern equipment, encompassing six canonical distortion types and structured multi-dimensional annotations; NightIQA-Bench, a benchmark of 1,078 visually grounded multiple-choice questions tailored to MLLM-based nighttime IQA, organized around a four-level evaluation hierarchy spanning Perception, Technical Assessment, Localization, and Reasoning; and NightIQA-Syn, an inherently scalable, scene-aware synthesis pipeline that jointly models global-level and instance-level degradations, with an initial release of 80k high-fidelity images alongside the full generation code. Fine-tuned on NightIQA with Supervised Fine-Tuning (SFT) and Group Relative Policy Optimization (GRPO), Qwen3-VL-8B outperforms open-source IQA methods and achieves higher overall accuracy than leading closed-source models, highlighting the value of domain-specific data and structured supervision.","authors":["Yiding Tian","Jiaojiao Yi","Jiayuan Lu","Pufan Xu","Jinlin Wu","Changyuan Wen","Hongyuan Yu"],"published":"2026-11-03T12:42:30Z","updated":"2026-11-03T12:42:30Z","abstract_url":"https://arxiv.org/abs/2611.04811v1","html_url":"https://arxiv.org/html/2611.04811v1","pdf_url":"https://arxiv.org/pdf/2611.04811v1.pdf","matched_keywords":["instance","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04764v1","title":"Pixel-space video generation with U-JiT","abstract":"Latent diffusion and flow matching models are ubiquitous in state-of-the-art generative video models. While highly effective, relying on pretrained autoencoders to compress the data into a lower-dimensional latent space also comes with drawbacks. First, training proceeds in two stages: autoencoder pretraining, with compression and reconstruction objectives, followed by latent generative model training, precluding fully end-to-end training. Second, autoencoders also lead to an inherent loss of signal, and the trade-off between reconstruction quality and generative performance in the latent space is still an active area of research. In this paper we explore the viability of generative video models directly in pixel space. We analyze recent approaches in pixel-space generative modeling of images that rely on basic transformer designs, and identify several shortcomings that limit their effectiveness for the high-dimensional pixel-space video generation. To overcome these limitations, we propose a UNet-like transformer architecture along with improvements to the training recipe and sampling strategy. We conduct controlled experiments, training latent and pixel-space models from scratch on Kinetics-600. For the standard frames-to-video task at 128 resolution, our U-JiT model improves generative FVD by 27% over prior state-of-the-art results, and by 14% against the JiT pixel-space baseline. Scaling to higher 256 resolution, we find the improvement over pixel-space and latent-based models grows as we increase the spatiotemporal compression rate up to $64 \\times 64 \\times 8$. Finally, we find that U-JiT improves per-frame FID by 27% over latent models and 61% over pixel-space models on class-to-video generation, with respectively 9% and 56% reduction in FVD.","authors":["Théophane Vallaeys","Jakob Verbeek","Matthieu Cord"],"published":"2026-11-03T12:11:03Z","updated":"2026-11-03T12:11:03Z","abstract_url":"https://arxiv.org/abs/2611.04764v1","html_url":"https://arxiv.org/html/2611.04764v1","pdf_url":"https://arxiv.org/pdf/2611.04764v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04759v1","title":"Beyond Local Refinement: Wide-Area Precise Cross-View Localization","abstract":"Fine-grained cross-view localization aims to precisely localize a ground camera against geo-referenced aerial imagery, but current methods typically assume a narrow geographic prior, substantially limiting their applicability when upstream localization remains coarse. To bridge this gap, we study this task over much larger aerial regions. However, this seemingly simple extension fundamentally changes the localization problem: the growing disparity in spatial extent between ground and aerial views makes reliable cross-view matching difficult to establish directly, while the increasing number of look-alike locations in larger regions introduces substantial visual ambiguity. To address these challenges, we propose RingMatch, a search-and-verification framework for wide-area cross-view localization. RingMatch first leverages predictive uncertainty to uncover plausible locations and progressively zooms into their surroundings to obtain increasingly fine-grained evidence, yielding a compact set of promising candidates. We then introduce the depth ring, a novel geometric representation that reveals subtle variations in the spatial layout around a location and serves as a view-shared spatial signature for an LVLM verifier to resolve residual ambiguity. To benchmark this setting, we construct VIGOR-Pro by composing VIGOR aerial tiles into contiguous regions with spatial extents of up to 400 m. Experiments show that RingMatch maintains strong localization performance as the aerial region expands, consistently outperforming representative end-to-end and retrieval-based methods.","authors":["Qingguo Hu","Xinyu Ma","Yujie Lin","Yaoxiang Wang","Qi Shi","Zonghao Guo","Chi Chen","Jinsong Su"],"published":"2026-11-03T12:08:24Z","updated":"2026-11-03T12:08:24Z","abstract_url":"https://arxiv.org/abs/2611.04759v1","html_url":"https://arxiv.org/html/2611.04759v1","pdf_url":"https://arxiv.org/pdf/2611.04759v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04755v1","title":"iMED: A Multi-Endoscope Dataset for Surgical 3D Perception","abstract":"We introduce iMED, the first synchronized multi-endoscope dataset for robot-assisted minimally invasive surgery (RAMIS), designed to address a fundamental limitation in surgical vision benchmarking: the absence of independent held-out viewpoints. Existing surgical datasets capture single-trajectory sequences from a single endoscope, making it impossible to distinguish geometric generalization from photometric interpolation along a narrow forward-facing path. iMED provides 340 sequences ~170K synchronized timepoints with 4 views per timepoint) recorded simultaneously from two independent stereo endoscopes across ex vivo, postmortem, and live surgical settings, spanning 14 specimens with diverse anatomical regions and motion regimes. The dataset includes calibrated camera intrinsics, ArUco-based frame-wise pose estimates with uncertainty quantification, instrument segmentation masks, and rich clinical metadata. Using a train-on-one-endoscope, test-on-another evaluation protocol, we benchmark 23 state-of-the-art methods across rigid and deformable novel view synthesis, pose estimation, feature matching, and monocular depth estimation. Our experiments show that methods relying primarily on photometric supervision degrade substantially under this held-out-endoscope setting, while methods with explicit geometric regularization are more robust across views in our benchmark. Notably, large-scale foundation models transfer surprisingly well to surgical imagery, often outperforming domain-specific models, suggesting pitfalls in current fine-tuning protocols. iMED establishes a new evaluation protocol for geometric generalization in surgical vision.","authors":["Sierra Bonilla","Fengyi Jiang","Chinedu Nwoye","Jingpei Lu","Kailey Reardon","Humphrey W. Chow","Francisco Vasconcelos","Sophia Bano","Adam Schmidt","Omid Mohareri"],"published":"2026-11-03T12:06:58Z","updated":"2026-11-03T12:06:58Z","abstract_url":"https://arxiv.org/abs/2611.04755v1","html_url":"https://arxiv.org/html/2611.04755v1","pdf_url":"https://arxiv.org/pdf/2611.04755v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04728v1","title":"SPOD: Recovering Suppressed Temporal Evidence in Video-LLMs via Single-Pass Orthogonal Decomposition","abstract":"Video Large Language Models (Video-LLMs) have achieved strong performance on many video understanding tasks, yet remain vulnerable to temporal hallucination in time-sensitive reasoning scenarios such as scene transition understanding and event ordering. Existing solutions either require costly retraining or introduce inefficient multi-pass inference and external supervision at test time. In this work, we show that temporal evidence is already encoded in Video-LLM hidden representations but is not fully exploited during standard inference. Motivated by this observation, we propose Single-Pass Orthogonal Decomposition (SPOD), a training-free framework that recovers suppressed temporal evidence through analytical hidden-state manipulation in a single forward pass. SPOD consists of two components: Frame Distinctiveness Analysis (FDA), which identifies salient frames from middle-layer hidden-state geometry, and Temporal Delta Subspace (TDS), which constructs orthogonal temporal and prior subspaces from weighted inter-frame hidden-state differences. By decomposing final hidden states into temporal, prior, and residual components and rescaling them independently, SPOD enhances dynamic information, suppresses static appearance bias, and preserves complementary information. Experiments on VidHalluc, EventHallusion, and VideoMMMU show that SPOD consistently outperforms strong inference-time baselines across temporal reasoning tasks and model architectures while retaining near-vanilla inference efficiency. These results suggest that improving temporal reasoning in Video-LLMs may depend not only on additional supervision, but also on recovering temporal evidence already present in their internal representations. Our code is available at https://github.com/VioAgnes/SPOD.","authors":["Yangguang Lin","Quan Fang","Xiaoyan Liu","Zefan Xu"],"published":"2026-11-03T11:46:39Z","updated":"2026-11-03T11:46:39Z","abstract_url":"https://arxiv.org/abs/2611.04728v1","html_url":"https://arxiv.org/html/2611.04728v1","pdf_url":"https://arxiv.org/pdf/2611.04728v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04712v1","title":"VISAGE: Vertex-based Intrinsic Surface Appearance GEneration via Dual-Stream Diffusion for Arbitrary 3D Heads","abstract":"Recovering identity-faithful, physically based surface appearance for 3D human heads from sparse images remains challenging. Existing methods often rely on UV-based pipelines, introducing seam artefacts, or operate in image space, limiting surface consistency. We present VISAGE, Vertex-based Intrinsic Surface Appearance GEneration, a surface-based conditional diffusion framework that synthesises per-vertex albedo and roughness directly on arbitrary mesh topologies, without requiring consistent UV parameterisation at training time. VISAGE combines global spectral processing with local geodesic K-Nearest-Neighbour refinement, enforcing structural coherence while restoring detail beyond the truncated spectral basis. Multi-view RGB images condition the network via visibility-aware cross-attention, enabling occlusion-robust synthesis across the full head surface. Region-specific modules specialise in semantically demanding and distinct areas (eyes, mouth, skin and hair), while a tangent-space output projection recovers fine iris detail. We further introduce a scalable procedural augmentation pipeline that enriches raw geometry scans with physically plausible albedo, roughness and normal maps for training. The predicted attributes render directly as a single RGBA vertex-colour channel. VISAGE reduces FID by 42.7% on NPHM and 22.5% and 4.4% on zero-shot FaceVerse and i3DMM, respectively, relative to the strongest baseline, with a 7.2M-parameter core network.","authors":["Jeremias Krauß","Pragati Jaiswal","René Schuster","Didier Stricker"],"published":"2026-11-03T11:35:05Z","updated":"2026-11-03T11:35:05Z","abstract_url":"https://arxiv.org/abs/2611.04712v1","html_url":"https://arxiv.org/html/2611.04712v1","pdf_url":"https://arxiv.org/pdf/2611.04712v1.pdf","matched_keywords":["3d","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04711v1","title":"Cycle WAM: Coupling Action and Video through Cycle Consistency","abstract":"Recent advances in video modeling have driven substantial progress in world action models (WAMs). Existing approaches exploit pretrained video priors by decoding actions from latent representations or inferring them from generated videos. The underlying link is causal: robot actions produce changes in the scene, and video observations of these changes provide evidence for inferring the actions that produced them. However, existing training formulations do not by themselves ensure that actions and their predicted visual consequences are consistent, potentially limiting the use of pretrained capabilities. We treat video and action as paired modalities linked by this causal relationship and learn their correspondence through a unified training framework designed to better exploit pretrained video priors. Cycle WAM first augments video-action co-training with bidirectional conversion to reinforce cross-modal correspondence and recover forward and inverse dynamics. It then introduces a differentiable cycle-reconstruction objective to further couple the two mappings. The resulting model supports both forward and inverse dynamics, with the potential to improve performance through more effective use of pretrained video priors. Cycle WAM achieves state-of-the-art performance among comparable methods on LIBERO-Pro and substantially improves DreamZero on DROID. Comparisons with UWM characterize its inverse-dynamics performance and show sharper visual detail in the displayed forward-dynamics predictions.","authors":["Qinglin Yang","Jiepeng Wang","Yuxing Huang","Haibin Huang","Kai Xu","Chi Zhang","Ruizhen Hu","Xuelong Li"],"published":"2026-11-03T11:33:51Z","updated":"2026-11-03T11:33:51Z","abstract_url":"https://arxiv.org/abs/2611.04711v1","html_url":"https://arxiv.org/html/2611.04711v1","pdf_url":"https://arxiv.org/pdf/2611.04711v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04710v1","title":"DenseTwins: Dense Modality Decoupling for Multimodal Self-Supervision","abstract":"Multimodal perception is central to many computer vision applications, including robotics and autonomous driving, where different sensing modalities provide complementary cues. Self-supervised learning offers a scalable solution for exploiting large amounts of unlabeled multimodal data. However, existing methods either neglect modality-specific information by enforcing feature-space alignment between modalities or learn only global representations without preserving spatial structure. We propose DenseTwins, a multimodal self-supervised framework that learns dense representations by explicitly decoupling the dense feature space into shared and modality-specific components. The proposed approach combines dense cross-modal correspondences with redundancy-reduction objectives, enabling the model to capture both shared semantics and modality-specific cues within a structured dense embedding space. DenseTwins jointly optimizes an intra-modal objective across augmented views and a cross-modal objective that aligns shared features while decorrelating modality-specific information. We evaluate DenseTwins across multiple multimodal benchmarks and sensing setups, achieving state-of-the-art or competitive performance across multimodal self-supervised baselines. Code available at: https://github.com/CarloSgaravatti/DenseTwins.","authors":["Carlo Sgaravatti","Daniele Kopyshevskiy","Davide Secco","Giacomo Boracchi"],"published":"2026-11-03T11:31:33Z","updated":"2026-11-03T11:31:33Z","abstract_url":"https://arxiv.org/abs/2611.04710v1","html_url":"https://arxiv.org/html/2611.04710v1","pdf_url":"https://arxiv.org/pdf/2611.04710v1.pdf","matched_keywords":["representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04709v1","title":"Learning from Unlabeled Photographs for General Oral Image Analysis","abstract":"Oral photographs contain rich clinical information and hold significant potential for artificial intelligence applications; however, most models are trained for individual tasks and rely on costly expert annotations. We hypothesized that self-supervised training on unlabeled oral photographs could produce transferable visual representations for heterogeneous vision tasks. To test this hypothesis, we developed DOVE (Dental Optical Visual Encoder) by domain-adaptive self-supervised pretraining on approximately 530,000 unlabeled oral photographs collected from publicly accessible sources. DOVE was benchmarked against 3 established baselines across 5 classification datasets and 4 segmentation datasets, covering both frozen backbone evaluation and end-to-end finetuning. DOVE achieved the strongest overall performance, ranking best in few-shot transfer and label efficiency on most benchmarks. Under the 20-shot frozen-backbone protocol, DOVE outperformed the second best DINOv3 by 4.37 percentage points in mean macro-F1 across classification datasets and by 4.49 percentage points in mean macro-Dice across segmentation tasks. Under end-to-end finetuning, DOVE achieved at least 80% of the strongest full-data baseline's performance across most evaluation datasets using only 10% of the labeled training data. Qualitative retrieval and feature analyses further indicated better organization of image-level and spatial representations. These findings support DOVE as a generalizable and label-efficient backbone for oral vision research.","authors":["Zhong-Shi Zhang","Zi-Li Yu","Xiao Xiao","Huan Liu","Gui-Song Xia","Cui Huang","Meng-Xun Li"],"published":"2026-11-03T11:28:54Z","updated":"2026-11-03T11:28:54Z","abstract_url":"https://arxiv.org/abs/2611.04709v1","html_url":"https://arxiv.org/html/2611.04709v1","pdf_url":"https://arxiv.org/pdf/2611.04709v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04666v1","title":"Phase-DGS: Phase-guided Dynamic Gaussian Splatting from Unsynchronized Multi-view Video","abstract":"Spatiotemporal scene reconstruction with Dynamic Gaussian Splatting (DGS) fundamentally depends on perfect temporal synchronization across all cameras, an assumption rarely achievable in practice. Industry-standard synchronization requires expensive specialized hardware and complex setup, while data-driven alternatives including audio-based alignment, geometry matching, and pose tracking remain limited by restrictive environmental or scene-specific assumptions. To overcome these limitations, we propose Phase-DGS, a framework that replaces conventional timestamps with a semantic phase representing each frame's inherent state within the underlying motion cycle. Frames capturing the same motion state share the same phase regardless of which camera records them or when, naturally establishing spatiotemporal correspondence across unsynchronized cameras. We validate Phase-DGS under temporal offsets, frame drops, and camera freezes, achieving up to +8.5 dB PSNR improvement over baselines while enabling seamless integration with existing DGS backbones including RealTime-4DGS and FreeTimeGS.","authors":["Hosung Jeon","Jun Young Jeong","Sangwoon Kwak","Joonsoo Kim","Sangmin Kim","Jaesik Park","Won-Sik Cheong","Hyon-Gon Choo"],"published":"2026-11-03T10:51:33Z","updated":"2026-11-03T10:51:33Z","abstract_url":"https://arxiv.org/abs/2611.04666v1","html_url":"https://arxiv.org/html/2611.04666v1","pdf_url":"https://arxiv.org/pdf/2611.04666v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04654v1","title":"BhopalMLS: A LiDAR Dataset for Semantic Scene Understanding in Heterogeneous Urban Environments","abstract":"We introduce BhopalMLS, a large-scale Mobile Laser Scanning (MLS) dataset from a dense, heterogeneous urban environment in Bhopal, India, with mixed traffic, informal structures, and narrow unplanned streets. It spans approximately 10 km of road corridors with over 1.2 billion points and 19,518 annotated instances across 62 fine-grained static categories, grouped into 12-class and 21-class benchmark taxonomies; 6 optional moving-class subclasses support dynamic-object analysis. Existing 3D datasets, collected in well-planned cities, are structurally more uniform than such unplanned settings, and lack their subtype diversity. On semantic and instance segmentation at both granularities, fine-tuned foundation models surpass supervised baselines: Utonia(L) reaches 71.28% mIoU (vs. PTv3's 68.04% from scratch) and 44.07% mAP50 on the 12-class benchmark. Cross-region experiments against four established datasets (Ke-MLS, Toronto-3D, Paris-Lille-3D, SemanticKITTI) reveal a consistent asymmetric transferability: models trained on BhopalMLS transfer better than the reverse on every pair, for both Utonia(L) and Concerto(L) (mean 21.5, up to 36 mIoU points), holding even when the target is denser. Factor-controlled retraining at a fixed label budget, repeated on both models, attributes this to the coverage of BhopalMLS's subtype inventory rather than to dataset size or corridor geometry: collapsing each class to a single subtype costs 13.0 and 13.3 mIoU points for Utonia(L) and Concerto(L). BhopalMLS therefore offers a testbed for 3D perception beyond well-planned cities. Data and an interactive viewer are at https://geoai4cities.github.io/bhopalmls.","authors":["Pyare Lal Chauhan","Vaibhav Kumar","Bharat Lohani"],"published":"2026-11-03T10:41:37Z","updated":"2026-11-03T10:41:37Z","abstract_url":"https://arxiv.org/abs/2611.04654v1","html_url":"https://arxiv.org/html/2611.04654v1","pdf_url":"https://arxiv.org/pdf/2611.04654v1.pdf","matched_keywords":["3d","instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04645v1","title":"Therapy-FIS: A Dataset for Assessing Facilitative Interpersonal Skills in Psychotherapeutic Setting","abstract":"Facilitative Interpersonal Skills (FIS) is a performance-based assessment method that provides a structured framework for evaluating the interpersonal competencies of mental health professionals. However, existing FIS assessment relies heavily on human observer ratings, making the evaluation process labor-intensive, costly, and difficult to scale. Progress toward automated FIS assessment has also been constrained by the lack of publicly available professional data in psychotherapy settings. To address this limitation, we introduce Therapy-FIS, a dataset for automated FIS assessment in standardized psychotherapy tasks. To our knowledge, Therapy-FIS is the first publicly available dataset in this domain. It contains facial, acoustic, and textual signals derived from standardized therapist responses to standardized mock patient stimulus clips, based on 890 therapist video recordings and 8 patient videos, and is rated with eight FIS subscale ratings and an overall FIS score. Built on Therapy-FIS, we further establish a benchmark with two downstream tasks: Therapist Performance Rating and Joint Therapist--mock-Patient Performance Rating. We also introduce a competitive baseline, DyadicFIS, with gated fusion and routed readout under therapist-only and dyadic settings. DyadicFIS obtains the best macro CCC(Concordance Correlation Coefficient) scores on both tasks (0.2807 and 0.3299). Therapy-FIS offers a reproducible resource for data-driven automated assessment of therapeutic interpersonal skills in mental health.","authors":["Qijian Zheng","Wanqing Lin","Yuanfang Wang","Yijun Ge","Jordan Bate","Katie Aafjes-van Doorn","Feng Liu"],"published":"2026-11-03T10:35:21Z","updated":"2026-11-03T10:35:21Z","abstract_url":"https://arxiv.org/abs/2611.04645v1","html_url":"https://arxiv.org/html/2611.04645v1","pdf_url":"https://arxiv.org/pdf/2611.04645v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04633v1","title":"ReXMo: End-to-End Video Character Replacement with Expression and Motion Preservation","abstract":"Video character replacement aims to replace actors while preserving facial expressions, motions, and scene dynamics. Existing methods typically rely on masked generation with pose guidance, limiting fine-grained expression and motion preservation in complex scenes. We propose ReXMo, an end-to-end framework that supports single-, multi-, and selective character replacement scenarios. ReXMo introduces paired triplet supervision, where synthesized driving videos and original videos share identical performances but different identities, enabling scalable training through synthetic data generation. An In-Context Diffusion Transformer learns identity transformation by jointly conditioning on driving videos, reference identities, and text prompts, while an Expression Enhancement Adapter improves facial expression preservation in multi-person scenes. Extensive experiments demonstrate that ReXMo outperforms existing methods in identity fidelity, motion consistency, expression preservation, and visual quality. Our dataset and code will be publicly released.","authors":["Hualiang Wei","Wenhui Li"],"published":"2026-11-03T10:22:09Z","updated":"2026-11-03T10:22:09Z","abstract_url":"https://arxiv.org/abs/2611.04633v1","html_url":"https://arxiv.org/html/2611.04633v1","pdf_url":"https://arxiv.org/pdf/2611.04633v1.pdf","matched_keywords":["video","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04626v1","title":"MambaHand: Local Identity and Behavioral Sequence Learning with Mamba for Dynamic Hand Gesture Authentication","abstract":"Dynamic hand gesture authentication (DHGA) is an emerging biometric technique that contains both physiological and behavioral identity characteristics. However, existing methods primarily rely on convolutional networks or manually designed motion representations, making it difficult to jointly capture fine-grained local identity differences and long-range behavioral dependencies during hand gesture execution. To address these challenges, we propose a two-stream identity representation learning framework, MambaHand Net, to combine CNNs with Mamba for DHGA. The proposed framework consists of a Local Identity Stream (LIS) and a Behavioral Sequential Stream (BSS). The LIS extracts frame-wise local identity cues with a convolutional network, while the BSS preserves spatial tokens from intermediate visual features and constructs first-order and second-order temporal difference sequences to model multi-order behavioral variations. Moreover, the bidirectional Mamba is incorporated into the BSS to model semantic motion across different spatial locations, enabling efficient long-range modeling of hand gesture execution habits. Finally, attention-guided spatial token aggregation and a two-stream fusion strategy are used to integrate local identity cues and multi-order behavioral patterns into a discriminative identity representation. Our method achieves state-of-the-art (SOTA) average performance on the SCUT-DHGA benchmark dataset, demonstrating that combining CNNs with Mamba is an effective new solution for DHGA.","authors":["Zenan Lin","Junduan Huang","Xilai Wang","Wenxiong Kang"],"published":"2026-11-03T10:16:43Z","updated":"2026-11-03T10:16:43Z","abstract_url":"https://arxiv.org/abs/2611.04626v1","html_url":"https://arxiv.org/html/2611.04626v1","pdf_url":"https://arxiv.org/pdf/2611.04626v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04616v1","title":"Gradient-Guided Orientation Learning for Weakly Supervised Oriented Object Detection","abstract":"Weakly supervised oriented object detection (WS-OOD) aims to reduce the annotation cost of rotated bounding boxes by leveraging cheaper annotations such as horizontal boxes or points. However, these weak annotations provide no explicit orientation information, forcing existing methods to infer object angles through indirect geometric consistency or equivariant constraints. Such indirect supervision often becomes ambiguous and unstable under real-world appearance variations, including illumination changes, color shifts, shadows, and background clutter. In this paper, we present a simple yet effective gradient-guided orientation learning strategy for WS-OOD. Motivated by the observation that the input image itself contains useful orientation priors, our method extracts dominant gradient-based orientation cues from object regions and converts them into pseudo-angle labels for auxiliary supervision, enabling the detector to learn orientation-aware representations without requiring rotated bounding box annotations or extra learnable parameters. Furthermore, since AP can mask substantial angular errors when spatial IoU remains high, we introduce an orientation-aware evaluation metric that incorporates angular discrepancies into the standard AP protocol. Extensive experiments on weakly supervised oriented detection benchmarks demonstrate that the proposed pseudo-angle supervision improves both detection performance and orientation estimation quality, while the proposed metric provides a more faithful assessment of angle prediction than conventional AP alone.","authors":["Junyong Jang","Juheon Park","Minyoung Jeon","Jaehyup Lee"],"published":"2026-11-03T10:07:49Z","updated":"2026-11-03T10:07:49Z","abstract_url":"https://arxiv.org/abs/2611.04616v1","html_url":"https://arxiv.org/html/2611.04616v1","pdf_url":"https://arxiv.org/pdf/2611.04616v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04604v1","title":"Sparse-View 3D Coronary Reconstruction from Vessel Segmentations Using a Diffusion Prior","abstract":"Reconstructing three-dimensional (3D) coronary anatomy from sparse angiographic views could support percutaneous coronary intervention, but limited angular coverage and imperfect vessel segmentations introduce substantial geometric ambiguity. We propose a vessel-specific reconstruction framework combining a learned 3D diffusion prior, visual-hull initialization, and projection-based data consistency. The unconditional diffusion model is trained on coronary vessel masks without paired 2D--3D data and reused across different view counts without retraining. During inference, a scaled visual hull initializes reconstruction, while projection-based updates constrain diffusion refinement using patient-specific vessel observations. We evaluated the framework on simulated angiograms derived from ImageCAS computed tomography angiography volumes using two, four, and eight views at two contrast levels. Across 50 evaluation coronary-tree cases, the proposed method achieved higher mean Dice and clDice than visual hull, deep image prior (DIP), and hash-grid implicit neural representation (INR) at all view counts under reduced contrast. With eight views, improvements over DIP, the best-performing baseline at lower contrast, were approximately 0.13 in Dice and 0.22 in clDice. At higher contrast, performance remained competitive with hash-grid INR, the best-performing eight-view baseline. The preferred diffusion starting timestep depended on observation quality and view count, with excessive refinement reducing accuracy at higher contrast. Projection guidance improved both metrics across all conditions. Averaging stochastic reconstructions further improved accuracy, while sample disagreement localized errors with average-precision gains of 0.14--0.21 over error prevalence. These findings support diffusion-prior reconstruction from sparse vessel observations, although clinical validation remains necessary.","authors":["Tianyuan Wang","Kenan Niu","Stefano Stramigioli"],"published":"2026-11-03T09:58:45Z","updated":"2026-11-03T09:58:45Z","abstract_url":"https://arxiv.org/abs/2611.04604v1","html_url":"https://arxiv.org/html/2611.04604v1","pdf_url":"https://arxiv.org/pdf/2611.04604v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04583v1","title":"Multi-Path Mamba Diffusion for 3D Point Cloud Semantic Scene Completion","abstract":"3D semantic scene completion plays a critical role in enabling various downstream tasks within autonomous systems by estimating both missing geometric structures and semantic information in scene data. In this work, we introduce a unique neural framework that integrates state space modeling with diffusion-based generative approaches to enhance 3D point cloud semantic scene completion. We propose \\textit{MPath Mamba} diffusion network, leveraging a skip-triple Mamba structure, dimensional decomposition residuals, and multi-directional dilations within multi-path data to efficiently process long-sequence data for feature extraction. The proposed method operates in the conditioned latent space of a variational autoencoder, enhanced by a state-space mechanism to improve 3D point cloud representation and reconstruction. Extensive experiments conducted on the SemanticKITTI benchmark demonstrate that our approach achieves highly competitive performance for 3D point cloud semantic scene completion.","authors":["Li Liang","Naveed Akhtar","Jordan Vice","Anwaar Ulhaq","Ajmal Saeed Mian"],"published":"2026-11-03T09:41:50Z","updated":"2026-11-03T09:41:50Z","abstract_url":"https://arxiv.org/abs/2611.04583v1","html_url":"https://arxiv.org/html/2611.04583v1","pdf_url":"https://arxiv.org/pdf/2611.04583v1.pdf","matched_keywords":["3d","representation","diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04554v1","title":"SEEK-VAU: Towards Evidence-Faithful Video Anomaly Understanding via Agentic Search","abstract":"Most video anomaly understanding (VAU) systems still infer anomaly judgments from evidence collected in a feed-forward way under predefined rules, typically sampled frames, or events clustered from such frames. This protocol fails when the collected evidence is incomplete under imperfect predefined rules, because once reasoning begins the model can no longer search for the missing evidence. We address this limitation with SEEK-VAU, which reframes VAU as an agentic search-and-verify interaction protocol under a bounded search budget: instead of passively reasoning over pre-collected evidence, the policy actively gathers evidence across the three stages of an anomaly event chain (precursor, trigger, and aftermath) and verifies its sufficiency before finalization, turning event-chain completeness into an explicit design rather than an outcome of predefined rules. A bounded budget caps the cost of this search, but does not by itself teach the policy where to look or when to stop. To make this behavior learnable, we introduce evidence-faithful counterfactual verification (EFCV), which rewards selected evidence that remains supportive, compact, and necessary under counterfactual verification. We further introduce SEEK-Bench, featuring video-level episodes with temporal interval annotations, semantic QA and event-chain stage labels. Together, SEEK-VAU and SEEK-Bench establish a strong foundation for evidence-faithful and actively verifiable VAU.","authors":["Minghe Wang","Weijun Zeng","Dapeng Luo","Xinyue Wang","Nong Sang"],"published":"2026-11-03T09:19:58Z","updated":"2026-11-03T09:19:58Z","abstract_url":"https://arxiv.org/abs/2611.04554v1","html_url":"https://arxiv.org/html/2611.04554v1","pdf_url":"https://arxiv.org/pdf/2611.04554v1.pdf","matched_keywords":["video","agent"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04548v1","title":"Predicting Void Points in Self-Occluding Forest Volumes","abstract":"Synthetic Aperture Imaging (SAI) enables drones to observe forest canopies by warping and averaging multiple displaced views at a common depth. However, occlusion is suppressed rather than eliminated, causing poorly observed regions to appear occupied and leading to systematic biomass overestimation. The Deep Forest project cannot distinguish reconstruction artifacts from real vegetation because its training data relies on measured reflectance points, excluding empty space and preventing the network from learning explicit occupancy boundaries. This thesis addresses the problem by modifying training labels rather than the imaging process. Each simulated scene is rendered twice: as a 9x9 grid of top-down captures for focal-stack generation and as 550 depth-clipped slabs derived from scene geometry to provide occupancy labels, explicitly representing void space as a negative class. A Gazebo pipeline generates procedural forest stands containing 80-200 trees across three species. A pretrained Pix2Pix model translates rendered RGB images into a synthetic near-infrared band, and Light Field Rendering produces aligned focal stacks of 550 planes across three channels. Four architectures were evaluated on a held-out scene. The plain 2D U-Net achieved an IoU of 0.6290, outperforming the volumetric 3D U-Net (0.5707). Established reconstruction methods performed substantially worse: COLMAP achieved 0.3446 and DepthAnything3 0.2959, both after their respective optimal dilation sweeps. An RGB-input variant of the volumetric architecture achieved the highest IoU of 0.6514 without dilation or per-scene calibration. These results highlight the limitations of conventional reconstruction methods, which recover visible surfaces but struggle to infer occupancy within closed canopies.","authors":["Benjamin Bachmayr","Mohamed Youssef","Oliver Bimber"],"published":"2026-11-03T09:12:46Z","updated":"2026-11-03T09:12:46Z","abstract_url":"https://arxiv.org/abs/2611.04548v1","html_url":"https://arxiv.org/html/2611.04548v1","pdf_url":"https://arxiv.org/pdf/2611.04548v1.pdf","matched_keywords":["3d"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04529v1","title":"Learning to Falsify: Hierarchical Multiple Instance Learning for High Resolution AI-Generated Image Detection","abstract":"Recent advances in generative models have made synthetic images increasingly photorealistic, posing growing challenges to reliable and generalizable detection of AI-generated images. Existing methods typically rely on holistic image-level classification, which may overlook local artifacts, especially in high-resolution images. To address this limitation, we formulate this task as a falsification-driven multiple instance learning problem, where a single fake patch can falsify the whole image, while a real image requires all patches to be authentic. Based on this formulation, we propose \\textit{Learning to Falsify (LTF)}, a hierarchical multiple instance learning framework that models an image as multiple bags of instances across different spatial levels and aggregates their predictions under the falsification-inspired principle. We further introduce Cross-Shuffle during training to encourage the model to learn local artifact evidence rather than image-level shortcuts. Furthermore, we propose the \\textit{Falsification-driven Test-time Aggregation Strategy (FATAS)}, a plug-and-play module that extends the same falsification-inspired principle to existing detectors by aggregating patch-level predictions. Extensive experiments demonstrate that LTF achieves strong generalization and robustness across multiple benchmarks, while FATAS substantially improves representative detectors in high-resolution scenarios without retraining. Code is available at https://github.com/HuiGuanLab/LTF.git","authors":["Haoran Chen","Daiqi Gao","Xinyuan Li","Yongwei Wang","Lei Zhu","Rui Cai","Jianfeng Dong"],"published":"2026-11-03T08:58:26Z","updated":"2026-11-03T08:58:26Z","abstract_url":"https://arxiv.org/abs/2611.04529v1","html_url":"https://arxiv.org/html/2611.04529v1","pdf_url":"https://arxiv.org/pdf/2611.04529v1.pdf","matched_keywords":["instance"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04524v1","title":"E2I-Flow: EEG-to-Image Reconstruction via Wavelet-Temporal Cross-Attention and Conditional Flow Matching","abstract":"Electroencephalography (EEG)-based visual decoding and reconstruction aims to recover visual information from non-invasive brain signals. But there are challenges due to the complex temporal-frequency characteristics of EEG signals and the difficulty of discrete denoising framework in mapping neural activity to meaningful visual representations. Here, we propose E2I-Flow, an EEG-to-image decoding and reconstruction framework that combines a novel EEG encoder for time-frequency representation learning from EEG features, and conditional flow matching for visual decoding. A stationary-wavelet frequency branch and a temporal-mixing branch are integrated through bidirectional cross-attention and adaptive fusion, with the resulting EEG representations aligned to ground-truth image embeddings using contrastive and mean-squared-error loss supervisions. The aligned EEG representation is then used as a condition for a Transformer-based flow-matching model to predict the corresponding visual embedding for image synthesis. Experimental results show strong zero-shot EEG-to-image retrieval and improved visual reconstruction performance, outperforming several state-of-the-art baselines.","authors":["Haowei Pan","Hwa Hui Tew","Junn Yong Loo","Fuad Noman","Hernando Ombao","Chee-Ming Ting"],"published":"2026-11-03T08:52:29Z","updated":"2026-11-03T08:52:29Z","abstract_url":"https://arxiv.org/abs/2611.04524v1","html_url":"https://arxiv.org/html/2611.04524v1","pdf_url":"https://arxiv.org/pdf/2611.04524v1.pdf","matched_keywords":["retrieval","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04498v1","title":"3DGS-VBench+ and 3DGSV-Assessor: A Multi-Dimensional Subjective Benchmark and a Reference-Flexible Objective Model for 3D Gaussian Splatting Video Quality Assessment","abstract":"3D Gaussian Splatting (3DGS) enables real-time novel view synthesis (NVS), but its heavy storage makes compression essential, and both training and compression introduce representation-specific distortions. Since generative compression in many methods treats geometric and color attributes via different parameters, it can induce dimension-specific distortions, motivating multi-dimensional assessment. Moreover, real-world captures generally lack an aligned ground-truth video for a synthesized, continuous camera trajectory, leaving only sparse captured views as references. To enable multi-dimensional quality assessment of 3DGS videos with scarce aligned references, we first present 3DGS-VBench+, a large-scale subjective video quality assessment (VQA) benchmark comprising 3{,}036 3DGS reconstructions, each paired with a rendered video, across 11 real-world and 22 synthetic scenes, generated by 6 representative compression algorithms at systematically designed levels and annotated with 9{,}108 MOSs covering overall, geometry, and color quality. Based on 3DGS-VBench+, we propose 3DGSV-Assessor, a reference-flexible, large multimodal framework that scores all three dimensions in one generation pass and fuses a ranking-based reference cue into the frozen regressor through a bounded gate, supporting both reduced-reference (RR) and no-reference (NR) assessment. Extensive experiments demonstrate state-of-the-art correlation with human perception on 3DGS-VBench+ and strong zero-shot generalization to other NVS benchmarks. The dataset and code will be released at https://github.com/YukeXing/3DGSV-Assessor.","authors":["Yuke Xing","William Gordon","Jiarui Wang","Yujie Zhang","Guangtao Zhai","Yiling Xu"],"published":"2026-11-03T08:26:13Z","updated":"2026-11-03T08:26:13Z","abstract_url":"https://arxiv.org/abs/2611.04498v1","html_url":"https://arxiv.org/html/2611.04498v1","pdf_url":"https://arxiv.org/pdf/2611.04498v1.pdf","matched_keywords":["video","3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04492v1","title":"Hybrid Particle-Voxel Dynamics for Multimodal 3D World Simulation","abstract":"Predicting how the world evolves in response to robot actions is central to policy learning, evaluation, and planning. However, many action-conditioned world models predict future observations in 2D image or video space without explicitly modeling the underlying 3D scene, making spatial consistency across viewpoints and over long-horizon interactions challenging. We introduce 3D World Simulator, an action-conditioned multimodal world modeling framework that jointly predicts appearance, geometry, and tactile observations from a unified 3D representation. Our approach combines a hybrid particle-voxel autoencoder that compresses point clouds into compact 3D voxel latents with an action-conditioned latent dynamics model that predicts their evolution. The shared 3D representation supports geometrically consistent rendering from arbitrary viewpoints and flexible integration of spatially aligned tactile signals. Our experiments demonstrate interactive, long-horizon, multimodal prediction at 50 Hz. We then show how our model enables scalable data generation for policy training and evaluation using tactile and multi-view visual observations, including wrist-mounted and novel camera views. Furthermore, we scale our method to large datasets containing diverse objects and demonstrate model-based planning with unseen objects and robot configurations. Together, these results highlight the potential of hybrid particle-voxel dynamics as a foundation for multimodal 3D world simulation.","authors":["Jimmy Wang","Yifan Chou","Kaifeng Zhang","Yixuan Wang","Binghao Huang","Tao Yu","Saleh Nabi","Yunzhu Li"],"published":"2026-11-03T08:20:53Z","updated":"2026-11-03T08:20:53Z","abstract_url":"https://arxiv.org/abs/2611.04492v1","html_url":"https://arxiv.org/html/2611.04492v1","pdf_url":"https://arxiv.org/pdf/2611.04492v1.pdf","matched_keywords":["video","3d","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04490v1","title":"Polarimetric Scattering-Structure Contrastive Learning for Few-Shot HRRP Recognition","abstract":"Few-shot high-resolution range profile (HRRP) recognition is challenged by strong aspect-dependent variation and sparse novel-class support. We propose polarimetric scattering-structure contrastive learning (PSS-CL), which supplies an episodic HRRP encoder with a structured physical training view. Dominant local responses are represented by their soft affinities to canonical polarimetric mechanisms, normalized range locations, and energy contributions. A symmetric cross-view objective transfers this scattering structure to the learned HRRP representation, while episodic prototype learning supports novel-class inference without the physical branch. We conduct Random-aspect and Cross-aspect experiments on a six-class measured dataset. In Cross-aspect 1-, 3-, and 5-shot recognition, PSS-CL achieves 81.73%, 86.92%, and 90.98% mean class accuracy (MCA), respectively, outperforming the best competing results by 5.62%, 3.09%, and 3.56%.","authors":["Fangyi Wang","Peng Zhao","Haipeng Wang"],"published":"2026-11-03T08:19:44Z","updated":"2026-11-03T08:19:44Z","abstract_url":"https://arxiv.org/abs/2611.04490v1","html_url":"https://arxiv.org/html/2611.04490v1","pdf_url":"https://arxiv.org/pdf/2611.04490v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04489v1","title":"Bridging CLIP with DINO: Cross-Modal Information Maximization for Online Test-Time Adaptation","abstract":"Vision-language models such as CLIP enable zero-shot classification from arbitrary class names, but under test-time corruptions, their visual encoder projects distorted features onto incorrect textual anchors with high confidence: a phenomenon we term modality bias. Standard entropy minimization reinforces these overconfident errors, which creates a confirmation-bias loop and collapses the predicted label distribution. We propose an online test-time adaptation (TTA) method that breaks this loop at three levels. At the representation level, a frozen self-supervised backbone (e.g., DINO v2) is combined with CLIP through a cross-covariance logit ensemble. CLIP text prototypes are projected into the feature space of this text-free backbone, so the self-supervised branch classifies native image features and is less affected by the text bias of CLIP. At the optimization level, a gated test-time information-maximization objective pairs per-sample sharpening with batch-level diversity, while an adaptive gate excludes unreliable samples from the gradient. At the prediction level, an online logit adjustment corrects the residual class-distribution skew. CDIM outperforms the compared CLIP-based online TTA baselines on ImageNet-C, CIFAR10-C, and CIFAR100-C, and remains competitive in continual and mixed-domain TTA. Extensive analyses and ablation studies verify the contribution of each of its components. Our code is available at https://github.com/B1ueC1oud/CDIM","authors":["Taehoon Kim","Wonjun Hwang","Hyunsouk Cho"],"published":"2026-11-03T08:19:29Z","updated":"2026-11-03T08:19:29Z","abstract_url":"https://arxiv.org/abs/2611.04489v1","html_url":"https://arxiv.org/html/2611.04489v1","pdf_url":"https://arxiv.org/pdf/2611.04489v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04476v1","title":"KeyWise: Efficient Video-Only Piano Transcription with a Lightweight Per-Key Architecture","abstract":"Audio-based piano transcription is hampered by the sustain pedal and by noisy or missing soundtracks, problems that video-only transcription avoids, since a top-view video shows directly when each key is pressed and released. Most visual transcription networks, however, describe the whole keyboard with one global feature vector and must learn where each key is. In this paper, we propose KeyWise, a lightweight per-key architecture that exploits the known geometry of the keyboard instead of learning it. The rectified keyboard is divided into 88 equal tiles that serve as regions of interest (ROIs), and one small recurrent network, shared by all keys, follows each key over time. On PianoVAM, KeyWise reaches the onset accuracy of the state-of-the-art V2N (95.0% vs. 94.7% onset F1 at 50 ms and 97.8% vs. 97.0% at 100 ms) with 1.3 M instead of 28.2 M parameters, and it runs 4.7 times faster on the same GPU. At 100 ms, it is also significantly more accurate when the key releases (97.0% vs. 95.5% F1) or the velocities (89.4% vs. 84.5% F1) must be correct as well. On PianoYT, KeyWise pre-trained on PianoVAM reaches 69.4% onset F1 at 100 ms, comparable to the best published result, although it needs fine-tuning for new recording conditions.","authors":["Anastasios Chatzigiannis","Natalia Panagou","Maria Koziri"],"published":"2026-11-03T08:08:59Z","updated":"2026-11-03T08:08:59Z","abstract_url":"https://arxiv.org/abs/2611.04476v1","html_url":"https://arxiv.org/html/2611.04476v1","pdf_url":"https://arxiv.org/pdf/2611.04476v1.pdf","matched_keywords":["video"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04472v1","title":"Beyond Token Representations: Explicit Visual Object Grounding for Video Reasoning Segmentation","abstract":"Video Reasoning Segmentation (VRS) aims to infer and segment target objects specified by reasoning queries in videos. Existing methods typically first infer the target and generate a few segmentation tokens for it, which are then fed into a mask decoder for mask prediction. However, such segmentation tokens tend to be both semantically monotonous and spatially ambiguous, making them largely insufficient to represent the target to guide mask prediction. In this paper, we propose an explicit visual object grounding framework for VRS. Specifically, we first propose a spatial-aware prompt generation and refinement scheme, in which we query a multimodal large language model to generate explicit spatial prompts (i.e., bounding box and point set) for the target and then refine them through multi-step dialogue. Furthermore, we introduce a query diversification and alignment module to generate auxiliary queries that describe the same target from different perspectives. We then enforce cross-query consistency between their predicted spatial prompts to alleviate the training bias caused by query limitations. Finally, we select several reliable frames using a prompt-based keyframe selection strategy to support mask decoding and propagation. Extensive experiments on eight datasets demonstrate that our method significantly outperforms state-of-the-art methods. The code is available at https://github.com/viscom-tongji/EVOG.","authors":["Jun Huang","Junyang Zhang","Zijie Yue","Bingkun Wang","Yong Luo","Miaojing Shi"],"published":"2026-11-03T07:59:55Z","updated":"2026-11-03T07:59:55Z","abstract_url":"https://arxiv.org/abs/2611.04472v1","html_url":"https://arxiv.org/html/2611.04472v1","pdf_url":"https://arxiv.org/pdf/2611.04472v1.pdf","matched_keywords":["video","representation","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04467v1","title":"Is Forgetting Unified? Exploring Concept Unlearning in Unified Multimodal Models","abstract":"Unified multimodal models (UMMs) integrate image generation and visual understanding, but are existing single-pathway unlearning methods sufficient to suppress target concepts across both? In this work, we study cross-pathway concept unlearning. Our goal is to prevent a model from both generating images of a target concept and identifying it in input images, while preserving other capabilities. To this end, we introduce UUBench, a diagnostic benchmark covering 30 target concepts and 60 semantically related neighboring concepts. Experiments on representative UMMs show that the evaluated single-pathway methods achieve limited joint forgetting: generation-side editors strongly suppress target generation but yield limited forgetting in visual understanding, while understanding-side baselines struggle to achieve substantial forgetting even in their own pathway. Their direct composition also yields limited joint forgetting. We therefore propose UniForget, achieving joint forgetting rates of 80.0% on BAGEL-7B-MoT and 92.7% on Janus-Pro-7B, outperforming representative baselines. Further analysis reveals trade-offs between joint forgetting and capability preservation.","authors":["Zhongkai Xue","Junkai Chen","Mingcong Lei","Rumo Zhang","Yixiao Liu","Zhimin Sun","Shu Wu","Qiang Liu","Lihua Zhang","Liang Wang"],"published":"2026-11-03T07:56:19Z","updated":"2026-11-03T07:56:19Z","abstract_url":"https://arxiv.org/abs/2611.04467v1","html_url":"https://arxiv.org/html/2611.04467v1","pdf_url":"https://arxiv.org/pdf/2611.04467v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04452v1","title":"DynOSeg: Dynamic Object Segmentation via Motion-Geometry Fusion","abstract":"Moving Object Segmentation (MOS) detects and separates dynamic objects from the static background in a video, which plays a fundamental role in dynamic-scene understanding. Most MOS methods rely on pure visual motion cues alone, such as optical flow or point tracks, which is inherently ambiguous due to the compounded camera and object motions as well as motion-induced appearance changes, e.g. shadows and reflections. Naive fusion of additional information such as depth and semantics, however, cannot leverage their complementarity to the fullest extent. We therefore propose DynOSeg, a novel MOS approach that takes on a two-stage fusion structure. DynOSeg first combines a geometry-aware residual map and depth encoding into a geometric representation of motion, delineating camera motions and object dynamics. We then further incorporate semantic features to refine object understanding. We have additionally curated a diverse training corpus including CARLA-MOS, a new synthetic urban-driving dataset for MOS training. Our experiments show that DynOSeg consistently outperforms published state-of-the-art MOS methods across a diverse range of datasets. Our code and pretrained models can be found at https://github.com/ACFR-RPG/DynOSeg","authors":["Xu Han","Yiduo Wang","Yiran Wang","Viorela Ila"],"published":"2026-11-03T07:42:35Z","updated":"2026-11-03T07:42:35Z","abstract_url":"https://arxiv.org/abs/2611.04452v1","html_url":"https://arxiv.org/html/2611.04452v1","pdf_url":"https://arxiv.org/pdf/2611.04452v1.pdf","matched_keywords":["video","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04438v1","title":"Entropy-Gated Dynamic Rectification for Object Hallucination in Large Vision-Language Models","abstract":"Large Vision-Language Models (LVLMs) routinely name objects that are absent from the image. Latent steering can reduce this failure in one model forward pass, but a fixed gate treats early and late decoding steps by the same criterion. We observe that predictive entropy varies sharply within free-running generation, while states that commit to short answers occupy a narrow, confident band. We exploit this temporal mismatch by using uncertainty as a causally available, token-local control signal for an existing steering gate. We propose Entropy-Gated Dynamic Rectification (EGDR), which lowers the intervention threshold when entropy derived from the preceding step's already available logits is high and retains the calibrated operating point when it is low. On LLaVA-1.5-7B, the underlying static gate lowers CHAIR CS/CI from 53.00/15.30 to 32.00/14.30; replacing only its constant threshold with EGDR further lowers them to 29.00/13.60. At a matched 58% intervention rate, the corresponding static control obtains 30.50/14.00. The gain over the static gate holds on LLaVA-NeXT-7B and grows with the generation budget, while POPE scores and general multimodal capability remain effectively unchanged. EGDR requires no additional model forward pass and adds roughly 2% measured latency. Our code is available at https://github.com/alvi-uiu/EGDR.","authors":["Riasad Alvi","Md. Asaduzzaman Shuvo","Md. Ahashan Habib","Md. Faiyaz Abdullah Sayeedi"],"published":"2026-11-03T07:31:21Z","updated":"2026-11-03T07:31:21Z","abstract_url":"https://arxiv.org/abs/2611.04438v1","html_url":"https://arxiv.org/html/2611.04438v1","pdf_url":"https://arxiv.org/pdf/2611.04438v1.pdf","matched_keywords":["multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04423v1","title":"SWAP-INR: Implicit Neural Representation with Switchable Attention Paths for Time-varying Multivariate Scientific Data Compression","abstract":"Visualizing multivariate scientific simulation data is essential for understanding complex physical phenomena, yet the massive scale of such data imposes a severe storage bottleneck in high-performance computing environments. Implicit neural representations (INRs) have emerged as a promising continuous alternative to traditional lossy compressors, but existing methods struggle to explicitly capture cross-variable interactions and to adapt to the diverse spectral characteristics of physical variables. To address these limitations, we propose SWAP-INR, an architecture for high-fidelity compression of multivariate, time-varying simulation data. SWAP-INR introduces two key components: (1) The switchable attention path (SWAP) module explicitly models cross-variable interactions through a cross-variable attention layer, then routes each variable to an attention or non-attention path by a deterministic, loss-driven criterion, and prunes the inactive layers for structural compression. (2) The adaptability amplification SIREN (A2-SIREN) replaces rigid frequency scaling with channel-wise learnable modulation, adapting to heterogeneous physical features with negligible overhead. Combined with post-training 16-bit quantization, SWAP-INR achieves state-of-the-art performance on small modular reactor (SMR) datasets and remains competitive on public physics simulation datasets, while maintaining a constrained memory footprint. Our code is https://github.com/hvcl/SWAP-INR.","authors":["Hyunsoo Son","Jeonghyun Noh","Chaoli Wang","Won-Ki Jeong"],"published":"2026-11-03T07:10:43Z","updated":"2026-11-03T07:10:43Z","abstract_url":"https://arxiv.org/abs/2611.04423v1","html_url":"https://arxiv.org/html/2611.04423v1","pdf_url":"https://arxiv.org/pdf/2611.04423v1.pdf","matched_keywords":["representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04422v1","title":"GVT3D: Gesture-Vision-Text Token Enrichment for 3D Embodied Reference Understanding","abstract":"Natural human-robot interaction requires robots to interpret language and gestures within a 3D environment to support tasks such as pick-and-place and object retrieval. 3D Embodied Reference Understanding (3D-ERU) supports this by identifying the 3D location of a target object from a scene (point-cloud) containing a human pointing gesture and an accompanying language description. However, current 3D-ERU models lack alignment of cross-modal representations and incur high processing costs that increase with the point-cloud's size. To address this, we propose GVT3D, which employs an Embodied Fusion module that jointly models language, gesture, and vision inputs within a shared embedding space, promoting cross-modal alignment. We additionally introduce a foveation approach that selectively processes the point cloud within a coarse region around the estimated pointing direction to reduce computations. GVT3D achieves ~8% higher accuracy and foveation enables 2.95x faster execution while maintaining comparable accuracy, relative to prior 3D-ERU models.","authors":["Vimarsh Shah","Dulanga Weerakoon","Ajinkya Deshpande","Saksham Agarwal","Nilesh Bhatia","Neel Kiran Naik","Parth Shah","Sravan Danda","Sanjay E. Sarma","Archan Misra","Vigneshwaran Subbaraju","Sougata Sen"],"published":"2026-11-03T07:09:31Z","updated":"2026-11-03T07:09:31Z","abstract_url":"https://arxiv.org/abs/2611.04422v1","html_url":"https://arxiv.org/html/2611.04422v1","pdf_url":"https://arxiv.org/pdf/2611.04422v1.pdf","matched_keywords":["retrieval","3d","representation"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04418v1","title":"VidUEU-Agent: A Data-Curation Agent for Multimodal Understanding, Editing, and Unified Tasks","abstract":"The advancement of multimodal learning is heavily constrained by the scarcity and high annotation cost of high-quality instruction data. While raw videos offer an abundant and dynamic source of visual knowledge, transforming them into precise instruction data remains highly challenging. To bridge this gap, we present VidUEU-Agent, an automated pipeline that synthesizes instruction data from raw videos for multimodal understanding, editing, and unified tasks. VidUEU-Agent follows a four-stage pipeline: it performs global perception to filter low-quality shots, mines keyframes and multimodal signals, constructs metadata and routes the metadata to synthesize instruction samples. More importantly, our agent framework can autonomously iterate the data distribution based on downstream training results, thereby optimizing data quality, balance, and training effectiveness. Scaling this pipeline, we construct VidUEU-100K, a large-scale dataset of 100K training samples spanning multiple domains and tasks, providing a robust foundation for developing comprehensive multimodal capabilities. Extensive experiments demonstrate that fine-tuning baseline models on VidUEU-100K yields significant and consistent performance gains across diverse representative benchmarks, validating the effectiveness of our proposed agent framework and dataset.","authors":["Tengju Ru","Weitong Lian","Zecong Tang","Lingyi Meng","Haoran Li","Zhejun Cui","Yichen Zhu","Hangshuo Cao","Qi Kang","Yechi Liu","Kaixuan Wang","Yu-Jie Yuan","Chunwei Wang","Yu Zhang","Bo Dai"],"published":"2026-11-03T07:02:55Z","updated":"2026-11-03T07:02:55Z","abstract_url":"https://arxiv.org/abs/2611.04418v1","html_url":"https://arxiv.org/html/2611.04418v1","pdf_url":"https://arxiv.org/pdf/2611.04418v1.pdf","matched_keywords":["video","agent","multimodal"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"},{"id":"2611.04416v1","title":"Efficient and Faithful High-Resolution Image Editing with Sparse Cross-Resolution Denoising","abstract":"Instruction-based image editors still primarily operate at 1K, whereas practical editing increasingly requires faithful 2K/4K outputs. Dense high-resolution adaptation preserves the editing trajectory but incurs expensive target-source attention; editing at 1K followed by external refinement is cheaper but can separate detail restoration from the editing trajectory. We introduce FLASH, a native high-resolution editor based on sparse cross-resolution denoising. A frozen 1K branch provides a semantic and structural anchor, while a target-resolution branch reconstructs local detail within the same Transformer. An asymmetric topology retains full 1K attention, guides high-resolution queries with spatially aligned low-resolution noisy-target states, and confines high-resolution target-reference interaction to local Halo neighborhoods. Resolution-specific diffusion-state mapping and spatial YaRN adapt the pretrained editor to larger grids. An optional, training-free progressive path replaces early high-resolution denoising with a 1K prefix and completes refinement in the same editor. On VINS-4KEval, the direct model achieves the strongest structural fidelity among the compared methods at both 2K and 4K. A separate 4K forward benchmark with R = 1 records 4.2x faster total forward execution and 25.3x faster attention than dense target-reference attention. Progressive inference reduces end-to-end 4K latency by 30.5%, with a modest quality cost.","authors":["Maosen Zhao","Xianfang Zeng","Pengtao Chen","Peng Ye","Gang Yu","Jiayuan Fan","Tao Chen"],"published":"2026-11-03T06:58:26Z","updated":"2026-11-03T06:58:26Z","abstract_url":"https://arxiv.org/abs/2611.04416v1","html_url":"https://arxiv.org/html/2611.04416v1","pdf_url":"https://arxiv.org/pdf/2611.04416v1.pdf","matched_keywords":["diffusion"],"source_used":"abstract","source_text_chars":0,"summary":null,"first_seen_at":"2026-11-04T07:10:12+00:00","last_seen_at":"2026-11-04T07:10:12+00:00"}],"tracked_paper_count":68,"storage_mode":"latest_overwrite"}};
